#       называется SPAN и приходит из паспорта. Литерал «255» при этом чаще
#       значил не размер, а ПОСЛЕДНИЙ ИНДЕКС, а «254.999» — последнюю точку, где
#       билинейная выборка ещё имеет соседа справа: разница в единицу, и её
#       нельзя было увидеть, пока оба числа выглядели как «256 плюс-минус».
#   (3) РЕКА СТАЛА СПИСКОМ. Формат .relief держал несколько [river] с самого
#       начала (движок читает секции подряд), а генератор умел ровно одну — и
#       у второго же города с двумя рукавами это вылезло бы посадкой моста.
#       Все меры реки (river_dist, river_taper, water_at, in_channel) теперь
