#   (4) ТОЧКИ ПРИТЯЖЕНИЯ СТАЛИ РЕЦЕПТАМИ МЕСТА. Было 488 строк про конкретные
#       Гилдергрин, рынок и двор замка; стало десять МЕХАНИЗМОВ (мощёный круг,
