#       ПАРАМЕТРЫ тех же механизмов, а не новый код.
#   (5) ОЧЕРЁДНОСТЬ ВЫЗОВОВ — ЧАСТЬ КОНТРАКТА, и это стоило отдельного
#       усилия. Порядок house()/place()/lay() задаёт порядок СТРОК в файле,
