#       ядро, жизнь, огонь, убранство, терраса), и оркестратор проходит фазы
#       в том же порядке, в каком их звал прежний main(). Иначе байт-в-байт
#       недостижимо в принципе, как бы ни совпадала геометрия.
# - 24:08:2026 - 14:05:00: ШАПКА СЦЕНЫ СТАЛА ПАРАМЕТРОМ write_scene (просьба
#   epoch-i15, зона И15 «интерьеры-локации»). Довод его, и он точный: у
#   интерьерной сцены шапка отличается СОСТАВОМ, а не значениями — нет relief,
#   нет world_span_m города, свой [air] и несколько [spawn]. Функция, которая
#   печатает шапку внутри себя, годна ровно для одного вида сцен, а всё тело
#   ниже шапки — общее, и делить его копией было бы дороже, чем передать
#   десять строк параметром. Город зовёт city_header(); выпуск проверен —
#   whiterun.scene побайтово тот же.
import importlib
import json
import math
import os
import re
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

# --- ПАСПОРТ ГОРОДА: ДАННЫЕ ПРИХОДЯТ СНАРУЖИ ---------------------------------
# Имена ниже — ГЛОБАЛЬНЫЕ ИМЕНА МОДУЛЯ, и связывает их load_city(). Так сделано
# не из лени: механизмов здесь три тысячи строк, они писались против этих имён
# и против них же отлажены, а любая передача паспорта параметром через сотню
# функций была бы правкой каждой из них — то есть ровно тем редизайном,
# которого волна И1 обязана избежать. Паспорт выбирается ОДИН РАЗ на процесс:
# двух городов в одном прогоне не бывает, у каждого своя карта.
CITY = None      # модуль паспорта
PLAN = None      # чертёж города (JSON)
# ИМЕНА ПАСПОРТА ОБЪЯВЛЕНЫ ЗДЕСЬ, ХОТЯ ЗНАЧЕНИЯ ИМ ДАЁТ load_city(). Без этого
# списка они существовали бы только внутри globals()[...] — то есть были бы
# невидимы и читателю, и любому линтеру, а «невидимо» и «нет» неотличимы, пока
# не упадёт прогон. Заодно это ЕДИНСТВЕННОЕ место, где написано, что генератор
# спрашивает у паспорта: новый город собирается по этому списку.
LIGHT = KIND = FIXED_KINDS = GAP_M = MOVE_CAP = None
FLOOR = FURN = HEARTH_SHADOW = HEARTH_COLOR = None
TREE = BUSH_KINDS = BUSH_R = FLOWER_KINDS = CITY_FLOWER_SCALE = None
YARD_KINDS = YARD_SKIP = YARD_KIT = YARD_KIT_WIDE = YARD_WIDE_M = None
HOUSE_PAD_DROP = HOUSE_PAD_FEATHER = None
FOOT_CLEAR = FOOT_BURY = FOOT_OUT = FOOT_SEG = FOOT_TH = FOOT_MAX = None
STOOP_W = STOOP_MIN = STOOP_MAX = None
LAMP_PITCH = LAMP_ROADS = AXIS_ROAD = AXIS_FIRE_NODES = None
SIZE_CHUNKS = PLACES = INTERIORS = None
GROUND_CORE_CLS = GROUND_EDGE_CLS = GROUND_FADE_M = GROUND_EDGE_P = None
GROUND_GATE_R = GROUND_STOOP_R = GROUND_WALL_BAND = None
OUT = HEIGHTS_PATH = NATURAL_PATH = RIVERS = None
SPAN = 256       # сторона карты в клетках сетки высот; перебивается паспортом
LAST = SPAN - 1  # последний индекс сетки — им пользуются все клипы
EDGE = SPAN - 1.001   # последняя точка, у которой у билинейной выборки есть
                      # сосед справа (было 254.999 при SPAN 256)

def load_city(name):
    """Связывает паспорт с глобальными именами модуля. Зовётся ПЕРВОЙ строкой
    main() и ничего, кроме связывания и чтения чертежа, не делает."""
    global CITY, PLAN, SPAN, LAST, EDGE, OUT, HEIGHTS_PATH, NATURAL_PATH, _H
    global RING, RIVERS, PLAZA_RECTS, HOUSE_PAD_DROP
    CITY = importlib.import_module("cities." + name)
    PLAN = json.load(open(os.path.join(ROOT, CITY.PLAN_PATH), encoding="utf-8"))
    SPAN = int(CITY.SPAN)
    LAST = SPAN - 1
    EDGE = SPAN - 1.001
    for key in ("LIGHT", "KIND", "FIXED_KINDS", "GAP_M", "MOVE_CAP",
                "FLOOR", "FURN", "HEARTH_SHADOW", "HEARTH_COLOR",
                "TREE", "BUSH_KINDS", "BUSH_R", "FLOWER_KINDS",
                "CITY_FLOWER_SCALE", "YARD_KINDS", "YARD_SKIP", "YARD_KIT",
                "YARD_KIT_WIDE", "YARD_WIDE_M", "HOUSE_PAD_DROP",
                "HOUSE_PAD_FEATHER", "FOOT_CLEAR", "FOOT_BURY", "FOOT_OUT",
                "FOOT_SEG", "FOOT_TH", "FOOT_MAX", "STOOP_W", "STOOP_MIN",
                "STOOP_MAX", "LAMP_PITCH", "LAMP_ROADS", "AXIS_ROAD",
                "AXIS_FIRE_NODES", "SIZE_CHUNKS", "GROUND_CORE_CLS",
                "GROUND_EDGE_CLS", "GROUND_FADE_M", "GROUND_EDGE_P",
                "GROUND_GATE_R", "GROUND_STOOP_R", "GROUND_WALL_BAND",
                "PLACES", "INTERIORS"):
        globals()[key] = getattr(CITY, key)
    # ...и РУКИ ЗАМЕРА поверх паспорта. Дверь одна на все города, поэтому имя
    # у неё общее (DFN_CITY_*), а старое имя WHITERUN_* принимается наравне:
    # в шапке записан полный прогон командами, и он обязан работать дословно.
    HOUSE_PAD_DROP = float(env("PAD_DROP", str(CITY.HOUSE_PAD_DROP)))
    OUT = os.environ.get("DFN_GEN_OUT", name)
    HEIGHTS_PATH = env("HEIGHTS", f"/tmp/{name}_heights.txt")
    NATURAL_PATH = env("NATURAL", f"/tmp/{name}_natural.txt")
    _H = None
    if os.path.exists(HEIGHTS_PATH):
        _H = [[float(v) for v in line.split()]
              for line in open(HEIGHTS_PATH, encoding="utf-8")
              if not line.startswith("#")]
    # РУСЛО — СПИСОК. Чертёж Вайтрана держит одну реку двумя ключами верхнего
    # уровня; чертёж следующего города вправе объявить их списком. Обе формы
    # сводятся здесь к одной, и дальше генератор знает только список.
    if "rivers" in PLAN:
        RIVERS = [{"pts": [tuple(p) for p in r["pts"]],
                   "half_w": float(r["half_w"])} for r in PLAN["rivers"]]
    elif "river" in PLAN:
        RIVERS = [{"pts": [tuple(p) for p in PLAN["river"]],
                   "half_w": float(PLAN["river_half_w"])}]
    else:
        RIVERS = []
    # ПРЯМОУГОЛЬНИКИ ПЛОЩАДЕЙ. Дворовый клаттер, бордюр и отодвиг от дорог
    # спрашивают «это площадь?» — раньше через MRX/MRZ рынка, единственной
    # площади единственного города. Список объявляют МЕСТА паспорта.
    PLAZA_RECTS = [tuple(plan_ref(p["rect"])) for p in PLACES
                   if p.get("plaza")]
    RING = _ring_build()


def env(key, default=None):
    """Дверь замера: DFN_CITY_<KEY>, иначе прежнее WHITERUN_<KEY>."""
    return os.environ.get("DFN_CITY_" + key,
                          os.environ.get("WHITERUN_" + key, default))

def plan_ref(v):
    """Значение паспорта, ссылающееся в чертёж: строка «market.rect» читается
    как PLAN["market"]["rect"], всё остальное отдаётся как есть. Паспорт —
    данные, и ссылка на чертёж в нём обязана быть данными, а не кодом."""
    if not isinstance(v, str):
        return v
    node = PLAN
    for part in v.split("."):
        node = node[part]
    return node

# --- ИМЯ ВЫПУСКА: DFN_GEN_OUT ------------------------------------------------
# Боевые файлы города (<город>.scene/.relief/.map) — ОБЩИЙ предмет: по ним
# ходит критик, их открывает владелец. Пока идёт волна правок, перезапись
# боевого выпуска отнимает у смотрящего предмет прямо под ногами, а его отчёт
# начинает описывать город, которого уже нет. Поэтому имя выпуска — параметр:
#     DFN_GEN_OUT=whiterun-dev python3 tools/gen_city.py whiterun
# кладёт assets/scenes/whiterun-dev.scene(+.relief) и
# assets/maps/houses/whiterun-dev.map; смотреть — DFN_OPEN_MAP=houses/whiterun-dev.
# Умолчание — ИМЯ ГОРОДА, и оно оставлено НАМЕРЕННО: боевая перегенерация не
# должна требовать помнить лишнее слово, а вот черновая — должна называть себя.
# Связывается в load_city().

# --- ПОЛНЫЙ ПРОГОН: ТРИ ЗАМЕРА, А НЕ ОДИН ЗАПУСК -----------------------------
# Записано командами, потому что два из трёх файлов, от которых зависит вся
# посадка, ДОЛГО были снимками разовой руки, и оба врали молча: дамп высот до
# 24.08 (об этом ниже в шапке) и НАТУРАЛЬНАЯ ЗЕМЛЯ до 23.08 (расхождение со
# свежим замером доходило до 0.481 м — то есть на столько врал весь рельеф).
# Прибор probe_ground собирается по строке из своей шапки.
#
#   # 1. НАТУРАЛЬНАЯ ЗЕМЛЯ: выпуск без реки и без дельт -> замер по сцене
#   # (SPAN — сторона карты из паспорта, у Вайтрана 256)
#   DFN_CITY_BARE=1 DFN_GEN_OUT=whiterun-bare python3 tools/gen_city.py whiterun
#   python3 -c 'print("\n".join(f"{x} {z}" for z in range(256) for x in range(256)))' \
#       | <scratch>/probe_ground assets/scenes/whiterun-bare.scene \
#       | python3 -c 'import sys;v=[l.strip() for l in sys.stdin];\
#print("# whiterun NATURAL, row per z, col per x, step 1m");\
#[print(" ".join(v[z*256:(z+1)*256])) for z in range(256)]' > /tmp/whiterun_natural.txt
#
#   # 2. ДВА ПРОХОДА: первый строит поле высот, второй на нём садится
#   for i in 1 2; do DFN_CITY_WRITE_HEIGHTS=/tmp/whiterun_heights.txt \
#       python3 tools/gen_city.py whiterun; done
#
# Прежние имена дверей (WHITERUN_BARE, WHITERUN_WRITE_HEIGHTS, ...) продолжают
# работать наравне с DFN_CITY_* — см. env(): в этой шапке записан полный
# прогон командами, и он обязан оставаться дословно исполнимым.
#
# Пункт 1 повторять, когда менялся worldgen или стенд; пункт 2 — каждый раз.
# Пропустить пункт 1 нельзя МОЛЧА: сцена соберётся, приёмки будут зелёными, а
# дома уедут в землю ровно на дрейф натуральной земли.

H = []   # [house]
P = []   # [place]
LIGHTS = []   # [light]

def house(file, x, y, z, yaw_deg, note):
    H.append((f"assets/houses/{file}", x, y, z, math.radians(yaw_deg), note))

def place(obj, x, y, z, yaw_deg=0.0, note=None, scale=1.0):
    P.append((obj, x, y, z, math.radians(yaw_deg), note, scale))

# ПАЛИТРА ГОРОДСКОГО ОГНЯ — В ПАСПОРТЕ (ключ LIGHT): у каждого города свой
# характер огня, и разбор её по типам («жаровня, горн, очаг, фонарь-столб,
# фонарь у двери, огонь сквера») там же. Здесь только правило: числа берутся
# из ОДНОЙ таблицы по имени типа, а не пишутся у каждого вызова.

def _light_jitter(x, z):
    """Экземплярная дрожь огня из позиции (круг 6: «19 надверных фонарей все
    бит-в-бит — ни джиттера радиуса, ни разброса температуры»). Хэш координат,
    не random: две сборки одной руки дают побайтово одну сцену."""
    h1 = math.modf(abs(math.sin(x * 12.9898 + z * 78.233)) * 43758.5453)[0]
    h2 = math.modf(abs(math.sin(x * 39.3467 + z * 11.135)) * 24634.6345)[0]
    h3 = math.modf(abs(math.sin(x * 26.6519 + z * 41.741)) * 61234.8123)[0]
    return h1, h2, h3

def light(x, y, z, color, radius, note, shadow=False, interior=False, room=None,
          soft=0.0, flick=0.0):
    LIGHTS.append((x, y, z, color, radius, shadow, note, interior, room, soft,
                   flick))

def lamp(kind, x, y, z, note, radius=None, shadow=None, interior=False, room=None):
    """Огонь ИМЕНОВАННОГО ТИПА. Числа берутся из одной таблицы, а не пишутся у
    каждого вызова: разнообразие света — это шесть выдержанных типов, а не
    тридцать разных чисел, которые через неделю никто не сведёт. Поверх типа —
    экземплярная дрожь из позиции: яркость ±15%, радиус ±10%, теплота лёгким
    сдвигом зелёного/синего. Тип держит характер, экземпляр — лицо."""
    col, rad, soft, flick, wants_shadow = LIGHT[kind]
    h1, h2, h3 = _light_jitter(x, z)
    bright = 0.85 + 0.30 * h1
    col = (min(col[0] * bright, 1.0),
           min(col[1] * bright * (0.94 + 0.12 * h3), 1.0),
           min(col[2] * bright * (0.88 + 0.24 * h3), 1.0))
    rad_base = radius if radius is not None else rad
    light(x, y, z, col, rad_base * (0.90 + 0.20 * h2), note,
          shadow=wants_shadow if shadow is None else shadow,
          interior=interior, room=room, soft=soft,
          flick=flick * (0.8 + 0.4 * h1))

# --- сетка высот двухпроходного цикла (gen -> dump_heights -> gen) ----------
# Путь и чтение — в load_city(): у каждого города свой дамп.
_H = None

def ground(x, z):
    if _H is None:
        return None
    xi = min(max(x, 0.0), EDGE)
    zi = min(max(z, 0.0), EDGE)
    x0, z0 = int(xi), int(zi)
    fx, fz = xi - x0, zi - z0
    r0, r1 = _H[z0], _H[z0 + 1]
    return ((r0[x0]*(1-fx) + r0[x0+1]*fx) * (1-fz)
            + (r1[x0]*(1-fx) + r1[x0+1]*fx) * fz)

def sit(x, z, fallback, half=3.5):
    gs = [ground(x+dx, z+dz) for dx, dz in
          ((0,0),(half,half),(half,-half),(-half,half),(-half,-half))]
    gs = [g for g in gs if g is not None]
    return fallback if not gs else min(gs) - 0.05

def rect_points(cx, cz, w, d, yaw_deg, n=5):
    """Сетка n x n по ПОВЁРНУТОМУ пятну здания."""
    c = math.cos(math.radians(yaw_deg))
    sn = math.sin(math.radians(yaw_deg))
    out = []
    for i in range(n):
        lx = (-0.5 + i/(n-1)) * w
        for j in range(n):
            lz = (-0.5 + j/(n-1)) * d
            out.append((cx + lx*c + lz*sn, cz - lx*sn + lz*c))
    return out

def sit_rect(cx, cz, w, d, yaw_deg, fallback):
    """Посадка по МИНИМУМУ ПЯТНА, и пятно берётся повёрнутым. Прежняя проба
    «центр плюс четыре угла квадрата half=max(w,d)/2» для замка 26.6х14
    щупала землю в 18 м от центра — за кромкой замкового плато, и находила
    там 25 вместо 36: замок стоял закопанным по конёк одиннадцать метров."""
    gs = [g for g in (ground(px, pz) for px, pz in rect_points(cx, cz, w, d, yaw_deg))
          if g is not None]
    return fallback if not gs else min(gs) - 0.05

# KIND (kind чертежа -> рецепт полки) — В ПАСПОРТЕ: у каждого города свои
# дома. ГАБАРИТ рецепта тут ни при чём и в таблице не пишется вовсе — он
# снимается с самой детали (recipe_box ниже), потому что кузница перепекает
# рецепты каждую волну и любая переписанная цифра — будущая ложь.

# =============================================================================
# ЕДИНСТВЕННЫЙ ИСТОЧНИК ГАБАРИТОВ: МАНИФЕСТ ПОЛКИ (волна И2)
# =============================================================================
# ДО 24.08 ФОРМАТ .dfh РАЗБИРАЛИ ДВА РАЗБОРЩИКА: C++ (read_house, кузница и
# движок) и питонский — здесь, пять функций подряд. Второй разборщик формата
# это будущее расхождение по определению: он не участвует ни в одной выпечке,
# и первое же поле, добавленное кузницей, он молча прочитает по-старому.
# Кузница (волна И2) пишет assets/houses/INDEX.txt после каждой выпечки, ПО
# ВСЕЙ ПОЛКЕ. Отсюда берутся: габарит графа, верх тела, пятно стен, точка и
# ось двери, низ балок, отметка пола, а также ростовки семейств.
# ЧЕГО В МАНИФЕСТЕ НЕТ И ПОЧЕМУ ДВА РАЗБОРЩИКА ОСТАЛИСЬ: гнутому прогону стены
# нужны ХОРДА И ПОВОРОТ его собственной оси (ломаная стенок height=6.00), а
# мосту — ПРОФИЛЬ НАСТИЛА (шесть наклонных плит thickness=0.30). Ни то, ни
# другое из габарита не выводится: это внутренняя геометрия детали, а не её
# коробка. arc_kit() и bridge_deck() поэтому читают .dfh; сказано вслух, чтобы
# «единственный источник» не звучал шире, чем он есть.
# ФОЛБЭК ОСТАВЛЕН НАМЕРЕННО: нет манифеста (свежий клон, чужая ветка) — читаем
# .dfh, как читали. DFN_CITY_NO_MANIFEST=1 — контрольная рука: она гоняет
# ОБА источника из одного бинарника, и без неё «числа совпадают» нечем
# доказать, кроме письма.
_SHELF = None

def shelf(rec):
    """Строка манифеста полки для рецепта, или None."""
    global _SHELF
    if _SHELF is None:
        _SHELF = {}
        path = os.path.join(ROOT, "assets/houses/INDEX.txt")
        if env("NO_MANIFEST") != "1" and os.path.exists(path):
            cols = None
            for line in open(path, encoding="utf-8"):
                if line.startswith("# columns:"):
                    cols = line.split(":", 1)[1].split()
                elif cols and line.strip() and not line.startswith("#"):
                    row = dict(zip(cols, line.split()))
                    _SHELF[row["file"]] = row
    return _SHELF.get(rec)

def _sh(row, key):
    """Число манифеста; «-» значит «этого у детали нет»."""
    v = row.get(key, "-")
    return None if v == "-" else float(v)

_REC = {}

def recipe_box(rec):
    """ГАБАРИТ И ДВЕРЬ РЕЦЕПТА СНИМАЮТСЯ С САМОГО .dfh, а не пишутся в
    таблицу: (центр габарита в локали, w, d, ось двери, вынос двери от
    центра). Таблица чисел «на глаз» уже дала city-house-s 7х7 при факте
    4.5х6.0 и Йоррваскр на 4 м короче своего тела; кузница мебели к тому же
    перепекает рецепты каждую волну, и любая переписанная цифра — будущая
    ложь. ОСЬ ДВЕРИ ВАЖНА ОТДЕЛЬНО: put_house считал, что дверь всегда на
    стороне z=d, а у city-longhall она на x=w и у city-mill на x=0 — обе
    постройки стояли к своей улице глухой стеной, повёрнутые на 90 гр. от
    красной стрелки чертежа (Йоррваскр — одна из четырёх названных доминант
    гайда §11). Дверь узнаётся по атрибуту door=1; у ворот амбара его нет —
    им остаётся сторона z=d."""
    if rec in _REC:
        return _REC[rec]
    row = shelf(rec)
    if row is not None:
        gx0, gz0 = _sh(row, "gx0"), _sh(row, "gz0")
        gx1, gz1 = _sh(row, "gx1"), _sh(row, "gz1")
        w, d = gx1 - gx0, gz1 - gz0
        axis = row["door_axis"]
        if axis == "-":
            axis, off = "+Z", d/2
        else:
            off = _sh(row, "door_off")
        _REC[rec] = ((gx0+gx1)/2, (gz0+gz1)/2, w, d, axis, off)
        return _REC[rec]
    V, door = {}, None
    for line in open(os.path.join(ROOT, "assets/houses", rec), encoding="utf-8"):
        t = line.split()
        if not t:
            continue
        if t[0] == "vertex":
            V[t[1]] = (float(t[3]), float(t[5]))
        elif "door=1" in line:
            pts = [V[v] for v in t[2:] if v in V]
            if pts:
                door = (sum(p[0] for p in pts)/len(pts),
                        sum(p[1] for p in pts)/len(pts))
    xs = [p[0] for p in V.values()]
    zs = [p[1] for p in V.values()]
    cx, cz = (min(xs)+max(xs))/2, (min(zs)+max(zs))/2
    w, d = max(xs)-min(xs), max(zs)-min(zs)
    if door is None:
        axis, off = "+Z", d/2
    else:
        dxl, dzl = door[0]-cx, door[1]-cz
        if abs(dzl) >= abs(dxl):
            axis, off = ("+Z", dzl) if dzl > 0 else ("-Z", -dzl)
        else:
            axis, off = ("+X", dxl) if dxl > 0 else ("-X", -dxl)
    _REC[rec] = (cx, cz, w, d, axis, off)
    return _REC[rec]

_TOP = {}

def recipe_top(rec):
    """ВЕРХ ТЕЛА РЕЦЕПТА, замеренный, а не выписанный: у стенки .dfh верх
    лежит не на вершине, а на «вершина + height», и разница как раз та, из-за
    которой огонь оказывался ВНУТРИ своей же чаши (у очага вершины кончаются
    на 0.17, а борт лотка — на 0.38)."""
    if rec in _TOP:
        return _TOP[rec]
    row = shelf(rec)
    if row is not None:
        _TOP[rec] = _sh(row, "top")
        return _TOP[rec]
    V, top = {}, 0.0
    for line in open(os.path.join(ROOT, "assets/houses", rec), encoding="utf-8"):
        t = line.split()
        if not t:
            continue
        if t[0] == "vertex":
            V[t[1]] = float(t[4])
            top = max(top, V[t[1]])
        elif t[0] == "surface":
            h = 0.0
            for tok in t:
                if tok.startswith("height="):
                    h = float(tok.split("=")[1])
            ys = [V[v] for v in t[2:] if v in V]
            if ys:
                top = max(top, max(ys) + h)
    _TOP[rec] = top
    return top

def yaw_for_door(axis, dx, dz):
    """yaw сцены, при котором наружная нормаль двери рецепта смотрит в (dx,dz).
    Конвенция: +X_лок = (cos, -sin), +Z_лок = (sin, cos)."""
    if axis == "+Z":
        return math.degrees(math.atan2(dx, dz)) % 360.0
    if axis == "-Z":
        return math.degrees(math.atan2(-dx, -dz)) % 360.0
    if axis == "+X":
        return math.degrees(math.atan2(-dz, dx)) % 360.0
    return math.degrees(math.atan2(dz, -dx)) % 360.0

# УБРАНСТВО (FLOOR, FURN, HEARTH_SHADOW) — В ПАСПОРТЕ: раскладка мебели это
# то, чем город живёт, и у второго города она будет другой. Здесь остаётся
# МЕХАНИЗМ (furnish ниже): локальные точки раскладки поворачиваются той же
# матрицей сцены, что и сам дом, и садятся на верх ПОЛОВОЙ ПЛИТЫ рецепта.
# Пламя стоит НАД верхом своей чаши, а не в ней: и у очага, и у жаровни точка
# света сидела внутри тела светильника, отчего у его ног было темнее, чем в
# трёх метрах ([N18], [N14]). Высота чаши не пишется числом — снимается
# recipe_top с самого .dfh; здесь только «на сколько пламя выше дров».
HEARTH_FLAME = 0.55   # над бортом лотка очага
HEARTH_TRAY = 0.20    # верх плиты дна лотка (замер: плоскость 0.17 + пол-0.06)
# У ЖАРОВНИ ПОДЪЁМ ЗАМЕРЕН И ОТВЕРГНУТ. Заказ был «поднять на 0.40 над чашей»,
# и на глаз это верно — но ночной кадр подножия (та же поза, те же часы 0.95,
# арма ДО и ПОСЛЕ) даёт медиану 36.3 против 34.5: свет, отодвинутый от земли
# ещё на четверть метра, светит ей СЛАБЕЕ, а не сильнее. Тени у жаровни нет
# (кубовых слотов два, оба у залов), значит и затенять подножие нечему —
# «темнее у ног» на этом столбе не воспроизводится вовсе. Оставлено 0.15 над
# макушкой: пламя над чашей, и ни сантиметра дальше от того, что освещает.
BRAZIER_LIGHT = 2.75  # огонь жаровни над землёй: под него кузница подобрала
                      # чашу (пламя рецепта 2.30..2.92); подъём на 0.40 уже
                      # отвергнут замером — подножие стало ТЕМНЕЕ на 5%
BRAZIER_CLEAR = 0.70  # чистое место под жаровню: полтела (0.36) плюс ладонь
BRAZIER_BANK = 7.0    # от осевой русла: half_w 3.6 + сведение берега 3.0 + тело
BRAZIER_FLAT = 0.25   # перепад по пятну жаровни: круче — это срез, а не место
BRAZIER_APART = 6.0   # ближе двух огней в шести метрах не бывает: это один огонь
BRAZIER_AT = []       # где уже стоят жаровни — иначе «мостовая» садится к «воротам»

# --- СТОЛБ ДЕРЖИТ БАЛКУ, А НЕ СТОИТ РЯДОМ (претензия владельца 23.08:
# «опоры не упираются в потолок, который должны держать») -------------------
# Низ несомой балки снимается с .dfh: у перекрытия с меткой beams=1 плоскость
# задана вершинами, тело идёт симметрично на thickness/2 вниз. Замер по
# рецептам: длинный зал — балки 3.60 при поле 0.13, то есть держать надо
# 3.41; замок — 4.60 при поле 1.72 (2.81); большой дом — 3.42 при поле 0.645
# (2.72); храм — не перекрытие, а скат кровли (roof=1), его столбы держат
# конёк, а не балку.
# Столб один и жёсткий (furn-column, 2.60), растянуть его нечем: у [house] нет
# scale, в отличие от [place]. Поэтому здесь ВЫБОР ИЗ ВЫПЕЧКИ по замеру, как у
# маршей террасы: подходит вариант, у которого верх встаёт под балку в пределах
# COLUMN_FIT; не подходит ни один — столб НЕ СТАВИТСЯ, и об этом печатается
# вслух с числом. Столб, не достающий до балки, — не опора, а декорация,
# изображающая опору, и это ровно то, что владелец увидел.
COLUMN_FIT = 0.02        # порог владельца: верх столба = низ балки +-0.02
_COLKIT = None

def column_kit():
    """[(высота, файл)] всех вариантов furn-column из выпечки."""
    global _COLKIT
    if _COLKIT is None:
        _COLKIT = []
        for f in sorted(os.listdir(os.path.join(ROOT, "assets/houses"))):
            if re.match(r"furn-column(-h\d+)?\.dfh$", f):
                _COLKIT.append((recipe_top(f), f))
    return _COLKIT

_BEAM = {}

def beam_under(rec):
    """Низ ближайшей несомой балки над полом рецепта (мировая высота от
    origin), или None, если перекрытия у рецепта нет."""
    if rec in _BEAM:
        return _BEAM[rec]
    floor = FLOOR.get(rec, 0.12)
    row = shelf(rec)
    if row is not None:
        # МАНИФЕСТ ОТДАЁТ ВСЕ БАЛКИ СПИСКОМ, А НЕ ОДНУ, и это верно: порог
        # «выше пола + 1.8» опирается на ПОЛ, а пол — число города (таблица
        # FLOOR паспорта), и решать его за генератор кузница не может.
        bs = row.get("beams", "-")
        vals = [] if bs == "-" else [float(v) for v in bs.split(",")]
        _BEAM[rec] = min((v for v in vals if v > floor + 1.8), default=None)
        return _BEAM[rec]
    V, best = {}, None
    for line in open(os.path.join(ROOT, "assets/houses", rec), encoding="utf-8"):
        t = line.split()
        if not t:
            continue
        if t[0] == "vertex":
            V[t[1]] = float(t[4])
        elif t[0] == "surface" and "beams=1" in line:
            th = 0.0
            for tok in t:
                if tok.startswith("thickness="):
                    th = float(tok.split("=")[1])
            ys = [V[v] for v in t[2:] if v in V]
            if not ys:
                continue
            under = min(ys) - th/2
            if under > floor + 1.8 and (best is None or under < best):
                best = under
    _BEAM[rec] = best
    return best

def loc_to_world(ox, oz, yaw_deg, lx, lz):
    """Локальная точка детали -> мир. Конвенция сцены: +X_лок = (cos, -sin),
    +Z_лок = (sin, cos), начало детали в углу."""
    c = math.cos(math.radians(yaw_deg))
    sn = math.sin(math.radians(yaw_deg))
    return (ox + lx*c + lz*sn, oz - lx*sn + lz*c)

def furnish(rec, ox, oy, oz, yaw_deg, note):
    """Мебель дома: локальные позиции раскладки поворачиваются той же
    матрицей сцены, что и сам дом, и садятся на ВЕРХ ПОЛОВОЙ ПЛИТЫ этого
    рецепта. Очаг заодно зажигает точечный свет."""
    items = FURN.get(rec)
    if not items:
        return
    fy = oy + FLOOR.get(rec, 0.12)
    under = beam_under(rec)
    for ff, lx, lz, lyaw in items:
        if ff == "furn-column.dfh" and under is not None:
            # нужная длина — от пола до низа балки
            need = under - FLOOR.get(rec, 0.12)
            fit = [(abs(h - need), h, f) for h, f in column_kit()]
            fit.sort()
            if not fit or fit[0][0] > COLUMN_FIT:
                COLUMN_SHORT.append((rec, need, fit[0][1] if fit else 0.0, note))
                continue
            ff = fit[0][2]
        mx, mz = loc_to_world(ox, oz, yaw_deg, lx, lz)
        house(ff, mx, fy, mz, (yaw_deg + lyaw) % 360.0, "убранство: " + note)
        FURN_Y.append((fy, fy, ff + " в " + note))
        if ff == "furn-hearth.dfh":
            # ДРОВА В ЛОТОК (выпечка кузни-2, furn-fire 0.60x0.78x0.60). До неё
            # очаг был пустым ящиком с точкой света над ним: огонь в кадре
            # существовал только как пятно на стенах. Посадка снята с обоих
            # рецептов, а не подобрана: у очага дно лотка — плита e6 (плоскость
            # 0.17, толщина 0.06, верх 0.20), лоток изнутри 1.00x1.00 от 0.20
            # до 1.20, а у костра подошва поленницы на 0.04 и габарит 0.60 —
            # значит центр лотка это локальные (0.40, 0.40) и высота +0.20.
            # Пламя костра кончается на 0.78 над своей подошвой, то есть на
            # 0.98 над низом очага, а точка света стоит на 0.93 (борт 0.38 +
            # HEARTH_FLAME) — свет оказывается ВНУТРИ пламени, а не над ним.
            fx2, fz2 = loc_to_world(ox, oz, yaw_deg, lx + 0.40, lz + 0.40)
            house("furn-fire.dfh", fx2, fy + HEARTH_TRAY, fz2,
                  (yaw_deg + lyaw + 37) % 360.0, "огонь очага: " + note)
            # ПЛАМЯ НАД ДРОВАМИ, А НЕ В ЛОТКЕ (претензии [N18]+[N4]: «зал замка
            # в полдень 25.9/255 при радиусе 13»). Огонь стоял на 0.55 над
            # ПОЛОМ, а борт лотка очага кончается на 0.38 (замер recipe_top:
            # вершины идут до 0.17, стенки e2-e5 добавляют height=0.24 от
            # 0.14) — источник висел в 0.17 над бортом СОБСТВЕННОГО ящика.
            # У очагов с теневым слотом (длинный зал и замок — им отданы оба
            # слота MAX_SHADOW_POINT_LIGHTS) этот борт ложится на пол кольцом
            # тени: при высоте h над полом и борте 0.38 на радиусе 0.7 тень
            # достаёт до r = 0.7*h/(h-0.38), то есть 2.26 м при h=0.55 — весь
            # пол у очага. На 0.55 НАД БОРТОМ (h=0.93) кольцо садится до
            # 1.18 м, и дальше него пол читается.
            hx, hz = loc_to_world(ox, oz, yaw_deg, lx + 0.70, lz + 0.70)
            # РАДИУС ОЧАГА — ПО РАЗМЕРУ ЗАЛА, А НЕ КОНСТАНТОЙ НА ВСЕ ДОМА
            # (претензия [N4]: очаг 4.6 м в зале 16 м — «оранжевая точка»,
            # дальняя стена в черноте). Правило координатора: 0.7 диагонали
            # помещения, габарит берётся у самого рецепта. Йоррваскр 16х8 ->
            # 12.5 м, рядовой дом 4.5х6 -> 5.2 м; правило переживёт новые
            # рецепты, подобранное число — нет.
            # Потолок 13 м: габарит рецепта — это ВСЯ постройка с крыльями и
            # портиком, а не зал. У замка 26.6х14 правило дало бы 21 м, и
            # очаг чадил бы во весь двор; 13 — чуть выше зала Йоррваскра,
            # самого длинного НАСТОЯЩЕГО помещения города.
            _cx, _cz, rw, rd, _a, _o = recipe_box(rec)
            rad = min(13.0, max(4.6, 0.7 * math.hypot(rw, rd)))
            # INTERIOR=1: свет гейтится небесной видимостью приёмника, иначе
            # очаг светит улице СКВОЗЬ КЛАДКУ — кубовую теневую карту получают
            # только два ближайших источника, остальные шесть шли с occl=1.0.
            # Порядок обязателен: поднять радиус до гейта значило бы утроить
            # утечку наружу.
            # КОРОБКА КОМНАТЫ (ключ room, движок 1f21b84): свет физически не
            # выходит за пятно помещения. Коробка у движка ОСЕВАЯ, а дома
            # повёрнуты — значит берём ОПИСАННЫЙ прямоугольник повёрнутого
            # пятна: полуразмеры (w|cos| + d|sin|)/2 и (w|sin| + d|cos|)/2.
            # ОГОВОРКА, которую надо знать: это пятно ВСЕЙ постройки, а не
            # зала. У длинного зала и замка есть крылья и портик, и для них
            # коробка выходит велика — очаг сможет светить собственному двору.
            # Урезать её числом «на глаз» я не стал: у меня всю волну правило
            # не сажать по неизмеренному, и оно дважды окупилось. Нужен зал —
            # нужен замер зала из кузницы.
            _c2 = abs(math.cos(math.radians(yaw_deg)))
            _s2 = abs(math.sin(math.radians(yaw_deg)))
            bcx, bcz = loc_to_world(ox, oz, yaw_deg, _cx, _cz)
            # КОРОБКА — ЭТО КОМНАТА, А НЕ ГАБАРИТ. Пятно рецепта обводит
            # НАРУЖНЫЕ грани, и коробка по нему включает саму кладку внутрь
            # освещаемого объёма: замер стенда дал 7.035% против 6.914% без
            # коробки, то есть стена продолжала течь, и чуть сильнее. Коробка
            # усаживается на ВСЁ, что лежит между огнём и наружной гранью:
            # свес кровли (габарит рецепта берётся ПО КОРПУСУ ВМЕСТЕ С
            # НАВЕСОМ, 0.4) + толщина стены (0.35-0.40 у city-house-l) +
            # кромка смягчения коробки в движке (0.3) = 1.10 на сторону.
            # Число не подобрано на глаз, а ПРОВЕРЕНО стендом §13: усадка 0.70
            # даёт 1.384% (maxch 45), усадка 1.10 — 0.000%, maxch 0, ровно
            # уровень нулевого контроля.
            ROOM_INSET = 1.10
            room = (bcx, bcz,
                    max(0.4, (rw*_c2 + rd*_s2)/2.0 - ROOM_INSET),
                    max(0.4, (rw*_s2 + rd*_c2)/2.0 - ROOM_INSET))
            lamp("hearth", hx, fy + recipe_top("furn-hearth.dfh") + HEARTH_FLAME,
                 hz, "очаг: " + note, radius=rad, shadow=rec in HEARTH_SHADOW,
                 interior=True, room=room)
# TREE (вид чертежа -> рецепты полки) — В ПАСПОРТЕ: это биом.

def door_dir(deg, door):
    """Мировое направление наружу от дверной стороны прямоугольника схемы."""
    base = {"S": (0, 1), "N": (0, -1), "E": (1, 0), "W": (-1, 0)}[door]
    r = math.radians(deg)
    return (base[0]*math.cos(r) - base[1]*math.sin(r),
            base[0]*math.sin(r) + base[1]*math.cos(r))

def house_frame(hs):
    """Геометрия посадки БЕЗ земли: (рецепт, центр тела, w, d, yaw, дверь).
    Отделена от put_house, потому что площадку под крупное здание надо
    спланировать в поле высот ДО того, как здание на неё сядет."""
    rec = KIND.get(hs["kind"], KIND[""])
    if rec is None:
        return None
    lcx, lcz, w, d, axis, off = recipe_box(rec)
    dx, dz = door_dir(hs["deg"], hs["door"])
    yaw = yaw_for_door(axis, dx, dz)
    # ПОСАДКА ДВЕРНОЙ ГРАНЬЮ: дверь реального дома встаёт туда, где дверная
    # грань схемного пятна (красная линия чертежа). Рост реального тела уходит
    # НАЗАД во двор — посадка центром выдвигала фасады на дороги (первый
    # прогон v5: 15 пересечений с полосами). Вынос двери от центра габарита
    # берётся у рецепта: у лавки её закрывает навес (2.0 вместо 4.0), у замка
    # зал сидит в глубине пятна (1.0 вместо 7.0).
    door_face = {"S": hs["d"]/2, "N": hs["d"]/2, "E": hs["w"]/2, "W": hs["w"]/2}[hs["door"]]
    fx = hs["x"] + dx * door_face
    fz = hs["z"] + dz * door_face
    ccx = fx - dx * off
    ccz = fz - dz * off
    return (rec, ccx, ccz, w, d, yaw, (fx, fz))

def nearest_on_roads(px, pz):
    best, pt = 1e9, (px, pz)
    for rd in PLAN["roads"]:
        for (x0,z0),(x1,z1) in zip(rd["pts"], rd["pts"][1:]):
            vx, vz = x1-x0, z1-z0
            L2 = vx*vx + vz*vz
            t = max(0.0, min(1.0, ((px-x0)*vx + (pz-z0)*vz) / L2))
            qx, qz = x0+vx*t, z0+vz*t
            dd = math.hypot(px-qx, pz-qz)
            if dd < best:
                best, pt = dd, (qx, qz)
    return pt

def push_off_roads(cx, cz, w, d, yaw, budget=8.0):
    """Отодвиг от полос дорог: тело пересекает полосу -> шаг по нормали ОТ
    ближайшей точки нарушающей дороги (двери мало, дорога бывает сбоку)."""
    moved = 0.0
    while moved < budget and any(rect_road_hit(cx, cz, w, d, yaw, rd)
                                 for rd in PLAN["roads"]):
        qx, qz = nearest_on_roads(cx, cz)
        nx, nz = cx - qx, cz - qz
        nl = math.hypot(nx, nz) or 1.0
        cx += nx / nl * 0.4
        cz += nz / nl * 0.4
        moved += 0.4
    return cx, cz

# ДОМ НЕ СТОИТ В КЛАДКЕ (претензия владельца 23.08: «несколько домов стоят в
# стене — стена сквозь дома»). Отодвиг от полос дорог у расстановки был с
# первого дня, а от ГОРОДСКОЙ СТЕНЫ — не было никогда: кольцо кладётся мимо
# PLACED, и для расстановки его просто нет. Правило то же, что у дороги:
# тело, попавшее в полосу, шагает по нормали ОТ неё, пока не отойдёт.
# ЗАПАС СЧИТАЕТСЯ ОТ КРИВОЙ, А НЕ ОТ КЛАДКИ, И ЭТО ВЫНУЖДЕННО: расстановка
# идёт ДО wall_ring (площадки под здания надо спланировать раньше, чем встанет
# стена), то есть осей построенных кусков ещё нет. Цепь отходит от кривой — на
# этом чертеже до 0.68 м, — и весь этот отход прибавляется к порогу, иначе
# дом, чистый по кривой, окажется в настоящей кладке.
RING_DEV = 0.70   # отход цепи кусков от кривой чертежа (замер wall_ring)
# ЗАПАС ДОМА ОТ КЛАДКИ — ЩЕЛЬ ФАСАДНОГО РЯДА, А НЕ ЧЕСТНЫЙ МЕТР ЗАМКА, и это
# не поблажка, а разные предметы. Владелец назвал метр ЗАМКУ («зазор честный
# >= 1 м»), а рядовому дому — только «стена не сквозь дом». Метр рядовому
# стоил бы города: замер свободных мест под тело кузницы (6.8x8.97) по всему
# южному кварталу при пороге 1.0+0.7 дал НОЛЬ клеток, при 0.35+0.7 — тоже
# ноль в её коридоре, потому что между полосой главной улицы и кладкой там
# меньше семи метров. Дом жмётся к городской стене — так и в жизни; смысл
# правила в том, чтобы кровля не росла ИЗ кладки.
RING_HOUSE_CLEAR = 0.35   # = GAP_M, та же ладонь, что между фасадами ряда

_RING_BODY = []      # плоский список точек осей ПОСТРОЕННОЙ кладки

def ring_probe():
    """Точки, по которым меряется щель до стены, и надбавка к порогу.
    По ПОСТРОЕННОЙ кладке (wall_ring уже прошла) — надбавки нет, мера точная;
    по кривой чертежа (стены ещё нет) — надбавка во весь отход цепи."""
    if RING_AXES:
        if not _RING_BODY:
            _RING_BODY.extend(p for ax in RING_AXES for p in ax)
        return _RING_BODY, 0.0
    return RING["pts"], RING_DEV

def ring_clear(cx, cz, w, d, yaw_deg):
    """Щель между пятном и кладкой (минус её полтолщины)."""
    pts, _dev = ring_probe()
    best = 1e9
    for px, pz in pts:
        if abs(px-cx) > 40.0 or abs(pz-cz) > 40.0:
            continue
        best = min(best, _rect_dist(px, pz, cx, cz, w, d, yaw_deg))
    return best - WALL_THICK/2

def wall_rect_of(rec, ccx, ccz, yaw):
    """Пятно СТЕН постройки в мире по центру её ГАБАРИТА: (cx, cz, w, d).
    Габарит обводит свес кровли, стены — нет, и разница у кузницы 0.8x0.97 м."""
    ox, oz = house_origin(rec, ccx, ccz, yaw)
    x0, z0, x1, z1 = recipe_wall_rect(rec)
    wcx, wcz = loc_to_world(ox, oz, yaw, (x0+x1)/2, (z0+z1)/2)
    return wcx, wcz, x1-x0, z1-z0

def push_off_ring(rec, cx, cz, w, d, yaw, budget=10.0):
    """Шаг ОТ кладки, пока ПЯТНО СТЕН не отойдёт на ладонь.
    МЕРИТСЯ ПЯТНО СТЕН, А ДВИГАЕТСЯ ГАБАРИТ, и разделение это не придирка:
    свес соломенной кровли над кладкой — карниз, стена в кладке — дефект (то
    же различие, каким мостовая отличает свес от стены). У кузницы габарит
    6.8x8.97 против стен 6.0x8.0, и требование ладони ОТ ГАБАРИТА выталкивало
    её на метр в проезжую часть главной улицы там, где стены стояли в 0.59 м
    от кладки, то есть чисто.
    ШАГ НЕ ПО ЧИСТОЙ НОРМАЛИ, А ПО ЛУЧШЕМУ ИЗ ДЕВЯТИ НАПРАВЛЕНИЙ, и это не
    украшение алгоритма: первый прогон отодвигал строго от кладки и загонял
    три дома НА ПОЛОСЫ УЛИЦ (check_layout: было 4 «на дороге», стало 7) —
    ровно та же болезнь, из-за которой отодвиг от дорог когда-то пришлось
    считать совместно, а не поодиночке. Стена и улица идут рядом, и уйти от
    одной, не встав на другую, почти всегда можно наискось."""
    wcx, wcz, ww, wd = wall_rect_of(rec, cx, cz, yaw)
    ddx, ddz = wcx - cx, wcz - cz
    out = _push_off_ring_rect(wcx, wcz, ww, wd, yaw, cx, cz, w, d, budget)
    return out[0] - ddx, out[1] - ddz

def _push_off_ring_rect(cx, cz, w, d, yaw, gx, gz, gw, gd, budget):
    """Ходьба пятна стен; полосы дорог проверяются по ГАБАРИТУ, смещённому
    так же (кровля над проезжей частью — тоже дефект)."""
    ddx, ddz = gx - cx, gz - cz
    need = RING_HOUSE_CLEAR + ring_probe()[1]
    # ПОЛ И ЦЕЛЬ — РАЗНЫЕ ЧИСЛА, И БЕЗ ЭТОГО ДЕЛЕНИЯ ДВА ОТОДВИГА ЗАЦИКЛИВАЮТСЯ.
    # Цель — ладонь сверх отхода цепи; ПОЛ — сам отход, то есть ровно та
    # граница, за которой кладка гарантированно не входит в тело. Кузница
    # юго-восточного квартала стоит в коридоре, где между полосой улицы и
    # кладкой на её тело остаётся 1.4 м свободы: цель и отодвиг от дороги
    # перебрасывали её туда-сюда, и последнее слово (у отодвига от кладки)
    # оставляло её метром НА проезжей части. Достигнув пола, отодвиг больше
    # не лезет на дорогу — дом жмётся к стене, как ему и положено.
    floor = ring_probe()[1]
    moved = 0.0
    while moved < budget and ring_clear(cx, cz, w, d, yaw) < need:
        near = min(RING["pts"], key=lambda p: math.hypot(p[0]-cx, p[1]-cz))
        nx, nz = cx - near[0], cz - near[1]
        nl = math.hypot(nx, nz) or 1.0
        nx, nz = nx/nl, nz/nl
        here = ring_clear(cx, cz, w, d, yaw)
        best = None
        for turn in (0.0, 25.0, -25.0, 50.0, -50.0, 75.0, -75.0, 90.0, -90.0):
            c, s = math.cos(math.radians(turn)), math.sin(math.radians(turn))
            ux, uz = nx*c - nz*s, nx*s + nz*c
            qx, qz = cx + ux*0.4, cz + uz*0.4
            gain = ring_clear(qx, qz, w, d, yaw) - here
            if gain < -0.02:
                continue                    # в кладку — не шаг
            # ХОД ВДОЛЬ СТЕНЫ РАЗРЕШЁН (turn = ±90, gain ~ 0), и без него
            # правило неполно: у кузницы юго-восточного квартала коридор между
            # полосой главной улицы и кладкой ЗАКРЫТ НАГЛУХО на всём отрезке
            # z=164..173 (замер картой свободных мест), и чистый отодвиг «от
            # стены» может только вытолкнуть её на проезжую часть. Выход есть
            # ВДОЛЬ стены — на север, где коридор открывается; поэтому шаг
            # выбирается сперва по числу задетых полос, и лишь потом по тому,
            # насколько он отодвигает от кладки.
            hits = sum(1 for rd in PLAN["roads"]
                       if rect_road_hit(qx+ddx, qz+ddz, gw, gd, yaw, rd))
            key = (hits, -gain, abs(turn))
            if best is None or key < best[0]:
                best = (key, qx, qz)
        if best is None:
            cx, cz = cx + nx*0.4, cz + nz*0.4
        elif (best[0][0] > 0 and here >= floor
              and not any(rect_road_hit(cx+ddx, cz+ddz, gw, gd, yaw, rd)
                          for rd in PLAN["roads"])):
            break                        # пол взят, дальше только на дорогу
        else:
            cx, cz = best[1], best[2]
        moved += 0.4
    return cx, cz

def half_proj(w, d, yaw_deg, ux, uz):
    """Половина тела в направлении (ux,uz) — опорная функция прямоугольника."""
    c = math.cos(math.radians(yaw_deg))
    sn = math.sin(math.radians(yaw_deg))
    return abs(c*ux - sn*uz) * w/2 + abs(sn*ux + c*uz) * d/2

# FIXED_KINDS (доминанты, неподвижные в разведении), GAP_M (норматив щели
# фасадного ряда) и MOVE_CAP (потолок смещения от схемного пятна) — В
# ПАСПОРТЕ: это правила застройки ЭТОГО города, а не устройство расталкивания.

def resolve_frames():
    """ТЕЛА ГОРОДА, РАЗВЕДЁННЫЕ МЕЖДУ СОБОЙ. Отодвиг от дорог считался
    каждым домом в одиночку и загонял его в соседа: лавка юга рынка уехала
    на 4 м в другую лавку, амбар — на 7 м в ферму (замер щелей: минимум
    -5.8 м, четыре наложения). Здесь тела расталкиваются совместно, до
    норматива щели, с потолком смещения от схемного пятна; после каждого
    круга — повторный отодвиг от полос. Один и тот же список используют и
    планировка площадок, и расстановка: считать раму дважды нельзя, второй
    счёт видел бы уже занятые места и давал другой ответ."""
    fr = []
    for hs in PLAN["houses"]:
        f = house_frame(hs)
        if f is None:
            continue
        rec, ccx, ccz, w, d, yaw, door = f
        # ДОМИНАНТА НЕ УСТУПАЕТ ДОРОГЕ. Улицы этого чертежа упираются в неё:
        # гравийная кончается на крыльце Йоррваскра, главная — у замка. Отодвиг
        # уносил Йоррваскр на 5 м, освобождая его же подъезд.
        px, pz = ((ccx, ccz) if hs["kind"] in FIXED_KINDS
                  else push_off_ring(rec,
                                     *push_off_roads(ccx, ccz, w, d, yaw),
                                     w, d, yaw))
        fr.append({"hs": hs, "rec": rec, "x": px, "z": pz, "w": w, "d": d,
                   "yaw": yaw, "door": door, "x0": ccx, "z0": ccz})
    # Первые круги ещё уводят тела с полос, последние — только разводят тела:
    # отодвиг от дороги и разведение спорили друг с другом и оставляли лавки
    # юга рынка врезанными на 0.44 м. Наложение хуже, чем полметра на полосе.
    for it in range(64):
        road_pass = it < 40
        worst = 0.0
        for i in range(len(fr)):
            for j in range(i + 1, len(fr)):
                a, b = fr[i], fr[j]
                D = math.hypot(b["x"]-a["x"], b["z"]-a["z"]) or 1e-6
                ux, uz = (b["x"]-a["x"])/D, (b["z"]-a["z"])/D
                gap = (D - half_proj(a["w"], a["d"], a["yaw"], ux, uz)
                         - half_proj(b["w"], b["d"], b["yaw"], ux, uz))
                if gap >= GAP_M:
                    continue
                need = GAP_M - gap
                worst = max(worst, need)
                ma = a["hs"]["kind"] not in FIXED_KINDS
                mb = b["hs"]["kind"] not in FIXED_KINDS
                if not ma and not mb:
                    continue
                sa = need if (ma and not mb) else (need/2 if ma else 0.0)
                sb = need if (mb and not ma) else (need/2 if mb else 0.0)
                a["x"] -= ux*sa; a["z"] -= uz*sa
                b["x"] += ux*sb; b["z"] += uz*sb
        if it % 8 == 7:
            for f in fr:
                dx, dz = f["x"]-f["x0"], f["z"]-f["z0"]
                Lm = math.hypot(dx, dz)
                if Lm > MOVE_CAP:
                    f["x"], f["z"] = f["x0"]+dx/Lm*MOVE_CAP, f["z0"]+dz/Lm*MOVE_CAP
                # ОТ КЛАДКИ — ПЕРВЫМ, ОТ ДОРОГ — ВТОРЫМ, И ПОРЯДОК ЗДЕСЬ
                # РЕШАЕТ. Разведение тел между собой умеет загнать дом обратно
                # в стену: о стене оно не знает и толкает туда, где «свободно».
                # Но кто из двух отодвигов говорит ПОСЛЕДНИМ, тот и оставляет
                # свой дефект: с отодвигом от кладки в конце кузница вставала
                # на метр в проезжую часть главной улицы и там же теряла свой
                # двор (горн, наковальня, бочка — «ставить некуда»). Отодвиг от
                # дороги последним безопасен: он мелкий (полоса рядом с телом
                # уже пройдена), а следующий круг всё равно начнётся с кладки.
                if f["hs"]["kind"] not in FIXED_KINDS:
                    f["x"], f["z"] = push_off_ring(
                        f["rec"], f["x"], f["z"], f["w"], f["d"], f["yaw"],
                        budget=6.0)
                if road_pass and f["hs"]["kind"] not in FIXED_KINDS:
                    f["x"], f["z"] = push_off_roads(f["x"], f["z"], f["w"],
                                                    f["d"], f["yaw"], budget=6.0)
        if worst < 0.02 and not road_pass:
            break
    # ПОСЛЕДНЯЯ ПРИМЕРКА: СОЙТИ С ПОЛОСЫ, ЕСЛИ ЭТО НИЧЕГО НЕ ЛОМАЕТ.
    # Отодвиг от дорог выключается на сороковом круге (иначе он спорит с
    # разведением тел и оставляет лавки врезанными друг в друга), и последние
    # круги двигают тела уже вслепую к улицам. Пока стены в расстановке не
    # было, это стоило полуметра на полосе у одного дома; с отодвигом от
    # кладки — метра проезжей части у кузницы, вместе с её двором. Примерка
    # ПРОБНАЯ и принимается только целиком: сходим с полосы, если после этого
    # ни кладка не входит в тело, ни соседи не налезают.
    for f in fr:
        if f["hs"]["kind"] in FIXED_KINDS:
            continue
        if not any(rect_road_hit(f["x"], f["z"], f["w"], f["d"], f["yaw"], rd)
                   for rd in PLAN["roads"]):
            continue
        qx, qz = push_off_roads(f["x"], f["z"], f["w"], f["d"], f["yaw"],
                                budget=3.0)
        # ЗДЕСЬ ПОРОГ — НОЛЬ, А НЕ ЛАДОНЬ, И РАЗМЕН НАЗВАН ВСЛУХ: сойти с
        # проезжей части ценой того, что дом прижмётся к стене вплотную,
        # выгоднее, чем стоять посреди улицы с ладонью за спиной. Твёрдое
        # правило одно — кладка не входит в тело.
        wr = wall_rect_of(f["rec"], qx, qz, f["yaw"])
        if ring_clear(wr[0], wr[1], wr[2], wr[3], f["yaw"]) < 0.0:
            continue
        if any(gap_rects(qx, qz, f["w"], f["d"], f["yaw"],
                         g["x"], g["z"], g["w"], g["d"], g["yaw"]) < 0.0
               for g in fr if g is not f):
            continue
        f["x"], f["z"] = qx, qz
    return fr

# HOUSE_PAD_DROP / HOUSE_PAD_FEATHER — В ПАСПОРТЕ (пад под домом выключен с
# 23.08 по заказу владельца, числа держит контрольная рука DFN_CITY_PAD=1).

def house_floor(rec, oy):
    """Верх ПОЛОВОЙ ПЛИТЫ рецепта в мире. Числа FLOOR замерены по .dfh; у
    рецепта без записи пол лежит на 0.12, как у рядового дома."""
    return oy + FLOOR.get(rec, 0.12)

# --- ДОМ СТОИТ НА ФУНДАМЕНТЕ, А НЕ В ЯМЕ ------------------------------------
# ЗАКАЗ ВЛАДЕЛЬЦА 23.08 дословно: «дома почти все на треть первого этажа под
# землей — это крит! земля не ровная, дома ровные; чтобы избегать налезания
# земли на дома, необходимо делать каждому дому небольшой фундамент, который
# может уходить под землю, но сам дом на нём стоит как на ровной земле; а к
# двери в дом идёт лестница-ступеньки».
#
# ЧТО БЫЛО НЕ ТАК, ЧИСЛОМ. Прежняя посадка брала МИНИМУМ пятна и лечила
# неровность ПАДОМ — срезом поля высот до «пол - 0.10» ровно по пятну с каймой
# 1.2 м. Внутри пятна это работало (приёмка check_floors честно давала 26 из
# 26), но пад — КОРЫТО: земля вокруг остаётся склоном и подходит к стене на
# уровне, который пятно уже не меряет. Замер по земле ДВИЖКА (прибор
# tools/probe_ground.cpp, natural + pads + rivers + relief, шаг проб <= 1 м):
#   вынос 0.0 м от стены — земля выше пола у  0 из 26
#   вынос 0.5 м          —                    9 из 26, худший +1.65
#   вынос 1.0 м          —                   19 из 26, медиана +0.14, худший +4.24
#   вынос 2.0 м          —                   20 из 26, медиана +0.29
# То есть корыто шириной в свою кайму, и в кадре у дома на склоне кровля
# садится прямо в траву — стены не видно вовсе.
#
# ПОСАДКА ПО МАКСИМУМУ, А НЕ ПО МИНИМУМУ. Отметка низа стен = максимум земли
# под пятном СТЕН плюс зазор. Минимум был честен ровно в одном («ни один угол
# не висит»), но выбирал нижнюю точку склона, и всё, что выше неё, лезло на
# кладку. Максимум переворачивает вопрос: висеть теперь может ВСЁ, и держит
# это не земля, а фундамент.
# FOOT_* и STOOP_* — В ПАСПОРТЕ: зазор под стеной, вкоп ленты, вынос цоколя,
# ширина крыльца это нормативы застройки города, и у горного города они
# будут другими. Длина и толщина рецепта ленты (FOOT_SEG/FOOT_TH) тоже там —
# они называют, КАКОЙ рецепт этот город кладёт в фундамент.

_WRECT = {}

def recipe_wall_rect(rec):
    """ПЯТНО СТЕН рецепта: прямоугольник вершин НИЖНЕГО ВЕНЦА (y == 0).

    Габарит (recipe_box) для этого не годится и по той же причине, по которой
    коробка комнаты не строится по габариту: он обводит СВЕС КРОВЛИ вместе с
    корпусом (у city-house-s 5.30x7.14 против стен 4.50x6.00, у city-keep-s
    26.6x14.0 против 25.0x13.2). Фундамент по габариту вылез бы полкой на
    0.4 м из-под карниза, а посадка по максимуму подняла бы дом на бугор,
    которого стена не касается.
    y == 0, а не минимальный y: у мельницы колесо уходит на -1.65, и «нижний
    венец» по минимуму дал бы отпечаток 0.80x0.00 — две вершины оси колеса."""
    if rec in _WRECT:
        return _WRECT[rec]
    row = shelf(rec)
    if row is not None:
        _WRECT[rec] = (_sh(row, "wx0"), _sh(row, "wz0"),
                       _sh(row, "wx1"), _sh(row, "wz1"))
        return _WRECT[rec]
    V = []
    for line in open(os.path.join(ROOT, "assets/houses", rec), encoding="utf-8"):
        t = line.split()
        if t and t[0] == "vertex":
            V.append((float(t[3]), float(t[4]), float(t[5])))
    low = [p for p in V if abs(p[1]) < 1e-6]
    src = low if len(low) >= 4 else V
    xs = [p[0] for p in src]
    zs = [p[2] for p in src]
    _WRECT[rec] = (min(xs), min(zs), max(xs), max(zs))
    return _WRECT[rec]

def in_channel(x, z):
    """Точка лежит в коридоре русла, где дно режет ДВИЖОК, а не чертёж."""
    return any(d <= r["half_w"] + RIVER_BANK_M for d, r in river_near(x, z))

def wall_pts(rec, ox, oz, yaw, step=0.9):
    """Пробы по ПЯТНУ СТЕН в мире: сетка с шагом <= step (заказ: <= 1 м), то
    есть и периметр, и углы, и внутренность — одним перебором."""
    x0, z0, x1, z1 = recipe_wall_rect(rec)
    nx = max(2, int(math.ceil((x1-x0)/step)) + 1)
    nz = max(2, int(math.ceil((z1-z0)/step)) + 1)
    out = []
    for i in range(nx):
        lx = x0 + (x1-x0)*i/(nx-1)
        for j in range(nz):
            lz = z0 + (z1-z0)*j/(nz-1)
            out.append(loc_to_world(ox, oz, yaw, lx, lz))
    return out

def house_origin(rec, ccx, ccz, yaw):
    """origin рецепта из центра его ГАБАРИТА — та же арифметика, что в
    put_house, вынесенная наружу: площадку и фундамент считают до посадки."""
    c, s = math.cos(math.radians(yaw)), math.sin(math.radians(yaw))
    lcx, lcz = recipe_box(rec)[0], recipe_box(rec)[1]
    return (ccx - lcx*c - lcz*s, ccz + lcx*s - lcz*c)

_DOORPT = {}

def recipe_door_pt(rec):
    """Локальная точка двери и наружная нормаль её стороны. recipe_box уже
    находит дверь, но отдаёт только ОСЬ и вынос от центра — крыльцу нужна и
    вторая координата, иначе марш встанет посреди фасада."""
    if rec in _DOORPT:
        return _DOORPT[rec]
    row = shelf(rec)
    if row is not None:
        axis = recipe_box(rec)[4]
        dpx = _sh(row, "dpx")
        if dpx is None:
            x0, z0, x1, z1 = recipe_wall_rect(rec)
            _DOORPT[rec] = ((x0+x1)/2, z1, axis)
        else:
            _DOORPT[rec] = (dpx, _sh(row, "dpz"), axis)
        return _DOORPT[rec]
    V, door = {}, None
    for line in open(os.path.join(ROOT, "assets/houses", rec), encoding="utf-8"):
        t = line.split()
        if not t:
            continue
        if t[0] == "vertex":
            V[t[1]] = (float(t[3]), float(t[5]))
        elif "door=1" in line:
            pts = [V[v] for v in t[2:] if v in V]
            if pts:
                door = (sum(p[0] for p in pts)/len(pts),
                        sum(p[1] for p in pts)/len(pts))
    axis = recipe_box(rec)[4]
    if door is None:
        x0, z0, x1, z1 = recipe_wall_rect(rec)
        door = ((x0+x1)/2, z1)
    _DOORPT[rec] = (door[0], door[1], axis)
    return _DOORPT[rec]

def axis_normal(axis, yaw):
    """Мировая наружная нормаль стороны рецепта. Конвенция сцены:
    +X_лок = (cos, -sin), +Z_лок = (sin, cos)."""
    c, s = math.cos(math.radians(yaw)), math.sin(math.radians(yaw))
    return {"+Z": (s, c), "-Z": (-s, -c),
            "+X": (c, -s), "-X": (-c, s)}[axis]

def foot_kit(prefix):
    """Ряд выпечки по имени: {высота: файл}. Читается С ПОЛКИ, а не пишется
    таблицей — рецепт, которого _kit не видит, неотличим от несуществующего
    (урок city-steps6-h12r2: шаблон ждал ровно две цифры, и новый марш был
    не «не выбран», а НЕВИДИМ)."""
    out = {}
    for fn in os.listdir(os.path.join(ROOT, "assets/houses")):
        m = re.fullmatch(prefix + r"-h(\d+)\.dfh", fn)
        if m:
            out[int(m.group(1))/10.0] = fn
    return out

_FOOT_KIT, _STOOP_KIT = None, None

def footing_and_stoop(rec, ox, oy, oz, yaw, lo, name):
    """ЛЕНТА ФУНДАМЕНТА ПО ПЕРИМЕТРУ + КРЫЛЬЦО К ДВЕРИ.

    Лента: верх на отметке НИЗА СТЕН (oy), низ — до min(земля под пятном)
    минус FOOT_BURY. Высота ОДНА на весь периметр: верх горизонтален (на нём
    стоит дом), низ уходит в грунт тем глубже, чем выше склон.
    Ряд берётся БЛИЖАЙШИЙ СВЕРХУ: промах уходит вниз, в землю, где его не
    видно; ближайший снизу оставил бы ленту висеть.
    Наружная плоскость отрезка (его origin) кладётся на FOOT_OUT наружу от
    лица стены — цоколь обязан читаться выступом, а не совпадать со стеной.
    Углы закрываются продлением каждой стороны на полтолщины: два каменных
    тела с ОДНИМ верхом дают невидимый нахлёст, а щель в углу — дыру."""
    global _FOOT_KIT, _STOOP_KIT
    if _FOOT_KIT is None:
        _FOOT_KIT = foot_kit("city-foot2")
        _STOOP_KIT = foot_kit("city-stoop16")
    n_seg, foot_base = 0, None
    need = oy - (lo - FOOT_BURY)
    if need > 0.01 and _FOOT_KIT:
        # ГЛУБЖЕ ПОТОЛКА РЯДА — ВЕНЦАМИ, А НЕ НОВЫМ РЕЦЕПТОМ. Один дом города
        # просит больше четырёх метров: донжон стоит на кромке замкового
        # плато, и под его пятном 4.4x4.4 перепад 9.3 м (46 гр. — сам откос).
        # Печь ряд до десяти метров ради него значило бы двадцать девять новых
        # .dfh на один случай; венцы дают ту же ленту любой глубины из той же
        # выпечки, а горизонтальный шов между венцами — не дефект, а то, чем
        # бутовая кладка и выглядит. Потолок в четыре венца: 16 м — уже не
        # фундамент, и молчать об этом нельзя.
        top, rem, courses = oy, need, []
        while rem > 0.01 and len(courses) < 4:
            want = min(rem, FOOT_MAX)
            fits = sorted(h for h in _FOOT_KIT if h >= want - 1e-6)
            H = fits[0] if fits else max(_FOOT_KIT)
            courses.append((top - H, H))
            top -= H
            rem -= H
        if rem > 0.01:
            FOOT_SHORT.append((name, need, need - rem))
        x0, z0, x1, z1 = recipe_wall_rect(rec)
        # четыре стороны: (начало, конец, наружная нормаль в локали)
        sides = ((x0, z0, x1, z0, (0.0, -1.0)), (x1, z0, x1, z1, (1.0, 0.0)),
                 (x1, z1, x0, z1, (0.0, 1.0)), (x0, z1, x0, z0, (-1.0, 0.0)))
        for (ax, az, bx, bz, (nx, nz)) in sides:
            ux, uz = bx-ax, bz-az
            L = math.hypot(ux, uz)
            if L < 0.1:
                continue
            ux, uz = ux/L, uz/L
            # продление на полтолщины с обоих концов — угол без щели
            ext = FOOT_TH/2
            sx, sz = ax - ux*ext + nx*FOOT_OUT, az - uz*ext + nz*FOOT_OUT
            span = L + 2*ext
            k = max(1, int(math.ceil(span / FOOT_SEG)))
            # шаг раскладки: k отрезков ровно перекрывают span (последний
            # нахлёстывает на соседа, а не оставляет хвост голым)
            adv = 0.0 if k == 1 else (span - FOOT_SEG) / (k - 1)
            # локальный +X отрезка идёт вдоль стороны, тело — от лицевой
            # плоскости ВГЛУБЬ (к дому), значит +Z_лок = -нормаль
            syaw = math.degrees(math.atan2(-nx, -nz)) % 360.0
            for i in range(k):
                px, pz = sx + ux*adv*i, sz + uz*adv*i
                wx, wz = loc_to_world(ox, oz, yaw, px, pz)
                # отрезок, чья середина стоит в русле, не кладётся: там нет
                # земли, до которой ему тянуться (см. пробы выше)
                mx, mz = loc_to_world(ox, oz, yaw,
                                      px + ux*FOOT_SEG/2, pz + uz*FOOT_SEG/2)
                if in_channel(mx, mz):
                    continue
                for (fy, H) in courses:
                    house(_FOOT_KIT[H], wx, fy, wz, (yaw + syaw) % 360.0,
                          f"фундамент {name}")
                    n_seg += 1
        foot_base = courses[-1][0] if courses else None
    # --- КРЫЛЬЦО --------------------------------------------------------
    dlx, dlz, axis = recipe_door_pt(rec)
    nx, nz = axis_normal(axis, yaw)
    dwx, dwz = loc_to_world(ox, oz, yaw, dlx, dlz)
    # Порог — верх ЛЕНТЫ (oy): по нему входят, дальше 0.12 половой плиты
    # берётся шагом (PLAYER_STEP_HEIGHT 0.35).
    # Земля у подножия зависит от вылета, вылет — от подъёма, подъём — от
    # земли: два круга сходятся (вылет меняется на четверть метра).
    rise, run = 0.0, 1.0
    for _ in range(2):
        fx = dwx + nx*(FOOT_OUT + run + 0.05)
        fz = dwz + nz*(FOOT_OUT + run + 0.05)
        g = ground(fx, fz)
        if g is None:
            return n_seg, 0, foot_base
        rise = min(STOOP_MAX, max(0.0, oy - g))
        steps = max(1, round(rise / 0.175))
        run = steps * 0.30
    if rise < STOOP_MIN:
        return n_seg, 0, foot_base
    key = min(_STOOP_KIT, key=lambda h: abs(h - rise))
    steps = max(1, round(key / 0.175))
    run = steps * 0.30
    step_rise = key / steps
    # ХОДИБЕЛЬНАЯ ПОВЕРХНОСТЬ = ЯКОРЬ + подступенок - 0.02 (пандус
    # collider_only: низ a.y + rise - 0.18, экструзия вверх 0.16). Верх
    # целится в порог ТОЧНО, остаток ряда уходит в подошву: наверху игрок
    # сходит с марша на ходу и спотыкается, внизу сантиметр читается первой
    # ступенью (тот же порядок, что у марша террасы рынка).
    sy = oy - key - step_rise + 0.02
    # ЛОКАЛЬНЫЙ +X МАРША ИДЁТ ВВЕРХ, К ДВЕРИ, то есть ПРОТИВ наружной нормали.
    # +X_лок = (cos, -sin), значит cos = -nx и sin = nz.  (У ленты фундамента
    # yaw выводится из ДРУГОГО требования — +Z_лок = -нормаль, тело от лица
    # вглубь, — и формула получается иная: две детали, две конвенции, обе
    # выписаны, потому что перепутать их значит развернуть марш поперёк.)
    syaw = math.degrees(math.atan2(nz, -nx)) % 360.0
    # origin в углу: сдвиг на полширины по локальному +Z, чтобы марш встал
    # серединой на дверь (та же ошибка, что у прилавков рынка и жаровен —
    # смещение к углу обязано поворачиваться, а не прибавляться по осям)
    zx, zz = math.sin(math.radians(syaw)), math.cos(math.radians(syaw))
    sx = dwx + nx*(FOOT_OUT + run) - zx*STOOP_W/2
    sz = dwz + nz*(FOOT_OUT + run) - zz*STOOP_W/2
    house(_STOOP_KIT[key], sx, sy, sz, syaw, f"крыльцо {name}")
    STOOP_FOOT.append((dwx + nx*(FOOT_OUT + run + 0.15),
                       dwz + nz*(FOOT_OUT + run + 0.15)))
    STOOPS.append((key, dwx + nx*0.5, dwz + nz*0.5,
                   STOOP_FOOT[-1][0], STOOP_FOOT[-1][1], name))
    return n_seg, 1, foot_base

def put_house(f):
    hs, rec = f["hs"], f["rec"]
    ccx, ccz, w, d, yaw = f["x"], f["z"], f["w"], f["d"], f["yaw"]
    fx, fz = f["door"]
    c, s = math.cos(math.radians(yaw)), math.sin(math.radians(yaw))
    # origin рецепта лежит в УГЛУ, а центр габарита — не в (w/2, d/2): у замка
    # тело идёт от -5.8 до 20.8, у мельницы от -3.8 (вылет колеса). Считаем от
    # ЗАМЕРЕННОГО центра, иначе тело уезжает на разницу.
    lcx, lcz = recipe_box(rec)[0], recipe_box(rec)[1]
    ox = ccx - lcx*c - lcz*s
    oz = ccz + lcx*s - lcz*c
    # ОТМЕТКА БЕРЁТСЯ У ПАДА, А НЕ У ДАМПА ПРОШЛОГО ПРОХОДА. sit_rect читает
    # ground() — сетку ПРЕДЫДУЩЕГО прогона, а земля этого прохода уже срезана
    # под пад; расхождение двух полей и было тем самым «дом утоплен».
    y = f.get("y", sit_rect(ccx, ccz, w, d, yaw, 25.0))
    name = hs["name"] or hs["kind"] or "дом"
    house(rec, ox, y, oz, yaw, name)
    PLACED.append((ccx, ccz, w, d, yaw, name))
    FLOORS.append((ccx, ccz, w, d, yaw, house_floor(rec, y), name))
    FRAMES.append((rec, ox, y, oz, yaw, w, d, name))
    furnish(rec, ox, y, oz, yaw, name)
    n_seg, n_stoop, foot_base = 0, 0, None
    if "foot_lo" in f:
        n_seg, n_stoop, foot_base = footing_and_stoop(
            rec, ox, y, oz, yaw, f["foot_lo"], name)
    WALLBASE.append((rec, ox, oz, yaw, y, name, foot_base))
    # ДОРОЖКА ОТ ДВЕРИ К УЛИЦЕ — ПОЛОТНОМ ЗЕМЛИ, А НЕ ЦЕПОЧКОЙ ПЛИТ.
    # Копится здесь, кладётся вместе с тропами дорог: у полотна нет ни высоты,
    # ни поворота, ни посадки — только ломаная.
    # ...И ЦЕЛИТСЯ В ПОДНОЖИЕ КРЫЛЬЦА, А НЕ В ПОРОГ (заказ владельца 23.08).
    # Полотно — свойство ЗЕМЛИ; доведённое до порога, который теперь стоит на
    # метр выше земли, оно рисовало бы мостовую по склону насыпи под маршем.
    if hs["walk"]:
        wx, wz = hs["walk"]
        if n_stoop and STOOP_FOOT:
            fx, fz = STOOP_FOOT[-1]
        if math.hypot(wx - fx, wz - fz) > 0.8:
            WALKWAYS.append((fx, fz, wx, wz))
    return n_seg, n_stoop

# КЛАСС ПОЛОТНА ПУТЕВОГО АТЛАСА (движок fde9a7b): 0 мостовая-камень,
# 1 укатанный грунт, 2 протоптанная стёжка, 3 тёсаные плиты.
PATH_CLASS = {"stone": 0, "gravel": 1, "dirt": 2}

# ...И КЛАСС ВЫБИРАЕТСЯ ПО МЕСТУ, А НЕ ТОЛЬКО ПО МАТЕРИАЛУ ЧЕРТЕЖА (владелец
# 23.08: «тропинки земляные, а не каменные»). Сначала СВЕРКА, потом правка:
# кадры сверху вниз на полотно дорожки, на улицу и на траву дали средний RGB
# 125/127/117 (R/B 1.07), 155/145/124 (1.26) и 74/137/61. Палитра рецептов
# ProcTexture: CUT_SLAB (0.60,0.61,0.60) R/B 1.00, COBBLE (0.67,0.63,0.55)
# 1.22, PACKED_EARTH 1.64, TRAIL 1.81. То есть шейдер рисует ИМЕННО тот класс,
# который записан: дорожка — тёсаный камень, улица — мостовая, подмены нет.
# Значит землёй выглядит САМ ВЫБОР классов, и лечится он здесь: внутри стен
# город мощёный, земляные стёжки остаются трактам ЗА кольцом (к дубу,
# просёлок на юг). Мера «внутри» — доля проб ломаной внутри кольца.
def inside_walls(pts, frac=0.5):
    ins = sum(1 for (x, z) in pts if point_in_poly(x, z, PLAN["wall"]))
    return ins >= frac * len(pts)

# ОДНО МОЩЕНИЕ НА ГОРОД, А НЕ ЧЕТЫРЕ ПО ИЕРАРХИИ (постановление архитектора
# 24.08, и оно ОТМЕНЯЕТ его же таблицу из четырёх классов, выданную часом
# раньше). Правило эталона сильнее правила красоты: у настоящего Вайтрана на
# весь город ДВА мощения — полотно на всё горизонтальное и тёсаный блок на
# ВЕРТИКАЛИ (ступени, подпорные стенки, цоколи). Участки различаются ИЗНОСОМ,
# а не вторым камнем.
#
# ЧТО БЫЛО ИЗМЕРЕНО ДО ПРАВКИ (перепись 51 записи path в whiterun.relief):
# 26 лент класса 0, 2 класса 2, 23 класса 3 и НИ ОДНОЙ класса 1. То есть
# «пять материалов на главной улице» были не пятью материалами: это ОДНА
# мостовая, поверх которой набросаны двадцать три кляксы тёсаной плиты —
# дорожки от дверей, зашитые константой cls=3. Класс в движке побеждает
# ПОСЛЕДНИЙ (TerrainMesher.cpp:67), и радиус класса на 0.75 м шире полуширины,
# поэтому каждая дорожка штамповала пятно чужого камня радиусом 2.35 м ПОВЕРХ
# улицы, к которой подходила.
CLS_PAVED = 0   # мостовая: всё горизонтальное внутри кольца стен
CLS_TRACK = 2   # стёжка: всё за кольцом
CLS_CUT = 3     # тёсаная плита: ТОЛЬКО вертикали и ступени, полотном не бывает

def path_class(rd):
    return CLS_PAVED if inside_walls(rd["pts"]) else CLS_TRACK

# ПОРОГ КЛАССОВОГО ОСТРОВА ВЫВЕДЕН, А НЕ НАЗНАЧЕН. У любого штриха
# fade = max(soft*half, PATH_MIN_FADE_M), а PATH_MIN_FADE_M = 1.0 м —
# пол ДВИЖКА (ReliefLayer.h), ниже него кромка не сжимается. Значит штрих
# короче 2*fade состоит из ОДНОЙ КРОМКИ И НИЧЕГО БОЛЬШЕ: у него нет ни метра
# полотна с полным износом, и прочитаться мощением он не может физически —
# только пятном. Чтобы островок своего класса читался, ему нужен хотя бы метр
# плоской вершины: 2*FADE_M + 1.0.
ISLAND_MIN_M = 3.0

# --- КРОМКА ПОЛОТНА ЗАДАЁТСЯ В МЕТРАХ, А НЕ ДОЛЕЙ ----------------------------
# ПРЕТЕНЗИЯ ВЛАДЕЛЬЦА 22.08: «между бордюром и тропой зелени просвет — плохо».
# Просвет — не бордюр и не тропа, а ТРЕТЬЕ число строки path, которое до сих
# пор писалось как метры, а читается как ДОЛЯ полуширины (ReliefLayer.h:
# edge_softness [0,1] — «доля полуширины, на которой износ спадает от полного
# до нуля; 1 значит спад начинается на осевой»). Генератор писал 1.2 у камня и
# 1.0 у прочих; и то и другое зажимается в 1.0, то есть плоской вершины у
# полотна НЕ БЫЛО НИ У ОДНОЙ ТРОПЫ ГОРОДА: мостовая набирала полный износ
# ровно на осевой линии и дальше линейно растворялась, а дизер fs_path.sc
# показывал сквозь неё траву на всю ширину улицы. То, что владелец назвал
# «просветом зелени», — этот спад, и на кадре он читается зелёными лентами
# вдоль обеих кромок.
# ЛЕЧИТСЯ ПЕРЕВОДОМ ЗАДАНИЯ В МЕТРЫ: полоса спада FADE_M одинакова у всех
# полотен, а доля считается от собственной полуширины. Тогда кромка полотна
# лежит на РОВНО half от осевой (это и есть то место, куда садится бордюрный
# сегмент, п. 4 заказа), а внутри неё камень сплошной.
# ПОЛ 1.0 М — НЕ ВЫБОР, А УСТРОЙСТВО (ReliefLayer.h, PATH_MIN_FADE_M =
# HEIGHTMAP_STEP): полоса уже отсчёта сетки превращает поле в 0/1, а 0/1 на
# решётке — лесенка. Значит у полотна полуширины 1.0 плоской вершины не будет
# никогда, и дорожки от дверей приходится расширять, а не «делать резче».
FADE_M = 1.0            # полоса спада полотна, метры (= пол движка)
WALK_HALF = 1.6         # полуширина дорожки от двери: 1.6 - 1.0 = 0.6 м камня
PATHS = []              # (ломаная, полуширина, edge_softness, класс, имя)
# ПЛОЩАДКИ, ЗАЯВЛЕННЫЕ СПЛОШНЫМИ. Полотно у движка — ЛЕНТА, а площадь —
# ПЯТНО; пятно набирается штриховкой, и штриховка либо сходится, либо нет.
# Чтобы приёмка спрашивала про ПЛОЩАДЬ, а не про ленты, из которых она
# сложена, каждая площадка объявляет свой контур сама:
#   ("имя", "rect", (x, z, w, d), класс) | ("имя", "disk", (cx, cz, R), класс)
SQUARES = []
# ...И ПЯТНА, ЗАЯВЛЕННЫЕ ГОЛЫМИ: ("имя", cx, cz, R). Приствольный круг дерева
# — площадка наоборот, и мерить её надо тем же полем и тем же прибором,
# иначе «мощёный сквер» выполняется самым простым способом — замостить всё,
# включая подножие дуба (ровно это и было до этой правки).
BARE_SPOTS = []

# ЗАПАС ПЕРЕКРЫТИЯ ШТРИХОВКИ ПЛОЩАДКИ. Полоса спада не может быть уже метра
# (пол движка), значит плоская вершина ленты равна half - FADE_M и другой не
# станет. Две соседние полки, поставленные ВСТЫК, дают сплошную площадь только
# на бумаге: между ними проходит линия, на которой износ равен единице ровно в
# одной точке, а ниже по решётке — уже нет. Полклетки высот запаса.
PAVE_LAP = 0.5

def pave_pitch(half_m, fade_m=FADE_M):
    """Шаг между осевыми лент, при котором полки перекрываются на PAVE_LAP."""
    return max(0.5, 2.0 * (max(half_m, 1.0) - max(fade_m, 1.0)) - PAVE_LAP)

def lay(pts, half_m, cls, note="", fade_m=FADE_M):
    """Кладёт полотно и возвращает записанный edge_softness. Полоса спада —
    в метрах; ниже пола движка её всё равно не опустить, поэтому и сама
    величина названа полом, а не вкусом."""
    half = max(half_m, 1.0)
    soft = min(1.0, max(fade_m, 1.0) / half)
    PATHS.append((list(pts), half, soft, cls, note))
    return soft

# --- БОРДЮР: ОБЪЁМНЫЕ СЕГМЕНТЫ ПО КРОМКЕ ПОЛОТНА (заказ владельца, п. 4) ----
# «Сделай тропу с отдельным элементом бордюра, чтобы всё точно по алгоритмам
# рисовалось». Отдельный элемент — рецепт кузницы (ждём wr-forge3); «точно по
# алгоритмам» — вот эти четыре правила, и каждое из них тут выполняется
# буквально, а не приблизительно:
#   1. Сегменты идут СТЫК В СТЫК по длине куска: origin следующего = конец
#      предыдущего, никаких зазоров «на глазок».
#   2. Отступ от кромки полотна НОЛЬ: линия раскладки — ровно `half` от
#      осевой, то есть та самая линия, на которой полотно кончается (после
#      перевода спада в метры кромка стала определённой; до этого «кромки» у
#      полотна не было вовсе — оно растворялось от самой осевой).
#   3. yaw — по КАСАТЕЛЬНОЙ к кромке в точке посадки.
#   4. НА ПЕРЕСЕЧЕНИЯХ БОРДЮР РВЁТСЯ: сегмент, чей след попадает в полосу
#      другого полотна, в створ ворот, в тело постройки или на площадь, не
#      ставится. Бордюр поперёк проезда — это порог, а не украшение.
# КРИВАЯ БЕРЁТСЯ ТА ЖЕ, ЧТО У ДВИЖКА. Полотно рисуется по центростремительному
# Catmull-Rom ЧЕРЕЗ точки (relief_path_polyline), а не по ломаной, и на изломах
# кривая уходит от ломаной на метры (замер кольца стены этой же волны: 1.86 м).
# Бордюр, разложенный по ломаной, разошёлся бы с нарисованной кромкой ровно
# там, где он заметнее всего — на повороте.
KERB_MIN_HALF = 1.5    # у дорожки от двери бордюра не бывает: она сама 1.6
KERB_CURVE_STEP = 0.25  # шаг выборки кривой полотна, м
KERB_CLEAR = 0.35      # запас от чужой полосы: полтела капсулы

def _knot(t_prev, a, b):
    return t_prev + max(math.sqrt(math.hypot(b[0]-a[0], b[1]-a[1])), 1.0e-3)

def _cr(p0, p1, p2, p3, t):
    """ЦЕНТРОСТРЕМИТЕЛЬНЫЙ Catmull-Rom — построчный перевод catmull_rom() из
    engine/world/sources/ReliefLayer.cpp. Переписан, а не приближён: своя
    «похожая» кривая дала бы бордюр, который почти совпадает с полотном, а
    «почти» на кромке читается как щель."""
    t0 = 0.0
    t1 = _knot(t0, p0, p1)
    t2 = _knot(t1, p1, p2)
    t3 = _knot(t2, p2, p3)
    tt = t1 + (t2 - t1) * min(max(t, 0.0), 1.0)

    def lk(a, b, ta, tb, x):
        d = tb - ta
        if abs(d) < 1.0e-6:
            return a
        w = (tb - x) / d
        return (a[0]*w + b[0]*(1-w), a[1]*w + b[1]*(1-w))
    a1 = lk(p0, p1, t0, t1, tt)
    a2 = lk(p1, p2, t1, t2, tt)
    a3 = lk(p2, p3, t2, t3, tt)
    b1 = lk(a1, a2, t0, t2, tt)
    b2 = lk(a2, a3, t1, t3, tt)
    return lk(b1, b2, t1, t2, tt)

def path_polyline(pts, step=KERB_CURVE_STEP):
    """Ломаная выборки кривой полотна — тот же обход, что в движке."""
    if len(pts) < 2:
        return list(pts)
    n = len(pts)
    at = lambda i: pts[min(max(i, 0), n-1)]
    out = [tuple(pts[0])]
    for i in range(n - 1):
        p0, p1, p2, p3 = at(i-1), pts[i], pts[i+1], at(i+2)
        chord = math.hypot(p2[0]-p1[0], p2[1]-p1[1])
        steps = max(1, int(math.ceil(chord / max(step, 0.05))))
        for k in range(1, steps + 1):
            out.append(_cr(p0, p1, p2, p3, k / steps))
    return out

# --- ПОЛОТНО ГЛАЗАМИ ДВИЖКА: КЛАСС И ИЗНОС В ТОЧКЕ ---------------------------
# Прибора на НЕПРЕРЫВНОСТЬ полотна в дереве не было вовсе: check_paving меряет
# объекты-плиты, а check_axis прямо пишет, что покрытие камнем «обеспечено по
# построению» — то есть о самом полотне не спрашивает никто, и лоскуты уехали
# в город молча. Здесь ровно две функции движка, переписанные построчно, а не
# «примерно так же»:
#   класс  — TerrainMesher.cpp::PathClassField::class_at: побеждает ПОСЛЕДНИЙ
#            мазок, накрывший точку радиусом half + 0.75 (запас на растушёвку);
#   износ  — ReliefLayer.cpp::relief_path_wear + math::path_wear_profile:
#            полка half - fade даёт единицу, дальше 1 - u^2, и по мазкам берётся
#            МАКСИМУМ, а не сумма.
# Обе меряются по КРИВОЙ (relief_path_polyline), а не по ломаной чертежа:
# движок семплит именно кривую, а она отходит от ломаной до 1.86 м.
# ЧЕСТНАЯ ГРАНИЦА ПРИБОРА: износ здесь аналитический, а движок хранит его на
# решётке 1 м и интерполирует — то есть ответ этого прибора это ЛУЧШИЙ случай.
# Провал у него настоящий, а ноль не гарантирует нуля на решётке.
FAB_CELL = 4.0

class Fabric:
    def __init__(self, paths):
        self.st = []
        self.grid = {}
        for pts, half, soft, cls, note in paths:
            curve = path_polyline(pts)
            fade = min(max(min(max(soft, 0.0), 1.0) * half, FADE_M), half)
            i = len(self.st)
            self.st.append((curve, half, fade, cls, note))
            reach = half + 0.75
            for j, (a, b) in enumerate(zip(curve, curve[1:])):
                x0 = int(math.floor((min(a[0], b[0]) - reach) / FAB_CELL))
                x1 = int(math.floor((max(a[0], b[0]) + reach) / FAB_CELL))
                z0 = int(math.floor((min(a[1], b[1]) - reach) / FAB_CELL))
                z1 = int(math.floor((max(a[1], b[1]) + reach) / FAB_CELL))
                for cx in range(x0, x1 + 1):
                    for cz in range(z0, z1 + 1):
                        self.grid.setdefault((cx, cz), []).append((i, j))

    def _near(self, px, pz):
        return self.grid.get((int(math.floor(px / FAB_CELL)),
                              int(math.floor(pz / FAB_CELL))), ())

    def _dist(self, px, pz):
        """{индекс мазка: расстояние до его кривой} по соседям точки."""
        out = {}
        for i, j in self._near(px, pz):
            curve = self.st[i][0]
            ax, az = curve[j]
            bx, bz = curve[j+1]
            vx, vz = bx-ax, bz-az
            L2 = vx*vx + vz*vz or 1e-9
            t = max(0.0, min(1.0, ((px-ax)*vx + (pz-az)*vz) / L2))
            d = math.hypot(px-ax-vx*t, pz-az-vz*t)
            if d < out.get(i, 1e9):
                out[i] = d
        return out

    def class_at(self, px, pz):
        return self.sample(px, pz)[0]

    def sample(self, px, pz):
        """(класс, износ, чей мазок) одной пробой — двух проходов не надо."""
        dd = self._dist(px, pz)
        cls, wear, who = None, 0.0, None
        for i in sorted(dd):
            curve, half, fade, c, _n = self.st[i]
            d = dd[i]
            if d <= half + 0.75:
                cls, who = c, i
            flat = half - fade
            if d <= flat:
                wear = 1.0
            elif d < half and fade > 0.0:
                u = (d - flat) / fade
                wear = max(wear, max(0.0, 1.0 - u*u))
        return cls, wear, who

    def touches(self, i, x, z, r=1.5):
        """Проходит ли кривая мазка i в r метрах от точки — им проверяется,
        СОЕДИНЕНЫ ли два штриха концом в конец."""
        curve = self.st[i][0]
        return any(math.hypot(px-x, pz-z) <= r for px, pz in curve)

# ВЫПЕЧКА КУЗНИ-3 (письмо wr-forge3, 22.08): furn-curb06/06b/12/12b —
# 0.600 и 1.200 вдоль +X, тело z 0.016..0.204, ВЕРХ +0.160, НИЗ -0.150.
# Заглубление -0.150 — не украшение: на неровной земле бордюр, посаженный
# «верхом в ноль», половиной цепи висел бы, а половиной тонул. Origin садится
# РОВНО на землю, и низ уходит в грунт сам.
# ТОНА ЧЕРЕДУЮТСЯ (b светлее): кузница назвала причину, и она проверяема —
# одинаковые куски встык читаются одной отлитой лентой, а не кладкой.
# И ЭТО НЕ city-kerb2-hNN. Та — подпорная стенка террасы рынка толщиной 0.35;
# подбор по слову «кромка» взял бы метровую стенку вдоль всей улицы.
CURB_LONG = ("furn-curb12.dfh", "furn-curb12b.dfh")
CURB_SHORT = ("furn-curb06.dfh", "furn-curb06b.dfh")
# НАХЛЁСТ 0.55, А НЕ 0.03 — И ЭТО НЕ ЗАПАС «НА ВСЯКИЙ СЛУЧАЙ», А ПОЛОВИНА
# КЛЕТКИ СЕТКИ ВЫСОТ. Кузница просила 2-3 см, и для ЖЁСТКОЙ кромки этого хватило
# бы; но кромка у нас не жёсткая: износ полотна хранится ПО ОТСЧЁТАМ решётки 1 м
# и интерполируется, поэтому граница сплошного камня гуляет вокруг расчётной
# линии в пределах полуклетки. На кадре это и было видно — бордюр стоял ровно,
# а трава то подходила к нему вплотную, то вылезала полосой с ВНУТРЕННЕЙ
# стороны. Камень уводится внутрь на полклетки: тогда под ним гарантированно
# сплошная мостовая при любом положении интерполированной границы, а наружу
# уходит полметра камня и метр спада — вытоптанная обочина, чем она и является.
CURB_OVERLAP = 0.55
# КРУЧЕ ЭТОГО — ЦЕПЬ ИДЁТ КОРОТКИМИ КУСКАМИ. Порог опущен 4.0 -> 2.0 по
# претензии владельца («стыки бордюра на кривой раскрываются клиньями»):
# клин на стыке = глубина тела * tg(поворот/2), тело furn-curb 0.188 м, то
# есть при 4 гр. на кусок это 6.6 мм, а при 2 гр. — 3.3. Само по себе и то и
# другое мелочь; читается НАКОПЛЕНИЕ — жёсткая хорда 1.2 м на дуге отходит от
# кромки на L^2*k/8, и на самых крутых улицах чертежа (до 3.7 гр/м) это 2 см
# у дальнего конца против 0.5 см у куска 0.6. Половинный кусок стоит вдвое
# больше расстановок только там, где кромка действительно гнётся.
CURB_TURN_DEG = 2.0
# ЦЕПЬ КОРОЧЕ ЭТОГО СНИМАЕТСЯ ЦЕЛИКОМ: два длинных куска — это уже кромка,
# один — обрубок. Числом: 2 * 1.2.
KERB_MIN_RUN = 3.6

def kerb_kit():
    """Есть ли бордюр на полке. Возвращает (длинный, короткий) или None."""
    have = lambda f: os.path.exists(os.path.join(ROOT, "assets/houses", f))
    if all(have(f) for f in CURB_LONG + CURB_SHORT):
        return (CURB_LONG, CURB_SHORT)
    return None

def kerbs_along(paths):
    """БОРДЮР ПО ОБЕИМ КРОМКАМ МОЩЁНЫХ ТРАКТОВ, стык в стык по кривой.
    ЛИНИЯ РАСКЛАДКИ — САМА КРОМКА ПОЛОТНА, минус нахлёст: внутренняя грань
    камня (локальный z=0) садится на half - CURB_OVERLAP от осевой, тело
    уходит наружу. Отступа нет ни по замыслу, ни по числу.
    РАЗВОРОТ ВЫВЕДЕН ИЗ КОНВЕНЦИИ СЦЕНЫ, А НЕ ПОДОБРАН: локальный
    +X = (cos yaw, -sin yaw), +Z = (sin yaw, cos yaw), то есть +Z — это +X,
    повёрнутый на (x,z)->(-z,x). Нужен наружный +Z = n, значит +X = (n_z, -n_x).
    Для правой кромки это касательная, для ЛЕВОЙ — касательная ОБРАТНАЯ,
    поэтому левая сторона выкладывается по дуге назад. Без этого вывода
    половина цепи стояла бы к улице спиной — та самая ошибка «лицом в грунт»,
    которую мы уже ловили на подпорной стенке."""
    kit = kerb_kit()
    n_put, n_skip, m_run, n_orphan = 0, 0, 0.0, 0
    gates = [(g["pos"][0], g["pos"][1]) for g in PLAN["gates"]]
    # СЧЁТЧИК ТОНА — СВОЙ У КАЖДОЙ ДЛИНЫ, иначе чётность длинных кусков решала
    # бы, каким тоном лягут редкие короткие. ЧЕСТНО ПРО КОРОТКИЕ: на ЭТОМ
    # чертеже их всего один из 268 — улицы после сглаживания кривой поворачивают
    # мягче 4 гр. на кусок почти везде, и 0.6 остаётся резервом на случай более
    # изломанного чертежа. Прибор check_unplaced будет спрашивать про
    # furn-curb06 — это и есть ответ, а не забытый замысел.
    tone = {True: 0, False: 0}
    for pts, half, soft, cls, note in list(paths):
        if cls != 0 or half < KERB_MIN_HALF:
            continue
        # бордюр — у УЛИЦ. Полотно площади, сквера и парадного двора — это
        # площадка, а не путь: у неё кромка не линия, а периметр, и цепь
        # вдоль каждого мазка легла бы решёткой посреди площади.
        if len(note.split()) < 2 or note.split()[1] not in ("stone", "gravel", "dirt"):
            continue
        poly = path_polyline(pts)
        acc = [0.0]
        for a, b in zip(poly, poly[1:]):
            acc.append(acc[-1] + math.hypot(b[0]-a[0], b[1]-a[1]))
        total = acc[-1]
        for side in (1.0, -1.0):
            s = 0.0
            chain = []      # (ox, oz, kyaw, seg_l, ставится?) по порядку дуги
            while s < total - 0.3:
                # ДЛИНА КУСКА ВЫБИРАЕТСЯ ПО ПОВОРОТУ КРОМКИ на нём: жёсткий
                # кусок 1.2 м на дуге даёт хорду, и его дальний конец сходит с
                # кромки тем сильнее, чем круче поворот.
                seg_l = 1.2
                for cand in (1.2, 0.6):
                    if s + cand > total:
                        continue
                    a0 = _arc_at(poly, acc, s)
                    a1 = _arc_at(poly, acc, min(s + cand*0.5, total))
                    a2 = _arc_at(poly, acc, min(s + cand, total))
                    v1 = math.atan2(a1[1]-a0[1], a1[0]-a0[0])
                    v2 = math.atan2(a2[1]-a1[1], a2[0]-a1[0])
                    dv = abs(math.degrees(v2 - v1))
                    dv = min(dv, 360 - dv)
                    seg_l = cand
                    if dv <= CURB_TURN_DEG:
                        break
                if s + seg_l > total:
                    break
                p_a = _arc_at(poly, acc, s)
                p_b = _arc_at(poly, acc, s + seg_l)
                tx, tz = p_b[0]-p_a[0], p_b[1]-p_a[1]
                tl = math.hypot(tx, tz) or 1.0
                tx, tz = tx/tl, tz/tl
                nx, nz = -tz*side, tx*side              # наружу от полотна
                # начало детали: у правой кромки — начало куска, у левой —
                # его конец (там +X смотрит назад по дуге)
                px, pz = (p_a if side > 0 else p_b)
                ax, az = (tx, tz) if side > 0 else (-tx, -tz)
                # ЛИНИЯ РАСКЛАДКИ — КРОМКА СПЛОШНОГО КАМНЯ (half - FADE_M), А
                # НЕ КРОМКА ПОЛОСЫ. Разница видна на первом же кадре и она и
                # есть претензия владельца. Полоса спада не может быть уже
                # метра (PATH_MIN_FADE_M = шаг сетки высот; уже — поле 0/1 и
                # лесенка), поэтому наружный метр полотна ВСЕГДА дизером: если
                # посадить камень на half, между сплошной мостовой и бордюром
                # остаётся ровно тот метр травы в клетку, который назвали
                # «просветом зелени». Камень садится там, где износ равен
                # единице, и полуметровый хвост спада уходит ЗА него — рядом с
                # бордюром это читается вытоптанной обочиной, чем и является.
                off = half - FADE_M - CURB_OVERLAP
                ox, oz = px + nx*off, pz + nz*off
                mx = px + ax*seg_l/2 + nx*(off + 0.11)
                mz = pz + az*seg_l/2 + nz*(off + 0.11)
                s += seg_l
                ok = not _kerb_blocked(mx, mz, pts, half, 0.22, gates)
                kyaw = math.degrees(math.atan2(-az, ax)) % 360.0
                chain.append((ox, oz, kyaw, seg_l, ok, mx, mz))
            # ОДИНОЧНЫЙ ОБРУБОК — НЕ БОРДЮР (претензия владельца, круг 6:
            # «одиночные обрубки 1.2 м лежат по диагонали посреди мостовой,
            # ничего не окаймляя»). Разрывы ставит _kerb_blocked, и между двумя
            # разрывами законно остаётся один уцелевший кусок: у перекрёстка,
            # у створа ворот, между двумя телами. Такой кусок не окаймляет
            # НИЧЕГО — он и читается мусором, а не кромкой. Бордюр — это
            # ЦЕПЬ, и цепь короче KERB_MIN_RUN снимается целиком.
            run = []
            for item in chain + [(0, 0, 0, 0, False, 0, 0)]:
                if item[4]:
                    run.append(item)
                    continue
                if sum(r[3] for r in run) + 1e-9 < KERB_MIN_RUN:
                    n_orphan += len(run)
                else:
                    for (ox, oz, kyaw, seg_l, _o, mx, mz) in run:
                        if kit:
                            is_long = seg_l > 0.9
                            fam = kit[0] if is_long else kit[1]
                            tone[is_long] += 1
                            gy = ground(mx, mz)
                            house(fam[tone[is_long] % 2], ox,
                                  (27.0 if gy is None else gy), oz, kyaw,
                                  "бордюр тропы")
                        n_put += 1
                        m_run += seg_l
                run = []
            n_skip += sum(1 for c in chain if not c[4])
    if kit:
        print(f"бордюр (furn-curb06/12, тона чередуются): {n_put} сегментов, "
              f"{m_run:.0f} м кромки, {n_skip} разрывов (перекрёстки, створы "
              f"ворот, тела, площадь), {n_orphan} обрубков снято "
              f"(цепь короче {KERB_MIN_RUN:.1f} м ничего не окаймляет); "
              f"нахлёст на полотно {CURB_OVERLAP*100:.0f} см")
    else:
        print(f"БОРДЮР: рецепта на полке нет — холостой прогон алгоритма: "
              f"{n_put} сегментов ({m_run:.0f} м), {n_skip} разрывов")
    return n_put

def _arc_at(poly, acc, s):
    """Точка кривой на длине дуги s (линейно внутри звена)."""
    lo, hi = 0, len(acc) - 1
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if acc[mid] <= s:
            lo = mid
        else:
            hi = mid
    seg = acc[lo+1] - acc[lo] or 1e-9
    t = (s - acc[lo]) / seg
    a, b = poly[lo], poly[min(lo+1, len(poly)-1)]
    return (a[0] + (b[0]-a[0])*t, a[1] + (b[1]-a[1])*t)

def _kerb_blocked(mx, mz, own_pts, own_half, seg_t, gates):
    """Разрыв бордюра. Пять причин, и каждая — про проход, а не про красоту:
    чужое полотно (перекрёсток), створ ворот, тело постройки, площадь и
    собственная петля полотна (у ломаной, возвращающейся к себе)."""
    for pts, half, soft, cls, note in PATHS:
        if pts is own_pts:
            continue
        for (x0, z0), (x1, z1) in zip(pts, pts[1:]):
            vx, vz = x1-x0, z1-z0
            L2 = vx*vx + vz*vz or 1e-9
            t = max(0.0, min(1.0, ((mx-x0)*vx + (mz-z0)*vz) / L2))
            if math.hypot(mx-x0-vx*t, mz-z0-vz*t) < half + seg_t/2 + KERB_CLEAR:
                return True
    for gx, gz in gates:
        if math.hypot(mx-gx, mz-gz) < GATE_SPAN:
            return True
    if on_plaza(mx, mz):
        return True
    for (cx, cz, w, d, yaw, _n) in PLACED:
        c = math.cos(math.radians(yaw))
        sn = math.sin(math.radians(yaw))
        dx, dz = mx - cx, mz - cz
        # МАРЖА 0.05, А НЕ ТОЛЩИНА КАМНЯ. Фасадные ряды этого города стоят
        # у самой кромки улицы (норматив щели 0.35 м), и запрет «шириной в
        # бордюр» снимал цепь как раз вдоль фасадов — там, где бордюр и нужен.
        # Запрещено ровно одно: камень внутри стены.
        if abs(dx*c - dz*sn) < w/2 + 0.05 and abs(dx*sn + dz*c) < d/2 + 0.05:
            return True
    return False

WALKWAYS = []  # (x0, z0, x1, z1) дорожек от дверей — кладутся полотном
PLACED = []  # (cx, cz, w, d, yaw_deg, name) реальных тел для проверок
FRAMES = []  # (rec, ox, oy, oz, yaw_deg, w, d, name) — рама дома для дворов
FLOORS = []  # (cx, cz, w, d, yaw, отметка пола, имя) — для приёмки «земля под полом»
FURN_Y = []  # (y предмета, отметка пола, имя) — та же приёмка для убранства
# НИЗ ЛЕНТЫ ЖИВЁТ В САМОЙ ЗАПИСИ ДОМА, А НЕ В СЛОВАРЕ ПО ИМЕНИ.
# Первая редакция держала его в dict[имя] — и приёмка врала на весь город:
# имён у чертежа 26 штук на 26 домов, но РАЗНЫХ среди них 12 («дом» девять
# раз, «ветхий» дважды, «лавка» дважды), поэтому лента одного дома судилась
# по земле другого. Число вылезло само: «глубже всех -7.29 м» при потолке
# ленты 4.0 — арифметически невозможно ни при какой посадке.
STOOP_FOOT = []  # (x, z) подножий крыльца — в них целятся дорожки WALKWAYS
FOOT_SHORT = []  # (дом, нужная высота ленты, лучшая в выпечке) — сказать вслух
STOOPS = []  # (подъём, дверь x, z, подножие x, z, дом) — для прогона бота
WALLBASE = []  # (рецепт, ox, oz, yaw, отметка НИЗА СТЕН, имя) — приёмка «утопленность»
PLAN_H_REF = [None]  # поле высот ЭТОГО прохода, чтобы приёмки не пересчитывали его
COLUMN_SHORT = []  # (рецепт, нужная длина, лучшая в выпечке, дом) — нет столба

PLAZA_RECTS = []   # прямоугольники площадей; объявляют МЕСТА паспорта
PLAZA_BUF = 2.0    # буфер площади: фасады стоят на самой площади, это норма

def on_plaza(px, pz):
    """Точка на площади (с буфером). Дороги, влившиеся в площадь, там не
    считаются конфликтом, дворовый клаттер туда не лезет, бордюр рвётся.
    ПЛОЩАДЕЙ БЫВАЕТ НЕСКОЛЬКО, и до волны И1 это был один прямоугольник рынка,
    зашитый четырьмя именами MRX/MRZ/MRW/MRD — не потому, что площадь может
    быть только одна, а потому, что у Вайтрана она одна."""
    for (rx, rz, rw, rd) in PLAZA_RECTS:
        if (rx - PLAZA_BUF <= px <= rx + rw + PLAZA_BUF
                and rz - PLAZA_BUF <= pz <= rz + rd + PLAZA_BUF):
            return True
    return False

ROAD_END_M = 6.0  # хвост дороги у её конца — это порог, а не конфликт

def rect_road_hit(cx, cz, w, d, yaw_deg, rd):
    """Сэмплы осевой дороги в локали дома против [±w/2]x[±d/2].
    КОНЦЫ ДОРОГИ НЕ СЧИТАЮТСЯ. Дорога в этом чертеже кончается НА цели —
    у ворот, у моста, у дуба, у крыльца Йоррваскра; последние метры осевой
    лежат в теле здания по замыслу («улицы упираются в доминанты», гайд §11).
    Без исключения отодвиг уносил Йоррваскр — доминанту, задающую сетку, —
    на 5.4 м от его места, лишь бы освободить свой же подъезд."""
    r = math.radians(yaw_deg)
    c, sn = math.cos(r), math.sin(r)
    ex0, ez0 = rd["pts"][0]
    ex1, ez1 = rd["pts"][-1]
    for (x0,z0),(x1,z1) in zip(rd["pts"], rd["pts"][1:]):
        L = math.hypot(x1-x0, z1-z0)
        for i in range(int(L*2) + 1):
            t = i / max(1, int(L*2))
            wx0, wz0 = x0+(x1-x0)*t, z0+(z1-z0)*t
            if on_plaza(wx0, wz0):
                continue
            if (math.hypot(wx0-ex0, wz0-ez0) < ROAD_END_M
                    or math.hypot(wx0-ex1, wz0-ez1) < ROAD_END_M):
                continue
            px, pz = wx0 - cx, wz0 - cz
            lx = px*c - pz*sn
            lz = px*sn + pz*c
            ddx = max(abs(lx) - w/2, 0.0)
            ddz = max(abs(lz) - d/2, 0.0)
            if math.hypot(ddx, ddz) < rd["w"]/2 - 0.3:
                return True
    return False

# --- ДВОРЫ (гайд §7/§10: «за каждым — дворик с поленницей/бочкой и межевым
# плетнём», обязательный набор — поленница, бочка дождевой воды, плетень
# 1.2-1.8 м) ------------------------------------------------------------------
# Двор лежит ЗА глухой стеной дома (локальное z<0: дверь на z=d), клаттер
# жмётся к стене и к линии плетня — «коридор прохода свободен». Ставится
# ВТОРЫМ проходом, когда все тела уже в PLACED: иначе поленница соседа,
# поставленная раньше, не видна проверке.
# YARD_KINDS, YARD_SKIP, YARD_KIT — В ПАСПОРТЕ: чем обставлен двор, это лицо
# города. Механизм двора (система «вдоль фронта / вглубь от задней грани»,
# П-образный плетень, правило «цепь или ничего») — здесь.

def dist_to_roads(px, pz):
    best = 1e9
    for rd in PLAN["roads"]:
        for (x0, z0), (x1, z1) in zip(rd["pts"], rd["pts"][1:]):
            vx, vz = x1-x0, z1-z0
            L2 = vx*vx + vz*vz
            t = max(0.0, min(1.0, ((px-x0)*vx + (pz-z0)*vz) / L2))
            best = min(best, math.hypot(px - (x0+vx*t), pz - (z0+vz*t)) - rd["w"]/2)
    return best

def spot_free(px, pz, r, skip=None):
    """Место под клаттер: не в теле дома, не на полосе дороги, не на площади."""
    if on_plaza(px, pz) or dist_to_roads(px, pz) < r:
        return False
    if not (1.0 <= px <= LAST and 1.0 <= pz <= LAST):
        return False
    for (cx, cz, w, d, yaw, n) in PLACED:
        if n == skip:
            continue
        c = math.cos(math.radians(yaw))
        sn = math.sin(math.radians(yaw))
        dx, dz = px - cx, pz - cz
        lx = dx*c - dz*sn
        lz = dx*sn + dz*c
        if abs(lx) < w/2 + r and abs(lz) < d/2 + r:
            return False
    # река: клаттер не стоит в воде
    if any(d < r["half_w"] + 1.0 for d, r in river_near(px, pz)):
        return False
    return True

FORGE_SPOTS = []   # (x, z, радиус) — занятое кузнечным набором во дворе

def smithy_yard():
    """ДВОР КУЗНИЦЫ: ГОРН, НАКОВАЛЬНЯ, ЗАКАЛОЧНАЯ БОЧКА (выпечка кузни-2).
    Кузница отличалась от жилого дома только износом стен: у неё был очаг в
    доме и общий дворовый набор — поленница, бочка, плетень, — то есть двор
    сапожника и двор кузнеца выглядели одинаково.
    Расстановка ремесленная, а не декоративная: горн ЗАДОМ К ГЛУХОЙ СТЕНЕ
    двора (у него дымовая труба, e19-e22 — короб 1.35..1.95, ей нужна стена),
    наковальня в 1.2 м ОТ УСТЬЯ горна (замер: огонь горна стоит на локальных
    (0.80,0.55) при габарите 1.60x1.00 — расстояние меряется от него, а не от
    угла детали), закалочная бочка вплотную к наковальне со стороны прохода.
    Числа посадки — с рецептов через recipe_box, посадка по земле (ground) со
    вкопом 0.03, как у всего дворового набора."""
    n = 0
    for (rec, ox, oy, oz, yaw, w, d, name) in FRAMES:
        if rec != KIND["smithy"]:
            continue
        lcx, lcz, _, _, axis, _ = recipe_box(rec)
        back = {"+Z": (0.0, -1.0), "-Z": (0.0, 1.0),
                "+X": (-1.0, 0.0), "-X": (1.0, 0.0)}[axis]
        along = (-back[1], back[0])
        span_m = d if axis in ("+X", "-X") else w
        bx = lcx + back[0]*(w/2 if axis in ("+X", "-X") else 0.0)
        bz = lcz + back[1]*(d/2 if axis in ("+Z", "-Z") else 0.0)
        yaw_along = math.degrees(math.atan2(-along[1], along[0])) % 360.0

        def put(ff, t, deep, extra, rad, note):
            """t — вдоль задней грани от её середины, deep — вглубь двора;
            точка задаёт ЦЕНТР габарита детали, origin считается от него."""
            nonlocal n
            lx = bx + along[0]*t + back[0]*deep
            lz = bz + along[1]*t + back[1]*deep
            mx, mz = loc_to_world(ox, oz, yaw, lx, lz)
            if dist_to_roads(mx, mz) < 0.5 or not spot_free(mx, mz, rad, skip=name):
                print(f"  двор кузницы: {ff} ставить некуда "
                      f"(до дороги {dist_to_roads(mx, mz):.2f} м)")
                return
            iyaw = (yaw + yaw_along + extra) % 360.0
            rcx, rcz, _, _, _, _ = recipe_box(ff)
            c2 = math.cos(math.radians(iyaw))
            s2 = math.sin(math.radians(iyaw))
            gy = (oy if ground(mx, mz) is None else ground(mx, mz)) - 0.03
            fox = mx - (rcx*c2 + rcz*s2)
            foz = mz - (-rcx*s2 + rcz*c2)
            house(ff, fox, gy, foz, iyaw, "кузнечный двор: " + name)
            if ff == "furn-forge-hearth.dfh":
                # ГОРН ГОРИТ. Пламя рецепта стоит на локальных (0.80,0.55) и
                # идёт от 0.89 до 1.23 — точка света в его середине, 1.05.
                # Ни interior, ни room: горн под открытым небом, ему нечего
                # ограничивать, и тени ему не полагается (кубовых слотов два,
                # оба у залов).
                lfx, lfz = loc_to_world(fox, foz, iyaw, 0.80, 0.55)
                lamp("forge", lfx, gy + 1.05, lfz, "горн: " + name)
            FORGE_SPOTS.append((mx, mz, rad))
            n += 1
            return (mx, mz)

        # горн: длинной стороной (1.60) вдоль глухой стены, спиной к ней
        put("furn-forge-hearth.dfh", 0.0, 0.65, 0.0, 0.9, "горн")
        # ...устье горна на локальных (0.80,0.55) при центре (0.80,0.50), то
        # есть на 0.05 ближе к стене: от него и меряется рабочее место
        put("furn-anvil.dfh", 0.0, 0.60 + 1.20, 90.0, 0.6, "наковальня")
        put("furn-quench.dfh", 0.95, 0.60 + 1.05, 0.0, 0.45, "бочка")
    return n

# ЦЕПЬ ПЛЕТНЯ КОРОЧЕ ЭТОГО — НЕ ОГРАДА (звено 2 м; три звена это 6 м, то есть
# двор рядового дома по задней грани).
FENCE_MIN_LINKS = 3

def yards():
    n_items = 0
    n_fence_drop = 0
    for i, (rec, ox, oy, oz, yaw, w, d, name) in enumerate(FRAMES):
        if rec in YARD_SKIP:
            continue  # у доминант двор не бытовой
        # ЗАДНЯЯ ГРАНЬ — ПРОТИВОПОЛОЖНАЯ ДВЕРНОЙ, а дверь у рецептов не всегда
        # на z=d: у мельницы она на x=0, и двор, посчитанный «за z<0», уходил
        # ей в бок. Строим двор в системе (вдоль фронта, вглубь от задней грани).
        lcx, lcz, _, _, axis, _ = recipe_box(rec)
        back = {"+Z": (0.0, -1.0), "-Z": (0.0, 1.0),
                "+X": (-1.0, 0.0), "-X": (1.0, 0.0)}[axis]
        along = (-back[1], back[0])
        span_m = d if axis in ("+X", "-X") else w
        # точка на задней грани, от центра габарита
        bx = lcx + back[0]*(w/2 if axis in ("+X", "-X") else 0.0)
        bz = lcz + back[1]*(d/2 if axis in ("+Z", "-Z") else 0.0)
        def yard_loc(t, deep):
            """t — вдоль задней грани от её начала, deep — вглубь двора."""
            return (bx + along[0]*(t - span_m/2) + back[0]*deep,
                    bz + along[1]*(t - span_m/2) + back[1]*deep)
        # поворот, при котором +X детали ложится ВДОЛЬ задней грани (звенья
        # плетня и поленница длинные по x)
        yaw_along = math.degrees(math.atan2(-along[1], along[0])) % 360.0
        # НАБОР ДВОРА — ИЗ ПАСПОРТА. Строка «span-1.0» значит «в метре от
        # дальнего угла задней грани»: t считается от её НАЧАЛА, и записать
        # там число нельзя — грань у каждого дома своей длины.
        def yard_t(v):
            return (span_m + float(v[4:]) if isinstance(v, str) else v)
        kit = [(ff, yard_t(t), deep, rad) for ff, t, deep, rad in YARD_KIT]
        if span_m >= YARD_WIDE_M:
            kit += [(ff, yard_t(t), deep, rad)
                    for ff, t, deep, rad in YARD_KIT_WIDE]
        for ff, t, deep, rad in kit:
            lx, lz = yard_loc(t, deep)
            lyaw = yaw_along
            mx, mz = loc_to_world(ox, oz, yaw, lx, lz)
            if not spot_free(mx, mz, rad, skip=name):
                continue
            # кузнечный набор двора занимает место раньше бытового
            if any(math.hypot(mx-fx, mz-fz) < rad + fr
                   for fx, fz, fr in FORGE_SPOTS):
                continue
            gy = ground(mx, mz)
            house(ff, mx, (oy if gy is None else gy) - 0.03, mz,
                  (yaw + lyaw) % 360.0, "двор: " + name)
            n_items += 1
        # --- МЕЖЕВОЙ ПЛЕТЕНЬ: ОГРАДА, А НЕ ЛИНИЯ ДОСОК --------------------
        # ПРЕТЕНЗИЯ ВЛАДЕЛЬЦА (круг 6): «заборы, стоящие на открытом газоне и
        # ничего не огораживающие; доски под случайными углами». Обе — про одно
        # и то же устройство: плетень был ОДНИМ ПРЯМЫМ ПРОГОНОМ поперёк двора,
        # каждое звено садилось поодиночке, и уцелевшие звенья оставались
        # стоять на траве. Прямая линия не огораживает НИЧЕГО по определению —
        # огораживает ЗАМКНУТЫЙ обход; а «случайные углы» это те же звенья
        # разных домов, каждый со своим джиттером поворота ±3 гр.
        # Два правила, и оба взяты у бордюра этой же волны:
        #   1. ФОРМА — П: прогон вдоль задней грани плюс два ВОЗВРАТА к дому.
        #      Вместе с глухой стеной это замкнутый двор, а не черта на газоне.
        #   2. ЦЕПЬ ИЛИ НИЧЕГО: если хоть один возврат не встал или в прогоне
        #      уцелело меньше FENCE_MIN_LINKS звеньев — плетень не ставится
        #      ВОВСЕ. Половина ограды — это не половина пользы, это мусор.
        deep_fence = 3.6 + (i % 3) * 0.35
        span = max(2, int(round(span_m / 2.0)))
        yaw_across = (yaw_along + 90.0) % 360.0
        plan = []
        for k in range(span):
            kind = "furn-fence-gate.dfh" if k == span // 2 else "furn-fence2.dfh"
            plan.append((kind, (span_m / span) * k, deep_fence, yaw_along, True))
        # возвраты: по звену от каждого конца прогона к задней грани дома
        for t_end in (0.0, span_m):
            plan.append(("furn-fence2.dfh", t_end, deep_fence - 2.0,
                         yaw_across, False))
        put, links, returns_ok = [], 0, 0
        for ff, t, deep, lyaw, is_run in plan:
            lx, lz = yard_loc(t, deep)
            mx, mz = loc_to_world(ox, oz, yaw, lx, lz)
            if not spot_free(mx, mz, 0.5, skip=name):
                continue
            if any(math.hypot(mx-fx, mz-fz) < 0.5 + fr
                   for fx, fz, fr in FORGE_SPOTS):
                continue
            put.append((ff, mx, mz, (yaw + lyaw) % 360.0))
            links += 1 if is_run else 0
            returns_ok += 0 if is_run else 1
        if links >= FENCE_MIN_LINKS and returns_ok == 2:
            for ff, mx, mz, fyaw in put:
                gy = ground(mx, mz)
                house(ff, mx, (oy if gy is None else gy) - 0.03, mz, fyaw,
                      "двор: " + name)
                n_items += 1
        else:
            n_fence_drop += len(put)
    if n_fence_drop:
        print(f"дворы: {n_fence_drop} звеньев плетня снято — незамкнутая "
              f"ограда на открытом газоне ничего не огораживает")
    return n_items

# =============================================================================
# ТОЧКИ ПРИТЯЖЕНИЯ (заказ владельца 22.08: «сделай минимум 3 точки притяжения,
# сейчас всё одно и скучно»)
# =============================================================================
# ТОЧКА ПРИТЯЖЕНИЯ — ЭТО НЕ КУЧА ПРЕДМЕТОВ, А МЕСТО, ГДЕ ЕСТЬ ЧТО ДЕЛАТЬ И ГДЕ
# ХОЧЕТСЯ ОСТАНОВИТЬСЯ. Гайд §10 разбирает это тремя признаками, и все три
# проверяемы: (1) ПОЛ — площадка отличается от улицы полотном, а не только
# предметами; (2) КРАЙ — по периметру есть на что сесть и обо что опереться;
# (3) ЯДРО — в середине стоит одна вещь, ради которой сюда идут. Поэтому у
# каждой из трёх точек ниже сначала полотно, потом кромка, и только потом
# мелочь.
# ТРИ ТОЧКИ И ПОЧЕМУ ИМЕННО ЭТИ:
#   1. СКВЕР ГИЛДЕРГРИНА — ядро дано (дерево, табу владельца), нужен пол и
#      кромка. Середина города, на пересечении главной улицы и улицы Ветров.
#   2. РЫНОК — ядро колодец, кромка торговые ряды. Низ города, вход с юга.
#   3. ПАРАДНЫЙ ДВОР ДРАКОНЬЕГО ПРЕДЕЛА — ВЫБРАН МНОЙ, и вот довод. Двор
#      таверны и двор кузницы стоят В ТЕХ ЖЕ ДВУХ МЕСТАХ, что рынок и сквер
#      (таверна — восточная кромка рынка, кузница — южный переулок в сорока
#      метрах от них): третья точка там не добавила бы городу ни высоты, ни
#      нового вида, а только уплотнила бы уже плотное. У замка обратное: там
#      кончается процессионная ось, и сегодня она кончается СТЕНОЙ — прибор
#      check_layout прямо это и печатает («на дороге (stone): ЗАМОК»), а
#      check_axis списывает последние 5.3 м как «под зданием». Двор превращает
#      тупик в цель (гайд §11: улицы упираются в доминанты — но упираться надо
#      В МЕСТО, а не в кладку), и он на 8 м выше рынка: с его южной кромки
#      виден весь город и долина за стеной. Три точки расходятся по высоте
#      (27 / 30 / 35 м) и по смыслу (торг / община / власть), а не стоят в ряд.
DECOR = []      # (x, z, r) — уже занятое убранством точек притяжения

def decor_free(px, pz, r, skip=None, on_square=False):
    """Место под предмет точки притяжения: свободно по всем прежним правилам
    (тела, полосы дорог, река) И не занято другим предметом этой же волны.
    Второе условие пришлось назвать отдельно: spot_free знает только PLACED,
    то есть ПОСТРОЙКИ, и три скамьи подряд встали бы в одну точку.
    ...А ПЕРВОЕ ПРИШЛОСЬ ОСЛАБИТЬ ФЛАГОМ, и это не поблажка. spot_free
    отказывает ВСЕМУ, что попало на прямоугольник площади (on_plaza) — правило
    писалось для ДВОРОВОГО КЛАТТЕРА, чтобы поленница соседа не вылезла на
    торговую площадь. Убранству САМОЙ площади оно запрещало ровно то, ради чего
    его зовут: первый прогон дал «рынок: 0 предметов оживления». Мера,
    приложенная не к своему предмету, четвёртый раз за этот город."""
    if on_square:
        if dist_to_roads(px, pz) < r:
            return False
        for (cx, cz, w, d, yaw, n) in PLACED:
            if n == skip:
                continue
            c = math.cos(math.radians(yaw))
            sn = math.sin(math.radians(yaw))
            dx, dz = px - cx, pz - cz
            if abs(dx*c - dz*sn) < w/2 + r and abs(dx*sn + dz*c) < d/2 + r:
                return False
    elif not spot_free(px, pz, r, skip=skip):
        return False
    return all(math.hypot(px-ax, pz-az) >= r + ar for ax, az, ar in DECOR)

def hold(px, pz, r):
    DECOR.append((px, pz, r))

def body_origin(rec, cx, cz, yaw_deg):
    """origin рецепта, при котором ЦЕНТР его габарита ляжет в (cx, cz).
    Та же поправка, которой садятся прилавки и жаровни: origin лежит в углу
    детали, и смещение от центра к углу ОБЯЗАНО поворачиваться матрицей сцены
    (три дефекта этого города подряд были ровно этой ошибкой)."""
    lcx, lcz, _w, _d, _a, _o = recipe_box(rec)
    c = math.cos(math.radians(yaw_deg))
    s = math.sin(math.radians(yaw_deg))
    return (cx - (lcx*c + lcz*s), cz - (-lcx*s + lcz*c))

def sit_at(Hh, cx, cz, w, d, yaw_deg, sink=0.03):
    """Отметка предмета: минимум ПОЛЯ ЭТОГО ПРОХОДА по его пятну, со вкопом.
    Мерить надо Hh, а не ground(): ground — дамп прошлого прогона, а земля
    сквера в этом уже спланирована."""
    return min(hh_at(Hh, px, pz)
               for px, pz in rect_points(cx, cz, w, d, yaw_deg, n=3)) - sink

BENCH_REC = "furn-bench.dfh"     # 1.60 x 0.35 (замер .dfh)
BENCH_ARC = "furn-bench-arc.dfh"  # сегмент кольцевой скамьи, 45 гр. (кузня-3)
# BUSH_KINDS / BUSH_R / FLOWER_KINDS / CITY_FLOWER_SCALE — В ПАСПОРТЕ: это
# биом. Радиусы кустов там же, потому что они свойство ВЫБРАННЫХ рецептов.
# ФОНАРИ КУЗНИ-3. Точка света — ГЕОМЕТРИЧЕСКИЙ ЦЕНТР СТЕКЛА в локали рецепта
# (замер кузницы: у столба стекло 2.350..2.650, точка 2.500). Выше, на макушку,
# ставить нельзя: короб даст тень сам на себя и получится «фонарь с чёрной
# серединой». Само тело НЕ светится — .dfh эмиссии не умеет, светит только
# [light], поэтому фонарь без своей строки огня — мёртвая палка.
LAMP_REC = {
    "post":  ("furn-lamp-post.dfh",   (0.700, 2.500, 0.220), 0.84, 0.40),
    "posts": ("furn-lamp-post-s.dfh", (0.620, 2.200, 0.200), 0.75, 0.40),
    "wall":  ("furn-lamp-wall.dfh",   (0.180, 2.340, 0.460), 0.29, 0.61),
}
PLANTER_REC = ("furn-planter.dfh", "furn-planter-w.dfh")
PLANTER_SOIL = 0.290    # верх земли в цветнике (замер кузницы) — на неё цветы

def put_bench(Hh, cx, cz, yaw_deg, note, on_square=False):
    if not decor_free(cx, cz, 0.95, on_square=on_square):
        return 0
    ox, oz = body_origin(BENCH_REC, cx, cz, yaw_deg)
    house(BENCH_REC, ox, sit_at(Hh, cx, cz, 1.6, 0.35, yaw_deg), oz,
          yaw_deg, note)
    hold(cx, cz, 0.9)
    return 1

def put_bush(Hh, cx, cz, i, note, r=None, on_square=False):
    kind = BUSH_KINDS[i % len(BUSH_KINDS)]
    rad = BUSH_R[kind] if r is None else r
    if not decor_free(cx, cz, rad * 0.55, on_square=on_square):
        return 0
    place(kind, cx, sit_at(Hh, cx, cz, 0.6, 0.6, 0.0, sink=0.05), cz,
          (i * 53) % 360, note)
    hold(cx, cz, rad * 0.55)
    return 1

def put_flowers(Hh, cx, cz, i, note):
    place(FLOWER_KINDS[i % 3], cx, sit_at(Hh, cx, cz, 0.4, 0.4, 0.0, sink=0.02),
          cz, (i * 71) % 360, note, scale=CITY_FLOWER_SCALE)
    return 1

def put_lamp_post(Hh, cx, cz, note, small=False, kind="lamp", yaw=None,
                  on_square=False):
    """ФОНАРЬ-СТОЛБ КУЗНИ-3. Точка света считается ИЗ ЛОКАЛИ РЕЦЕПТА и
    поворачивается матрицей сцены — так же, как смещение к углу у прилавков и
    жаровен. Записать «свет над столбом» мировой прибавкой значило бы
    повторить ту же ошибку четвёртый раз за город."""
    rec, loc, rw, rd = LAMP_REC["posts" if small else "post"]
    if not decor_free(cx, cz, max(rw, rd)/2 + 0.25, on_square=on_square):
        return 0
    lyaw = (int(cx*11 + cz*7) % 360) if yaw is None else yaw
    ox, oz = body_origin(rec, cx, cz, lyaw)
    gy = sit_at(Hh, cx, cz, rw, rd, lyaw)
    house(rec, ox, gy, oz, lyaw, note)
    fx, fz = loc_to_world(ox, oz, lyaw, loc[0], loc[2])
    lamp(kind, fx, gy + loc[1], fz, note,
         radius=4.5 if small else None)
    hold(cx, cz, max(rw, rd)/2 + 0.25)
    return 1

def put_wall_lamp(Hh, wx, wz, out_x, out_z, note):
    """НАСТЕННЫЙ ФОНАРЬ У ДВЕРИ. Плоскость крепления рецепта — ровно z=0
    (спинка садится на грань стены), тело уходит в +Z, значит локальный +Z
    обязан смотреть НАРУЖУ из стены: yaw = atan2(out_x, out_z). Origin
    ставится НА грань стены и на отметку земли — рецепт сам живёт по высоте
    2.16..2.72."""
    rec, loc, _rw, _rd = LAMP_REC["wall"]
    lyaw = math.degrees(math.atan2(out_x, out_z)) % 360.0
    gy = sit_at(Hh, wx, wz, 0.4, 0.4, 0.0, sink=0.0)
    house(rec, wx, gy, wz, lyaw, note)
    fx, fz = loc_to_world(wx, wz, lyaw, loc[0], loc[2])
    lamp("door", fx, gy + loc[1], fz, note)
    return 1

def put_brazier(Hh, cx, cz, note, on_square=False):
    if not decor_free(cx, cz, BRAZIER_CLEAR, on_square=on_square):
        return 0
    gy = sit_at(Hh, cx, cz, 0.72, 0.72, 0.0)
    byaw = (int(cx * 7) % 40) - 20
    ox, oz = body_origin("furn-brazier-fire.dfh", cx, cz, byaw)
    house("furn-brazier-fire.dfh", ox, gy, oz, byaw, note)
    lamp("brazier", cx, gy + BRAZIER_LIGHT, cz, note)
    BRAZIER_AT.append((cx, cz))
    hold(cx, cz, BRAZIER_CLEAR)
    return 1

# =============================================================================
# МЕСТА: ДЕСЯТЬ МЕХАНИЗМОВ И ТАБЛИЦА PLACES ПАСПОРТА
# =============================================================================
# Было 488 строк про конкретные Гилдергрин, рынок и двор замка. Стало: пол
# (мощёный круг / прямоугольник / партер), кромка (кольцо скамей), развёртка по
# углу, раскладка по карте свободы, ядро, торговый ряд, ореол, терраса — и
# таблица PLACES, которая их составляет. Ни один механизм не написан «про
# запас»: все работают в этих же трёх местах, а площадь без рядов, святилище
# или смотровая кромка — это ДРУГИЕ ПАРАМЕТРЫ тех же механизмов.
#
# ПОЧЕМУ МЕСТО РАЗБИТО НА ФАЗЫ, А НЕ НА ОДНУ ФУНКЦИЮ. Порядок house()/place()/
# lay() задаёт порядок СТРОК в файле, а фазы места стоят в разных местах
# конвейера: площадку рынка надо спланировать до полотна трактов, полотно
# площади положить после расстановки домов, жизнь вокруг колодца — после
# полотна, убранство сквера — после дворов (кто раньше, тот и занял место), а
# террасу — последней. Поэтому оркестратор идёт по ФАЗАМ и спрашивает у каждого
# места только те, что у него есть.

def place_at(pl):
    """Точка места: явная ссылка в чертёж («gildergreen») или центр его пятна."""
    if "at" in pl:
        p = plan_ref(pl["at"])
        return float(p[0]), float(p[1])
    rx, rz, rw, rd = plan_ref(pl["rect"])
    return rx + rw/2.0, rz + rd/2.0

def place_grade(pl, Hh):
    """ФАЗА 1 — ПЛОЩАДКА. Место стоит на РОВНОМ: под жёсткой плитой, кольцевой
    скамьёй и торговым рядом неровность читается либо висящим телом, либо
    обрывом на кромке. Возвращает спланированный прямоугольник (его потом
    минуют полотно трактов и пады домов) или None."""
    g = pl.get("grade")
    if not g:
        return None
    if "rect" in g:
        x0, z0, w, d = plan_ref(g["rect"])
    else:
        cx, cz = place_at(pl)
        w = d = float(g["square"])
        x0, z0 = cx - w/2.0, cz - d/2.0
    grade_rect(Hh, x0, z0, w, d, g["feather"])
    return (x0, z0, w, d)

# --- МЕХАНИЗМ: МОЩЁНЫЙ ПРЯМОУГОЛЬНИК ШТРИХОВКОЙ ------------------------------
def pave_rect(x0, z0, w, d, half, over, inset, note, cls=0):
    """Площадь мостится ТЕМ ЖЕ ПОЛОТНОМ, что улицы: широкие мазки поперёк и
    вдоль, шаг между осевыми pave_pitch — соседние ленты смыкаются ПЛОСКИМИ
    ВЕРШИНАМИ, а не спадами. Иначе между мазками осталась бы полоса
    половинного износа — трава в клетку.
    Поперечные торчат за пятно на over (кромка не гребёнка), продольные НЕ
    ТОРЧАТ (inset): свес с каждого конца делал контур площади лопастным
    крестом, а не прямоугольником."""
    pitch = pave_pitch(half)
    n_row = max(1, int(math.ceil(d / pitch)))
    for k in range(n_row + 1):
        zr = z0 + d * (k / n_row)
        lay([(x0 - over, zr), (x0 + w + over, zr)], half, cls, note)
    n_col = max(1, int(math.ceil(w / pitch)))
    for k in range(n_col + 1):
        xr = x0 + w * (k / n_col)
        lay([(xr, z0 + inset), (xr, z0 + d - inset)], half, cls, note)

# --- МЕХАНИЗМ: МОЩЁНОЕ КОЛЬЦО ВОКРУГ ГОЛОГО ЯДРА ----------------------------
def pave_ring(cx, cz, bare_r, half, slack, note, cls=0):
    """Кольцевой мазок — ОДНА лента постоянного радиуса, а не набор хорд,
    поэтому поле износа у неё зависит только от |r - r_mid|. Хорды сходились на
    ободе и расходились у центра; у кольца этой болезни нет ПО ПОСТРОЕНИЮ:
    ширина полки одна на всю окружность.
    СЕРЕДИНА МАЗКА ВЫВОДИТСЯ ИЗ ГОЛОГО КРУГА, А НЕ ИЗ ОБОДА: заказан именно
    круг земли, обод — следствие. Внутренняя граница камня лежит на
    r_mid - half, значит r_mid = bare_r + half; обод выходит на
    r_mid + half - FADE_M.
    ...ПЛЮС ЛАДОНЬ (slack), И ОНА ВЫВЕДЕНА, А НЕ НАЗНАЧЕНА: кривая полотна —
    не окружность, а её выборка ломаной, и радиус у неё на 7 мм меньше
    заказанного. Семь миллиметров и есть те четыре пробы камня на ободе круга.
    ЗАМКНУТАЯ ЛЕНТА ВЕДЁТСЯ С ЗАХЛЁСТОМ ЗА ШОВ, А НЕ ВСТЫК: центростремительный
    Catmull-Rom движка на КОНЦАХ ломаной зажимает соседа, и у первого и
    последнего звена узел вырожден — кривая уходит внутрь. Замер: встык 4 пробы
    камня внутри круга, с захлёстом в два звена 0.
    Возвращает (r_mid, R обода)."""
    r_mid = bare_r + half + slack
    R = r_mid + (half - FADE_M)
    n_k = max(24, int(math.ceil(2*math.pi*r_mid / 0.8)))
    ring = [(cx + math.cos(2*math.pi*k/n_k)*r_mid,
             cz + math.sin(2*math.pi*k/n_k)*r_mid) for k in range(-2, n_k + 3)]
    lay(ring, half, cls, note)
    return r_mid, R

# --- МЕХАНИЗМ: ПАРТЕР ПЕРЕД ФАСАДОМ ------------------------------------------
def pave_apron(fx, fz, ux, uz, tx, tz, fl, cls=0):
    """Пол двора перед зданием: поперечные мазки на выносе out0+1 и дальше,
    плюс осевой, доводящий процессионную ось до самого крыльца."""
    yp = pave_pitch(fl["half"])
    out0 = fl["out0"]
    n_yr = max(3, int(math.ceil(fl["rows"] / yp)) + 1)
    wing = fl["wing"]
    for k in range(n_yr):
        out_m = out0 + 1.0 + yp * k
        cxm, czm = fx + ux*out_m, fz + uz*out_m
        lay([(cxm - tx*wing, czm - tz*wing), (cxm + tx*wing, czm + tz*wing)],
            fl["half"], cls, fl["note"])
    a, b = fl["run"]
    lay([(fx + ux*(out0 + a), fz + uz*(out0 + a)),
         (fx + ux*(out0 + b), fz + uz*(out0 + b))], fl["half"], cls, fl["note"])

# --- МЕХАНИЗМ: РАЗВЁРТКА ПО УГЛУ ---------------------------------------------
def sweep(cx, cz, n_want, radius, put, step_deg=12.0, start_deg=0.0):
    """Фиксированные слоты «через 120 градусов» ставили один фонарь из трёх:
    две трети окружности сквера лежат на полосах двух улиц, и слот, попавший на
    проезжую часть, просто пропадал. Развёртка спрашивает много углов и берёт
    первые N подошедших — заказанное число выполняется, а несевшее печатается
    вслух, а не молчит."""
    got, k = 0, 0
    n_step = int(360.0 / step_deg)
    while got < n_want and k < n_step:
        a = math.radians(start_deg + k * step_deg)
        if put(cx + math.cos(a)*radius, cz + math.sin(a)*radius, a, got):
            got += 1
        k += 1
    return got

# --- МЕХАНИЗМ: КАРТА СВОБОДЫ --------------------------------------------------
def free_radius(px, pz):
    """Свободный радиус клетки: до кромки полос дорог и до тел построек;
    внутри тела — минус девять (то есть «сюда нельзя вовсе»)."""
    r = dist_to_roads(px, pz)
    for (cx2, cz2, w2, d2, y2, _n2) in PLACED:
        c2 = math.cos(math.radians(y2))
        s2 = math.sin(math.radians(y2))
        ddx, ddz = px - cx2, pz - cz2
        lx2 = abs(ddx*c2 - ddz*s2) - w2/2
        lz2 = abs(ddx*s2 + ddz*c2) - d2/2
        r = min(r, math.hypot(max(lx2, 0.0), max(lz2, 0.0))
                if (lx2 > 0 or lz2 > 0) else -9.0)
    return r

# --- МЕХАНИЗМ: ОДИН ПРЕДМЕТ НАБОРА -------------------------------------------
def put_item(Hh, what, px, pz, spec, i=0, yaw=None, on_square=False):
    """Ставит предмет по имени вида. Один вход на все места: набор двора,
    набор площади и набор сквера различаются ЧИСЛАМИ, а не кодом."""
    if what == "bench":
        return put_bench(Hh, px, pz,
                         (int(px*37) % 360) if yaw is None else yaw,
                         spec["note"], on_square=on_square)
    if what == "lamp":
        return put_lamp_post(Hh, px, pz, spec["note"],
                             kind=spec.get("light", "lamp"),
                             on_square=on_square)
    if what == "brazier":
        return put_brazier(Hh, px, pz, spec["note"], on_square=on_square)
    if what == "bush":
        return put_bush(Hh, px, pz, i, spec["note"], on_square=on_square)
    if what == "crate":
        # ТАРА: два рецепта через один, разворот из позиции — экземплярное
        # лицо без random(), как у дрожи огня.
        if not decor_free(px, pz, spec["clear"], on_square=on_square):
            return 0
        rec = spec["recs"][1] if i % 3 else spec["recs"][0]
        byaw = (int(px*53 + pz*29)) % 360
        ox, oz = body_origin(rec, px, pz, byaw)
        house(rec, ox, sit_at(Hh, px, pz, 0.7, 0.7, byaw), oz, byaw,
              spec["note"])
        hold(px, pz, spec["clear"])
        return 1
    raise KeyError(what)

# --- МЕХАНИЗМ: КОЛЬЦО СКАМЕЙ --------------------------------------------------
def bench_ring(Hh, cx, cz, br):
    """Сегменты ставятся В ОДНУ ТОЧКУ (у рецепта начало детали — ЦЕНТР кольца,
    дуга симметрична вокруг локального +X) и различаются только yaw. Посадка по
    земле ЯДРА, а не каждого сегмента: кольцо обязано быть горизонтальным,
    иначе оно перестаёт быть кольцом.
    ПРОБА — ПО ТРЁМ ТОЧКАМ ДУГИ, А НЕ ПО ОДНОЙ СЕРЕДИНЕ: сегмент это дуга 3.2 м
    длиной, и одна проба радиусом «на весь сегмент» отказывала там, где мешало
    что-то в полутора метрах ЗА кромкой (первый прогон: одна скамья из восьми).
    КОЛЬЦО СЕБЯ НЕ ДЕРЖИТ, и это не небрежность: сегменты СМЫКАЮТСЯ по
    построению (соседние концы дуг в 0.40 м), поэтому любой держатель шире
    0.2 м запрещает соседа сам себе. Пересечься они не могут — общий центр и
    разные секторы, — а всё остальное убранство уведено за наружную кромку
    сиденья по РАДИУСУ."""
    n = br["n"]
    ring_y = sit_at(Hh, cx, cz, br["sit"], br["sit"], 0.0)
    # КОЛЬЦО ГОРИЗОНТАЛЬНО — ЗНАЧИТ ОНО МЕРИТСЯ ПО ВСЕЙ СВОЕЙ ПОЛОСЕ, а полоса
    # у него шириной в свой поперечник: минимум по такому пятну лежит НИЖЕ
    # земли под самим сиденьем ровно на уклон места. Печатаем это число, потому
    # что владелец сказал «кольцевая скамья не видна», и утопленность — первый
    # подозреваемый, которого до сих пор никто не мерил.
    _seat = [hh_at(Hh, cx + math.cos(math.radians(k*360.0/n))*br["r"],
                   cz + math.sin(math.radians(k*360.0/n))*br["r"])
             for k in range(n)]
    print(f"кольцевая скамья: посадка {ring_y:.2f}, земля под дугами "
          f"{min(_seat):.2f}..{max(_seat):.2f} — утоплена на "
          f"{max(_seat) - ring_y:.2f} м в худшей точке")
    gap_k, n_b = set(), 0
    for k in range(n):
        a = math.radians(k * 360.0/n)
        arc = [(cx + math.cos(a + da)*br["r"], cz + math.sin(a + da)*br["r"])
               for da in (-br["arc"], 0.0, br["arc"])]
        if not all(decor_free(px, pz, br["clear"]) for px, pz in arc):
            gap_k.add(k)
            continue
        house(br["rec"], cx, ring_y, cz, (-k * 360.0/n) % 360.0, br["note"])
        n_b += 1
    return n_b, gap_k

# --- МЕХАНИЗМ: ЦВЕТНИК ---------------------------------------------------------
def put_planter(Hh, px, pz, a, idx, note, flowers_note):
    """Короб цветника плюс четыре цветка НА ЕГО ЗЕМЛЕ (верх 0.290, замер
    кузницы), а не на копинге и не рядом с коробом."""
    if not decor_free(px, pz, 0.85):
        return 0
    prec = PLANTER_REC[idx % 2]
    byaw = (-math.degrees(a)) % 360.0
    ox, oz = body_origin(prec, px, pz, byaw)
    gy = sit_at(Hh, px, pz, 1.26, 1.26, byaw)
    house(prec, ox, gy, oz, byaw, note)
    hold(px, pz, 0.85)
    for j, (lx, lz) in enumerate(((0.35, 0.35), (0.88, 0.40),
                                  (0.40, 0.88), (0.88, 0.88))):
        fpx, fpz = loc_to_world(ox, oz, byaw, lx, lz)
        place(FLOWER_KINDS[(idx + j) % 3], fpx, gy + PLANTER_SOIL, fpz,
              (idx*97 + j*41) % 360, flowers_note,
              scale=CITY_FLOWER_SCALE)
    return 1

# --- ФАЗА: ПОЛОТНО И ЯДРО ПЛОЩАДИ --------------------------------------------
def place_floor(pl, Hh):
    """ФАЗА 2 — ПОЛ ПЛОЩАДИ. Только у прямоугольных мест: пол сквера кладётся
    вместе с его убранством (фаза 6), потому что зависит от голого круга."""
    # DFN_GEN_NO_COBBLE=1 собирает ту же сцену без мощения площади — рука A
    # замера цены мощения из одного бинарника.
    if pl["kind"] != "market" or os.environ.get("DFN_GEN_NO_COBBLE") == "1":
        return
    x0, z0, w, d = plan_ref(pl["rect"])
    fl = pl["floor"]
    pave_rect(x0, z0, w, d, fl["half"], fl["over"], fl["inset"], fl["note"])
    SQUARES.append((pl["name"], "rect", (x0, z0, w, d), 0))

def place_core(pl, Hh):
    """ФАЗА 3 — ЯДРО ПЛОЩАДИ И ТОРГОВЫЙ РЯД. Ядро садится на ЗЕМЛЮ по своему
    пятну, как всякое тело: плиты под ним больше нет.
    Ядро уходит в ОРИЕНТИРЫ (LANDMARKS): оно ставится мимо resolve_frames и
    мимо check_layout, и потому может встать посреди улицы, а прибор промолчит.
    Ровно это и было — колодец стоял в узле главной улицы."""
    if pl["kind"] != "market":
        return None
    co = pl["core"]
    wx, wz = plan_ref(co["at"])
    bx, bz = co["body"]
    sw, sd = co["size"]
    y = min(hh_at(Hh, px, pz)
            for px, pz in rect_points(wx + bx, wz + bz, sw, sd, 0.0,
                                      n=5)) - co["sink"]
    house(co["rec"], wx, y, wz, 0, co["note"])
    _cx, _cz, _w, _d, _a, _o = recipe_box(co["rec"])
    LANDMARKS.append((co["note"], wx + _cx, wz + _cz, _w, _d, 0.0, False))
    st = pl.get("stalls")
    if st:
        stall_row(Hh, st)
    return (wx, wz, y)

def stall_row(Hh, st):
    """ТОРГОВЫЙ РЯД. Точка чертежа — ЦЕНТР прилавка, и смещение к углу ОБЯЗАНО
    поворачиваться матрицей сцены: стояло `sx - 1.2, sz - 0.5` — верно только
    при yaw 0, а лотки повёрнуты на 173-187 гр., и тело уезжало на две своих
    половины, поперёк осевой главной улицы.
    Поворот у каждого свой (гайд §11: ни одно здание не параллельно соседнему),
    посадка по СВОЕМУ пятну: лотки садились на отметку плиты, а стоят они на
    земле рядом с ней — ножки висели над травой."""
    base, spin = st["yaw"]
    sw, sd = st["size"]
    gd, bk = st["goods"], st["back"]
    for i, (sx, sz) in enumerate(plan_ref(st["at"])):
        syaw = (base + (i - 1) * spin) % 360.0
        sy = min(hh_at(Hh, px, pz)
                 for px, pz in rect_points(sx, sz, sw, sd, syaw,
                                           n=3)) - st["sink"]
        rcx, rcz, _rw, _rd, _ax, _off = recipe_box(st["rec"])
        sc = math.cos(math.radians(syaw))
        ss = math.sin(math.radians(syaw))
        sox = sx - (rcx*sc + rcz*ss)
        soz = sz - (-rcx*ss + rcz*sc)
        house(st["rec"], sox, sy, soz, syaw, f"прилавок {i+1}")
        # ТОВАР ЖИВЁТ В ПЯТНЕ ПРИЛАВКА: бочки «у ноги» стояли за габаритом, на
        # полметра в проход (замер до осевой главной улицы: 0.20 м).
        for lx, lz, dy in gd["at"]:
            gx, gz = loc_to_world(sox, soz, syaw, lx, lz)
            house(gd["rec"], gx, sy + dy, gz, (syaw + i*gd["spin"]) % 360.0,
                  f"товар прилавка {i+1}")
        bx2, bz2 = loc_to_world(sox, soz, syaw, bk["at"][0], bk["at"][1])
        house(bk["rec"], bx2, sy, bz2, (syaw + bk["yaw"]) % 360.0,
              f"стеллаж прилавка {i+1}")

def place_life(pl, Hh, core):
    """ФАЗА 4 — ЖИЗНЬ ПЛОЩАДИ: скамьи и фонари вокруг ядра, тара у лотков,
    набор по карте свободы. ЯДРО надо не «украсить», а СДЕЛАТЬ ЦЕНТРОМ
    ВНИМАНИЯ: вокруг него садятся скамьи лицом к нему и фонари, то есть
    появляется причина к нему подойти. Лотки при этом остаются кромкой."""
    if pl["kind"] != "market" or core is None:
        return 0
    co = pl["core"]
    wcx, wcz = core[0] + co["body"][0], core[1] + co["body"][1]
    n = 0
    for sp in pl.get("around", ()):
        n += sweep(wcx, wcz, sp["n"], sp["r"],
                   lambda px, pz, a, i, _s=sp: put_item(
                       Hh, _s["what"], px, pz, _s, i=i,
                       yaw=math.degrees(-a) % 360.0, on_square=True),
                   step_deg=sp["step"], start_deg=sp.get("start", 0.0))
    cl = pl.get("clutter")
    if cl:
        for i, (sx, sz) in enumerate(plan_ref(pl["stalls"]["at"])):
            put_here = 0
            for k, (dx, dz) in enumerate(cl["at"]):
                if put_here >= cl["max"]:
                    break
                px, pz = sx + dx, sz + dz
                if not decor_free(px, pz, cl["clear"], on_square=True):
                    continue
                rec = cl["recs"][1] if (i + k) % 3 else cl["recs"][0]
                byaw = (i*63 + k*29) % 360
                ox, oz = body_origin(rec, px, pz, byaw)
                house(rec, ox, sit_at(Hh, px, pz, cl["size"], cl["size"], byaw),
                      oz, byaw, f"{cl['note']} {i+1}")
                hold(px, pz, cl["clear"])
                n += 1
                put_here += 1
    x0, z0, w, d = plan_ref(pl["rect"])
    cells = []
    for zi in range(int(z0), int(z0 + d) + 1):
        for xi in range(int(x0), int(x0 + w) + 1):
            px, pz = xi + 0.5, zi + 0.5
            r = free_radius(px, pz)
            if r > 0.45:
                cells.append((r, px, pz))
    cells.sort(reverse=True)
    n_h = 0
    for sp in pl.get("fill", ()):
        got = 0
        for r, px, pz in list(cells):
            if got >= sp["n"]:
                break
            if r <= sp["r"]:
                continue
            got += put_item(Hh, sp["what"], px, pz, dict(sp, clear=0.5),
                            i=(int(px + pz) if sp["what"] == "bush" else got),
                            on_square=True)
        if sp["what"] == "bush":
            n_h = got
        else:
            n += got
    print(f"{pl['name']}: {n} предметов оживления (скамьи, фонари, тара, "
          f"огонь), {n_h} кустов; плита снята — площадь мостится полотном земли")
    return n + n_h

def place_tree(pl, Hh):
    """ФАЗА 5 — ЯДРО-ДЕРЕВО. Стоит отдельной фазой от ядра-колодца, потому что
    зовётся в другом месте конвейера: дерево садится после моста и до дворов,
    а колодец — сразу за полотном площади."""
    if pl["kind"] != "grove":
        return
    co = pl["core"]
    gx, gz = place_at(pl)
    gy = sit(gx, gz, co["fallback"], half=co["sit_half"])
    place(co["object"], gx, gy, gz, 0, co["note"])
    rim = co["rim"]
    house(rim["rec"], gx - rim["off"], gy, gz - rim["off"], 0, rim["note"])
    nm, lw, ld, rnd = co["landmark"]
    LANDMARKS.append((nm, gx, gz, lw, ld, 0.0, rnd))

def place_decor(pl, Hh, FR):
    """ФАЗА 6 — УБРАНСТВО. Идёт ПОСЛЕ дворов, и это обязательно: у сквера и
    парадного двора места мало (замер: до дома 0.38 м), а поленница соседа,
    поставленная ПОЗЖЕ, не была бы видна проверке. Кто раньше, тот и занимает;
    убранству точки притяжения место нужнее, чем ещё одной бочке."""
    if pl["kind"] == "grove":
        return decor_grove(pl, Hh)
    if pl["kind"] == "forecourt":
        return decor_forecourt(pl, Hh, FR)
    return 0

def decor_grove(pl, Hh):
    gx, gz = place_at(pl)
    fl, co = pl["floor"], pl["core"]
    r_mid, R = pave_ring(gx, gz, fl["bare_r"], fl["half"], fl["slack"],
                         fl["note"])
    # СКВЕР ЗАЯВЛЯЕТ СЕБЯ КОЛЬЦОМ, А НЕ ДИСКОМ, и это не поблажка приёмке.
    # Диск с дырой, объявленный диском, дал бы «износ < 1.0 у 21%» — и прибор
    # был бы прав ровно наоборот: он мерил бы сплошность там, где сплошности
    # быть НЕ ДОЛЖНО.
    SQUARES.append((fl["square"], "disk",
                    (gx, gz, R, r_mid - (fl["half"] - FADE_M)), 0))
    # ...И ВСТРЕЧНАЯ МЕРА: у сплошности всегда есть парная ей пустота, и без
    # второго числа первое можно выполнить, замостив всё (что и было). Круг у
    # ствола заявляется ГОЛЫМ, и его меряет тот же прибор тем же полем.
    BARE_SPOTS.append((fl["bare"], gx, gz, fl["bare_r"]))
    n_b, gap_k = bench_ring(Hh, gx, gz, pl["bench_ring"])
    got = {}
    for sp in pl["sweeps"]:
        if sp["what"] == "planter":
            fn = lambda px, pz, a, i, _s=sp: put_planter(
                Hh, px, pz, a, i, _s["note"], _s["flowers"])
        else:
            fn = lambda px, pz, a, i, _s=sp: put_item(Hh, _s["what"], px, pz,
                                                      _s, i=i)
        got[sp["what"]] = sweep(gx, gz, sp["n"], sp["r"], fn,
                                step_deg=sp["step"], start_deg=sp["start"])
    n_p = got.get("planter", 0)
    n_l = got.get("lamp", 0)
    n_h = got.get("bush", 0)
    print(f"{pl['name']}: {n_b} сегментов кольцевой скамьи из "
          f"{pl['bench_ring']['n']} (разрывы {sorted(gap_k)} — две улицы и "
          f"фасад), {n_p} цветников ({n_p*4} цветов), {n_l} фонарей, "
          f"{n_h} кустов; мостовая кольцом "
          f"{fl['bare_r'] + FADE_M:.1f}..{R:.1f} м вокруг приствольного круга "
          f"земли r={fl['bare_r']:.1f} м (окантовка city-treering 2.775), "
          f"дерево и кольцо не тронуты (запрет r={co['keep_r']:.1f})")
    return n_b + n_l + n_h

def decor_forecourt(pl, Hh, FR):
    """Двор перед зданием: пол партером, набор по карте свободы двора."""
    rec = KIND[pl["of"]]
    keep = next((f for f in FR if f["rec"] == rec), None)
    if keep is None:
        print(f"{pl['name']}: здания «{pl['of']}» в раскладке нет — пропущено")
        return 0
    fx, fz = keep["door"]
    ux, uz = fx - keep["x"], fz - keep["z"]
    ul = math.hypot(ux, uz) or 1.0
    ux, uz = ux/ul, uz/ul                 # наружу от двери
    tx, tz = -uz, ux                      # вдоль фасада
    yaw_face = math.degrees(math.atan2(ux, uz)) % 360.0
    out0 = pl["out0"]
    pave_apron(fx, fz, ux, uz, tx, tz, dict(pl["floor"], out0=out0))
    n = 0
    cells = []
    ce = pl["cells"]
    for oi in range(int(out0), int(out0) + ce["out"]):
        for li in range(-ce["side"], ce["side"] + 1):
            px, pz = fx + ux*oi + tx*li, fz + uz*oi + tz*li
            r = free_radius(px, pz)
            if r > 0.45:
                cells.append((r, oi, li, px, pz))
    # ПОРЯДОК ОБХОДА КЛЕТОК — ЧАСТЬ РЕЦЕПТА МЕСТА, а не деталь реализации:
    # им и различаются «у входа», «по кромке», «на смотровой», «по углам».
    # Ключ «side» СОРТИРУЕТ ТОЛЬКО ПО ОТСТУПУ ОТ ОСИ и тем отличается от
    # «far-side»: сортировка устойчива, значит при равном отступе клетки
    # остаются в порядке обхода карты, а не переставляются по свободе. Разница
    # видна на кустах двора — три из шести встают в другие клетки.
    ORDER = {"near-face": lambda c: (c[1], -c[0]),
             "far-side":  lambda c: (-abs(c[2]), -c[0]),
             "side":      lambda c: -abs(c[2]),
             "far-face":  lambda c: (-c[1], -c[0]),
             "far-corner": lambda c: (-(c[1] + abs(c[2])), -c[0])}
    n_own = 0
    for sp in pl["fill"]:
        pool = [c for c in cells if c[0] > sp["r"]
                and abs(c[2]) >= sp.get("side_min", 0)]
        pool.sort(key=ORDER[sp["by"]])
        if "take" in sp:
            pool = pool[:sp["take"]]
        cnt = n_own if sp.get("own") else n
        for _r, _o, li, px, pz in pool:
            if cnt >= sp["n"]:
                break
            face = sp.get("face")
            yaw = None
            if face == "axis":
                yaw = (yaw_face + (90 if li < 0 else 270)) % 360.0
            elif face == "out":
                yaw = (yaw_face + 90.0) % 360.0
            cnt += put_item(Hh, sp["what"], px, pz, sp,
                            i=int(px + pz), yaw=yaw)
        if sp.get("own"):
            n_own = cnt
        else:
            n = cnt
    n += n_own
    print(f"{pl['name']}: {n} предметов (жаровни, скамьи, фонари, кусты); "
          f"ось доведена полотном до двери ({fx:.1f},{fz:.1f})")
    return n

def place_terrace(pl, Hh):
    """ФАЗА 7 — ПОСТРОЕННЫЙ ПЕРЕПАД на нагорной кромке площади."""
    if not pl.get("terrace"):
        return 0, 0
    return market_terrace(Hh, plan_ref(pl["rect"]))

def place_halo(pl):
    """ОРЕОЛ ВЫТОПТАННОГО у ядра места — для покраски земли классами."""
    h = pl.get("halo")
    if h is None:
        return None
    if isinstance(h, dict):
        px, pz = plan_ref(h["at"])
        return (px + h["d"][0], pz + h["d"][1], h["r"])
    cx, cz = place_at(pl)
    return (cx, cz, h)

# --- ОЗЕЛЕНЕНИЕ ГОРОДА (п. 5: «мало кустиков по городу») ---------------------
# Кусты СУЩЕСТВУЮЩИЕ (полка glade, табу владельца на правку) и ставятся ТАМ,
# ГДЕ ИХ САЖАЮТ, а не где осталось место: вдоль глухих стен домов, у ворот, по
# кромкам точек притяжения. «Умеренно, по-скайримски» переведено в число:
# не больше двух кустов на дом и не ближе 1.2 м к дверной грани — куст у самой
# двери читается как заброшенность, а не как озеленение.
def greenery(Hh):
    n = 0
    for i, (rec, ox, oy, oz, yaw, w, d, name) in enumerate(FRAMES):
        lcx, lcz, _w, _d, axis, _o = recipe_box(rec)
        # боковая грань (не дверная и не задняя-дворовая): вдоль фасада
        side = {"+Z": (1.0, 0.0), "-Z": (-1.0, 0.0),
                "+X": (0.0, 1.0), "-X": (0.0, -1.0)}[axis]
        for k in (0, 1):
            t = (0.30 + 0.45*k)
            lx = lcx + side[0]*(w/2 + 0.85) + (-side[1])*(d*(t - 0.5))
            lz = lcz + side[1]*(d/2 + 0.85) + (side[0])*(w*(t - 0.5))
            bx, bz = loc_to_world(ox, oz, yaw, lx, lz)
            n += put_bush(Hh, bx, bz, i + k, "озеленение у стены: " + name)
    for gt in PLAN["gates"]:
        gx, gz = gt["pos"]
        for k in range(4):
            a = 2*math.pi*k/4 + 0.7
            n += put_bush(Hh, gx + math.cos(a)*7.5, gz + math.sin(a)*7.5,
                          k, "куст у ворот " + gt["name"])
    print(f"озеленение: {n} кустов (у стен, у ворот) — ассеты полки glade, "
          f"ни один не правлен")
    return n

# --- РАЗНООБРАЗИЕ СВЕТА: ФОНАРИ УЛИЦ И ОГОНЬ У ДВЕРЕЙ ------------------------
# Разнообразие тут не в цвете, а в ТИПАХ ИСТОЧНИКА (таблица LIGHT паспорта):
# жаровня — резкий большой оранжевый, фонарь-столб — мягкий средний тёплый,
# огонь у двери — мягкий малый тусклый. Ставятся они по РАЗНЫМ ПРАВИЛАМ, и
# это важнее чисел: жаровни в узлах решений, фонари РИТМОМ вдоль улицы (шаг
# LAMP_PITCH паспорта — чуть больше двойного радиуса, чтобы между ними
# оставалась темнота: гирлянда без темноты не читается как огонь), огонь у
# двери — у каждой двери, к которой ведёт дорожка.

def street_lamps(Hh):
    n = 0
    # ГЛАВНАЯ, ТРАКТ РЫНКА, ВОСТОЧНЫЙ — большим столбом; УЛИЦА ВЕТРОВ (гравий,
    # 4 м) — малым: столб 0.84 м поперёк четырёхметровой улицы съедает пятую
    # часть проезда. Без этой строки furn-lamp-post-s не ставился НИ РАЗУ
    # (нашлось check_unplaced: рецепт есть, места ему в раскладке нет).
    for ri in LAMP_ROADS:
        if ri >= len(PLAN["roads"]):
            continue
        rd = PLAN["roads"][ri]
        if rd["mat"] not in ("stone", "gravel"):
            continue
        poly = path_polyline(rd["pts"], 0.5)
        acc = [0.0]
        for a, b in zip(poly, poly[1:]):
            acc.append(acc[-1] + math.hypot(b[0]-a[0], b[1]-a[1]))
        s, side = LAMP_PITCH*0.5, 1.0
        while s < acc[-1] - 4.0:
            p0 = _arc_at(poly, acc, s)
            p1 = _arc_at(poly, acc, min(s + 1.0, acc[-1]))
            tx, tz = p1[0]-p0[0], p1[1]-p0[1]
            tl = math.hypot(tx, tz) or 1.0
            nx, nz = -tz/tl*side, tx/tl*side
            for step in (rd["w"]/2 + 0.9, rd["w"]/2 + 1.7, rd["w"]/2 + 2.6):
                px, pz = p0[0] + nx*step, p0[1] + nz*step
                if put_lamp_post(Hh, px, pz, "фонарь улицы",
                                 small=(rd["w"] < 5.0)):
                    n += 1
                    break
            s += LAMP_PITCH
            side = -side                  # в шахматном порядке, как в жизни
    print(f"фонари улиц: {n} столбов (шаг {LAMP_PITCH:.0f} м, в шахматном "
          f"порядке по обеим кромкам)")
    return n

def door_lights(Hh, FR):
    """ФОНАРЬ У ДВЕРИ — НАСТЕННЫЙ (furn-lamp-wall кузни-3), а не столб рядом.
    Спинка садится РОВНО на дверную грань дома, потому что у рецепта плоскость
    крепления — локальный z=0; фонарь, отодвинутый «для надёжности» на
    полметра, читался бы как столбик без столба.
    Ставится СБОКУ ОТ СТВОРА (1.1 м вдоль фасада): над самой дверью он бьёт в
    глаза выходящему и загораживает косяк."""
    n = 0
    for f in FR:
        fx, fz = f["door"]
        ux, uz = fx - f["x"], fz - f["z"]
        ul = math.hypot(ux, uz) or 1.0
        ux, uz = ux/ul, uz/ul                  # наружу из двери
        tx, tz = -uz, ux                       # вдоль фасада
        placed = False
        for sgn in (1.0, -1.0):
            px, pz = fx + tx*sgn*1.15, fz + tz*sgn*1.15
            # ВАЖНО: сама грань занята стеной, поэтому spot_free тут ответил бы
            # «нет» всегда — фонарь ДОЛЖЕН стоять в теле дома. Проверяем только
            # то, что он не влез в чужое: дорогу и чужие огни этой волны.
            if dist_to_roads(px, pz) < 0.2:
                continue
            if any(math.hypot(px-ax, pz-az) < 1.0 for ax, az, _r in DECOR):
                continue
            put_wall_lamp(Hh, px, pz, ux, uz,
                          "фонарь у двери: " + (f["hs"]["name"] or f["hs"]["kind"] or "дом"))
            hold(px, pz, 0.5)
            n += 1
            placed = True
            break
        if not placed:
            continue
    print(f"фонари у дверей: {n} настенных из {len(FR)} построек")
    return n

# --- МОЩЕНИЕ (плиты wr-forge, семейство city-cobble) -------------------------
# «Композиция земли» ведёт игрока увереннее всего (гайд §10: мощение 55%
# против 40% у цвета), поэтому камнем идёт процессионная ось: южные ворота ->
# рынок -> замок, рынок -> восточные ворота, выход с моста. Плиты ЖЁСТКИЕ —
# рельеф они не повторяют, поэтому длина куска выбирается по РОВНОСТИ пятна:
# на плато ложится 24 м, на переломе 6. Кромка у city-cobble — наклонный
# поясок 0.30 м под 15 гр. (замер wr-forge: скачок 3 см против 22 см отвеса у
# прежних city-plaza), так что улицу можно переходить поперёк где угодно.
# ШТУЧНЫХ ПЛИТ НА УЛИЦАХ БОЛЬШЕ НЕТ (приказ владельца 22.08: «тропинки опять
# плитами кладутся, а не тропинкой каменной»). Каменный тракт стал СВОЙСТВОМ
# ЗЕМЛИ — класс полотна в строке path файла .relief, движок fde9a7b. Вместе с
# лентами ушла и вся машинерия их набора: выбор длины по ровности пятна,
# наклонные куски -sNN, цепь отметок, отступ на изломе. Она была верной для
# своей задачи и решила её (подъём к замку 23.4 -> 91.0%), но задачи этой
# больше нет: у полотна земли нет ни стыков, ни ступеней, ни «губы» над
# грунтом, и разрывов у него не бывает по построению. Держать её мёртвой
# значило бы врать о том, как построен город.
# ПЛИТАМИ ОСТАЛИСЬ ТРИ ВЕЩИ, и каждая — не тропа: мост (авторский настил),
# марш и подпорная кромка террасы (построенный перепад) и мостовая рынка
# (площадь — место, а не путь; по ней ходят во все стороны).
PAVE_TOP = 0.087    # верх мостовой city-cobble над её origin (у НИЖНЕЙ кромки)

PAVED = []
PAVE_OVERLAP = 1.0  # м2: больше — считается наложением плиты на плиту
PAVE_SLIVER = 0.05  # м2: меньше — численный волосок на изломе, не наложение
PAVE_FLICKER = 0.01 # м: ближе по высоте — соплоскостная пара, она мерцает
PAVE_MAX_DROP = 0.35  # круче — мостовую не кладём вовсе, это дело лестниц
PAVE_STEP = 0.20      # предельная ступень между СОСЕДНИМИ плитами одной улицы

def slab_top(p, px, pz, clamp=False):
    """Ходибельная отметка плиты в мировой точке: наклонный кусок ЕДЕТ.
    clamp=True прижимает точку к СВОЕМУ пятну: поверхность существует только
    над пятном, а за его краем честное значение — отметка ближней кромки.
    Без этого короткий крутой кусок, продлённый до середины между центрами,
    привирает на весь свой уклон: марш 2.1 м рядом с восьмиметровой плитой
    насчитывал ступень 0.85 м там, где кромки сходятся с точностью 3 см."""
    c = math.cos(math.radians(p[4]))
    sn = math.sin(math.radians(p[4]))
    lx = (px - p[0]) * c - (pz - p[1]) * sn
    if clamp:
        lx = max(-p[2]/2, min(p[2]/2, lx))
    return p[5] + p[6] * lx
def slab_covers(p, px, pz):
    c = math.cos(math.radians(p[4]))
    sn = math.sin(math.radians(p[4]))
    lx = (px - p[0]) * c - (pz - p[1]) * sn
    lz = (px - p[0]) * sn + (pz - p[1]) * c
    return abs(lx) <= p[2] / 2 and abs(lz) <= p[3] / 2

def rect_poly(cx, cz, w, d, yaw_deg):
    c = math.cos(math.radians(yaw_deg))
    sn = math.sin(math.radians(yaw_deg))
    return [(cx + lx*c + lz*sn, cz - lx*sn + lz*c)
            for lx, lz in ((-w/2, -d/2), (w/2, -d/2), (w/2, d/2), (-w/2, d/2))]

def poly_clip_area(subject, clip):
    """Площадь пересечения двух ВЫПУКЛЫХ многоугольников (Сазерленд-Ходжман).
    Нужна честная площадь, а не «касаются ли»: на изломе улицы соседние плиты
    задевают друг друга углом на десятки сантиметров — это нормальный шов, а
    вот 16 м2 в одной плоскости мерцают, и 15 м2 со ступенькой 0.40 м дают
    ровно ту кромку, ради которой у city-cobble делалась фаска (замер
    wr-forge: девять пар наложений в первой раскладке)."""
    out = subject
    n = len(clip)
    for i in range(n):
        ax, az = clip[i]
        bx, bz = clip[(i + 1) % n]
        ex, ez = bx-ax, bz-az
        def inside(p):
            return ex*(p[1]-az) - ez*(p[0]-ax) >= 0.0
        src, out = out, []
        if not src:
            return 0.0
        prev = src[-1]
        for cur in src:
            if inside(cur):
                if not inside(prev):
                    out.append(seg_cross(prev, cur, (ax, az), (ex, ez)))
                out.append(cur)
            elif inside(prev):
                out.append(seg_cross(prev, cur, (ax, az), (ex, ez)))
            prev = cur
    if len(out) < 3:
        return 0.0
    a = 0.0
    for i in range(len(out)):
        x0, z0 = out[i]
        x1, z1 = out[(i + 1) % len(out)]
        a += x0*z1 - x1*z0
    return abs(a) / 2.0

def seg_cross(p, q, a, e):
    dx, dz = q[0]-p[0], q[1]-p[1]
    den = e[0]*dz - e[1]*dx
    if abs(den) < 1e-12:
        return q
    t = (e[0]*(p[1]-a[1]) - e[1]*(p[0]-a[0])) / -den
    return (p[0] + dx*t, p[1] + dz*t)
def check_paving():
    """Раскладка обязана сама говорить, что положила плиту на плиту: пара
    в одной плоскости мерцает, пара со ступенькой даёт кромку посреди улицы."""
    import itertools
    bad = []
    joints = 0
    for a, b in itertools.combinations(PAVED, 2):
        ar = poly_clip_area(rect_poly(*a[:5]), rect_poly(*b[:5]))
        # СТУПЕНЬ МЕРЯЕТСЯ В ТОЧКЕ СТЫКА, А НЕ ПО ЦЕНТРАМ. У наклонных соседок
        # центры разнесены по высоте на весь уклон куска, а игрок переступает
        # там, где кромки сходятся: разность центров назвала бы дефектом
        # именно ту пару, которая сошлась по построению.
        mx, mz = (a[0] + b[0])/2, (a[1] + b[1])/2
        dy = abs(slab_top(a, mx, mz, clamp=True)
                 - slab_top(b, mx, mz, clamp=True))
        if ar > PAVE_SLIVER and dy < PAVE_FLICKER:
            bad.append(f"СОПЛОСКОСТНАЯ пара (мерцает): {ar:.2f} м2, "
                       f"разность верха {dy:.4f} м в ({a[0]:.0f},{a[1]:.0f})")
            continue
        if ar > PAVE_OVERLAP:
            bad.append(f"плита на плите: {ar:.1f} м2, ступень {dy:.2f} м "
                       f"в ({a[0]:.0f},{a[1]:.0f})")
            continue
        # СТЫК: кромки ближе 0.6 м. Дальше — землю между плитами мостит
        # рельеф, и разность отметок там ничего не значит (пара с ступенью
        # 3.5 м — это терраса, а не дефект).
        D = math.hypot(a[0]-b[0], a[1]-b[1]) or 1e-6
        ux, uz = (b[0]-a[0])/D, (b[1]-a[1])/D
        gap = D - half_proj(a[2], a[3], a[4], ux, uz) - half_proj(b[2], b[3], b[4], ux, uz)
        if gap < 0.6:
            joints += 1
            if dy > PAVE_STEP + 0.02:
                bad.append(f"стык с обрывом: зазор {gap:.2f} м, ступень {dy:.2f} м "
                           f"в ({a[0]:.0f},{a[1]:.0f})")
    print(f"мощение: {len(PAVED)} плит, {joints} стыков (кромки ближе 0.6 м)")
    if bad:
        print("ПРОВЕРКА МОЩЕНИЯ:")
        for b in sorted(set(bad)):
            print("  -", b)

# --- ТЕРРАСА РЫНКА: ПОСТРОЕННЫЙ ПЕРЕПАД (марш + подпорная кромка) -----------
# СЕВЕРНАЯ грань прямоугольника рынка — нагорная: z убывает НА СЕВЕР (контракт
# Scene.h: «spawn_yaw 0 looks north, forward = {sin,0,-cos}»; спавн z=248 юг,
# замок z=60 север), прямоугольник идёт z 146..157, значит 146 — северная,
# верхняя сторона. Мы с архитектором оба сначала звали её южной; имя врало, а
# композиция была права — рынок ВРЕЗАН в склон, поднимающийся к замку, и марш
# на процессионной оси идёт ВВЕРХ, к цитадели (гайд §11).
# Перепад на этой грани — не постоянный, а КЛИН: замер по итоговой земле даёт
# 1.30 м у x=110 и ноль у x≈122, ровно по уклону улицы. Поэтому:
#   * марш ставится в РОВНЫЙ КАРМАН, а не на клин. Жёсткий блок на переменной
#     отметке болеет тем же, чем болела плита на склоне: шестиметровое пятно
#     ловит 0.21 м разброса — ровно порог ступени. Карман режется в поле высот;
#   * кромка собирается ОТРЕЗКАМИ по 2 м ступенями высот, а не плавным скосом:
#     копинг настоящей кладки ступает рядами, непрерывный скос читается
#     выдавленной геометрией (гайд §10, «силуэт бьёт всё»);
#   * восточный конец не строится вовсе: подпорка кончается там, где кончается
#     то, что она держит. Там выход тракта Восточных ворот — это вход на
#     площадь, а не дыра в ограждении.
# ЛИЦО СТЕНКИ СМОТРИТ НА ЮГ, в площадь, хотя стоит она на СЕВЕРНОЙ кромке:
# положение и разворот — разные вопросы, и стенку, развёрнутую лицом в грунт,
# ни связность, ни ступень не поймают.
KERB_REC = "city-kerb2-h%02d.dfh"
STEP_REC = "city-steps6-h%02d.dfh"
KERB_MIN = 0.25     # ниже — подпорной стенки в природе не бывает, это выкат
KERB_COPING = 0.053  # напуск копинга над ростовкой (замер wr-forge)

# ХОДИБЕЛЬНАЯ ПОВЕРХНОСТЬ МАРША НЕ СОВПАДАЕТ С ЕГО ЯКОРЯМИ: у подошвы она
# выше origin, у верхней кромки — выше верхнего якоря, и на РАЗНУЮ величину.
# Числа — замер прибором кузницы по .dfh (её письмо), а не паспорт: посадка
# цепью по одному лишь «подъём 1.200» оставила бы на стыке 0.025 м. Вывести их
# из толщины и угла нельзя — у h12 и h08 угол один, а поправки разные.
# Рецепт без замера НЕ САЖАЕТСЯ: угадывать полсантиметра под ногой нечем.
STEP_FIT = {"city-steps6-h12.dfh": (0.176, 0.151),
            "city-steps6-h08.dfh": (0.165, 0.140),
            "city-steps6-h12r2.dfh": (0.176, 0.151),
            # h14r2 НЕ наследует поправки соседа: у него восемь подступенков по
            # 0.175, у h12r2 семь по 0.1714, и с дроблением меняется рельеф
            # ступеней. Разница 4 мм на конец — ровно та ошибка на ровном
            # месте, ради которой рецепт без замера и не сажается.
            "city-steps6-h14r2.dfh": (0.180, 0.155)}

def _kit(pattern):
    """Ростовки читаются из assets/houses, а не выписываются: кузница печёт их
    волнами, и любое записанное сюда число — будущая ложь. Варианты ОДНОГО
    роста («r2» — тот же подъём другим вылетом) подхватываются наравне:
    иначе новый рецепт не просто не используется, он НЕВИДИМ, и отказ «нет
    замера поверхности» даже не печатается — а молчание тут неотличимо от
    исправности. Отдаём списком, а не словарём по росту: у h12 и h12r2 рост
    общий, и словарь молча оставил бы один из двух.
    Возвращает [(подъём, вылет, файл)]."""
    rx = re.compile(pattern.replace(".", r"\.").replace("%02d", r"\d\d[a-z]?\d?") + r"$")
    out = []
    for f in sorted(os.listdir(os.path.join(ROOT, "assets/houses"))):
        if not rx.match(f):
            continue
        row = shelf(f)
        if row is not None:
            # подъём — верх габарита графа, вылет — его длина вдоль +X
            out.append((_sh(row, "gy1"),
                        _sh(row, "gx1") - _sh(row, "gx0"), f))
            continue
        xs, ys = [], []
        for line in open(os.path.join(ROOT, "assets/houses", f), encoding="utf-8"):
            t = line.split()
            if t and t[0] == "vertex":
                xs.append(float(t[3]))
                ys.append(float(t[4]))
        out.append((max(ys), max(xs) - min(xs), f))
    return out

def market_terrace(Hh, rect, plate_top=None):
    """Строит перепад НАГОРНОЙ кромки площади. Возвращает (маршей, отрезков).
    plate_top=None — «мерить землю площади самому». Так теперь и зовут: плиты
    под маршем больше нет (площадь мостится полотном), а МАКСИМУМ пятна, на
    который садилась плита, стоит на 3-9 см выше земли в створе оси, и подошва
    целилась мимо — ступень на стыке выросла 0.056 -> 0.196 при пороге 0.20.
    Отметка берётся ТАМ, ГДЕ СТОИТ ПОДОШВА."""
    steps, kerbs = _kit(STEP_REC), dict((h, (f, ln)) for h, ln, f in _kit(KERB_REC))
    if not steps or not kerbs:
        print("терраса рынка: нет выпечки city-steps6/city-kerb2 — пропущено")
        return 0, 0
    mkx, mkz, mkw, _mkd = rect
    edge_z = float(mkz)
    # створ оси: где процессионная ломаная пересекает кромку
    ax = PLAN["roads"][AXIS_ROAD]["pts"]
    x_axis = None
    for (x0, z0), (x1, z1) in zip(ax, ax[1:]):
        if (z0 - edge_z) * (z1 - edge_z) <= 0 and z0 != z1:
            x_axis = x0 + (x1 - x0) * ((edge_z - z0) / (z1 - z0))
            break
    if x_axis is None:
        return 0, 0
    if plate_top is None:
        plate_top = hh_at(Hh, x_axis, edge_z + 1.5)

    def street(x):
        """Ходибельная отметка улицы против точки x кромки. Улица — ПОЛОТНО
        ЗЕМЛИ, а не лента плит: по ней ходят по самому грунту, и никаких
        «вкоп 0.03 плюс верх камня» к отметке добавлять не надо. Пока эта
        добавка тут стояла, марш целился на 0.117 выше улицы, и с его верхней
        ступени игрок сходил на землю, лежащую на 0.175 ниже."""
        return hh_at(Hh, x, edge_z - 2.0)

    rise = street(x_axis) - plate_top
    # ВЫБОР РОСТОВКИ — ПО ХОДИБЕЛЬНОМУ ПОДЪЁМУ, а не по якорному: игрок идёт
    # по камню, и у марша h12 камень поднимается на 1.200+0.151-0.176 = 1.175.
    usable = []
    for h, run, rec in steps:
        if rec not in STEP_FIT:
            print(f"  {rec}: нет замера поверхности — НЕ САЖАЮ (посадка цепью "
                  f"требует поправок у подошвы и у верха, вывести их из угла "
                  f"нельзя: у h12 и h08 угол один, а поправки разные)")
            continue
        t_foot, t_top = STEP_FIT[rec]
        usable.append((h + t_top - t_foot, run, rec, t_foot, h))
    if not usable:
        return 0, 0
    # при равной пригодности предпочитается ЦЕЛЫЙ вылет: сетка высот идёт
    # шагом 1 м, и кромка, попавшая между строк, стоит доли строки на уклон
    usable.sort(key=lambda u: (abs(u[0] - rise), abs(u[1] - round(u[1]))))
    walk_rise, run, rec_s, t_foot, h_anchor = usable[0]
    # ОСТАТОК ДЕЛИТСЯ ПОПОЛАМ. Марш ростом ровно в перепад не испечён и не
    # будет: перепад — свойство горы, а ростовки дискретны. Половина остатка
    # достаётся низу, половина верху, и обе заведомо мельче порога ступени.
    # ВЕРХ МАРША ЦЕЛИТСЯ В УЛИЦУ ТОЧНО, ОСТАТОК ДОСТАЁТСЯ ПОДОШВЕ. Прежде
    # остаток делился пополам, и наверху оставалась ступенька — а это как раз
    # тот конец, где игрок СХОДИТ с лестницы на ходу и спотыкается. Внизу
    # лишний сантиметр читается просто первой ступенью: лестница и есть
    # ступени. Поэтому верх сажается вровень с полотном улицы, а разница
    # ростовки и перепада уходит в стык с плитой рынка.
    oy = street(x_axis) - STEP_FIT[rec_s][1] - h_anchor
    # ПОДОШВА ВСТЫК К ПЛИТЕ, А НЕ ПОВЕРХ НЕЁ. При oz = edge_z + 0.5 нижняя
    # ступень ложилась на мостовую рынка тремя квадратами внахлёст — стык двух
    # тел в одной плоскости, ровно то, что мы браковали у плит.
    ox, oz = x_axis - 3.0, edge_z      # +X на север, +Z на восток (yaw 90)
    # РОВНЫЙ КАРМАН под маршем: режется в поле высот НА УЛИЧНОЙ стороне, до
    # самой кромки. Дальше кромки — площадь, и там последнее слово за рынком.
    # карман: от верхней кромки марша (с запасом 0.4) до самой грани рынка —
    # дальше грани площадь, и там последнее слово за рынком
    # КАРМАН РЕЖЕТСЯ ПО СОБСТВЕННОМУ УКЛОНУ МАРША, А НЕ ПЛОСКИМ.
    # Архитектор просил ровную нишу, и причина у него верная: жёсткий блок на
    # переменной отметке одним краем врежется, другим повиснет. Но ПЛОСКАЯ ниша
    # лечит это ценой двух новых болезней — под верхними ступенями остаётся
    # пустота в метр с лишним, а за верхней кромкой (там, где кайма) земля
    # ложится на НИЖНЮЮ отметку и даёт канаву поперёк улицы. Ниша по уклону
    # марша даёт то же лекарство без обеих: подошва рецепта — плоскость от
    # (0,0) до (вылет, ростовка), и земля режется ровно этой плоскостью.
    # Приёмка соответственно меняется: не «четыре угла в пределах 5 см друг от
    # друга», а «четыре угла в пределах 5 см от ПОДОШВЫ МАРША» — то же
    # требование, посчитанное от той плоскости, на которую марш и садится.
    # Узлы стоят РОВНО на концах марша, без запаса: grade_corridor прижимает
    # проекцию к отрезку, поэтому за концами отметка выходит на полку — снизу
    # на уровень подошвы (это плита рынка, разница 2 см), сверху на уровень
    # верхней ступени (это улица). Запас же в полметра растягивал ту же
    # разность на 3.1 м вместо 2.1 и задирал углы подошвы на 0.17 м.
    # ...и ТРЕТИЙ УЗЕЛ ЗА ВЕРХНЕЙ КРОМКОЙ. Ниша идёт по ПОДОШВЕ марша, а
    # ходибельная поверхность лежит на t_top выше верхнего якоря — значит
    # земля, продолженная за кромку по подошве, оказывается на t_top ниже
    # последней ступени, и игрок сходит с марша в ямку. За кромкой земля
    # поднимается к отметке улицы на коротком выносе.
    # ...и ВЕРХНИЙ УЗЕЛ НИШИ СТОИТ НА ХОДИБЕЛЬНОЙ ОТМЕТКЕ, А НЕ НА ПОДОШВЕ.
    # Ниша, доведённая по подошве до самой кромки, оставляла землю на t_top
    # ниже последней ступени — игрок сходил с марша в ямку 0.15 м. У настоящей
    # лестницы верхняя ступень лежит ВРОВЕНЬ с верхней землёй, а низ марша под
    # ней прикопан; так и режем. Заодно за кромкой отметка выходит на полку
    # ровно уличную, и никакой канавы там больше нет.
    top_walk = oy + h_anchor + STEP_FIT[rec_s][1]
    # НИЖНИЙ УЗЕЛ НИШИ СТОИТ НА ЗЕМЛЕ ПЛОЩАДИ, А НЕ НА ПОДОШВЕ МАРША.
    # Пока под маршем лежала плита рынка, игрок сходил с камня на камень, и
    # ниша могла спокойно резать землю до подошвы: её никто не видел. Плиты
    # больше нет — снизу теперь ПОЛОТНО ЗЕМЛИ, и ступень на стыке стала
    # разностью «ходибельный низ марша минус дно ниши» = t_foot + 0.02 =
    # 0.196 м при пороге 0.20 (check_axis это и показал: было 0.056).
    # Земля у подошвы обязана лежать на отметке ПЛОЩАДИ; марш при этом
    # прикапывается на 9-13 см по всей длине, что и правильно — у настоящей
    # лестницы низ утоплен, а верхняя ступень лежит вровень с верхней землёй.
    grade_corridor(Hh,
                   [(ox + 3.0, oz, plate_top - 0.02),
                    (ox + 3.0, oz - run, top_walk - 0.02)],
                   3.4, 0.8)
    house(rec_s, ox, oy, oz, 90.0, "марш террасы рынка")
    # МАРШ — ТОЖЕ ОПОРА, и связность оси обязана его засчитывать: критерий
    # архитектора про то, что игрок идёт из конца в конец по твёрдому, а не про
    # то, что всё твёрдое сделано из булыжника. Ложится в PAVED как наклонный
    # кусок: длина вдоль +X — вылет, поперёк — ширина, уклон — ходибельный
    # подъём на вылет.
    # центр пятна: origin + вылет/2 на север (лок. +X) + 3.0 на восток (лок. +Z)
    PAVED.append((ox + 3.0, oz - run/2.0, run, 6.0, 90.0,
                  oy + t_foot + walk_rise/2.0, walk_rise/run))
    open_lo, open_hi = ox, ox + 6.0

    n_k, kerb_faces = 0, []
    x = float(mkx)
    while x + 2.0 <= mkx + mkw + 0.01:
        xm = x + 1.0
        if x < open_hi and x + 2.0 > open_lo:
            x += 2.0                      # створ марша стенкой не перекрывают
            continue
        top = hh_at(Hh, xm, edge_z - 2.0)
        face = top - hh_at(Hh, xm, edge_z + 1.0)
        if face < KERB_MIN:
            x += 2.0                      # держать нечего — стенки и нет
            continue
        h_k = min(kerbs, key=lambda v: abs(v - face))
        rec_k, ln = kerbs[h_k]
        # РАЗВОРОТ 180, А НЕ 0. У рецепта лицо лежит на локальном z=0, а тело
        # уходит в +Z; при yaw 0 локальный +Z — это мировой +z, ЮГ, и лицо
        # смотрело бы на СЕВЕР, в грунт. Такую стенку не поймает ни связность,
        # ни ступень — она пройдёт обе проверки, стоя задом к площади.
        # При yaw 180 локальный +X — на запад, +Z — на север: тело уходит в
        # гору, лицо с копингом смотрит на юг, в рынок. Origin, стало быть,
        # на ВОСТОЧНОМ конце отрезка и ровно на кромке.
        # Верх копинга = ростовка + напуск, и он садится вровень с улицей.
        house(rec_k, x + ln, top - (h_k + KERB_COPING), edge_z, 180.0,
              "подпорная кромка рынка")
        kerb_faces.append((xm, edge_z, 180.0, h_k))
        n_k += 1
        x += 2.0
    # ЧЕТЫРЕ УГЛА ПЯТНА МАРША — приёмка кармана (архитектор: разброс <= 5 см).
    # Мерить надо ПОЛЕ ЭТОГО ПРОХОДА, а не ground(): ground — это дамп прошлого
    # прохода, кармана в нём ещё нет, и он честно показал бы нетронутый клин
    # 1.32 м, то есть приёмку с обратным знаком. Hh и есть та земля, которая
    # уйдёт в relief.
    # ПРИЁМКА МЕРЯЕТ ТО, ПО ЧЕМУ ХОДЯТ. «Углы подошвы против земли» отвечали
    # на вопрос «не висит ли блок», а спотыкается игрок не о подошву, а о
    # стык КАМНЯ с землёй. Меряем его на обоих концах марша: внизу — против
    # мостовой рынка, наверху — против полотна улицы.
    cs = [hh_at(Hh, px, pz) - w
          for px, pz, w in ((ox, oz - run, top_walk), (ox + 6.0, oz - run, top_walk))]
    foot_step = (oy + t_foot) - plate_top
    check_faces(Hh, kerb_faces)
    print(f"терраса рынка: марш {rec_s} (перепад {rise:.2f} м, ходибельный "
          f"подъём {walk_rise:.3f}, остаток {abs(rise-walk_rise):.3f} — весь "
          f"в подошву), кромка {n_k} отрезков")
    if cs:
        print(f"  стыки марша: низ (камень против мостовой рынка) "
              f"{foot_step:+.3f} м, верх (камень против полотна улицы) "
              f"{min(cs):+.3f}..{max(cs):+.3f} м")
    return 1, n_k

# --- ДЕТЕКТОР «ЛИЦОМ В ГРУНТ» ------------------------------------------------
# Дыра класса «проходит всё» (найдена на подпорной кромке, довод архитектора):
# деталь, поставленную ВЕРНО ПО КООРДИНАТЕ и развёрнутую лицом в гору, не
# ловит НИ ОДИН наш замер. Связность видит пятно — пятно на месте. Ступень
# видит высоты — высоты верны. Наложений нет. Стенка молча стоит задом к
# площади, и это замечают глазами через неделю.
# Причина в том, что замер отвечает на «ГДЕ», а вопрос стоит про «КУДА
# РАЗВЁРНУТО», и это разные вопросы, проверяемые разными способами.
# Разделитель для подпорной стенки дешёвый и однозначный: она держит грунт,
# значит ПЕРЕД лицом земля обязана быть НИЖЕ, чем за спиной. Смотрит в гору —
# перепад меняет знак, и это ловится одной пробой с каждой стороны.
def check_faces(Hh, faces, probe=1.0):
    """faces: [(x, z, yaw, высота)] — точка на ЛИЦЕ и разворот детали.
    Лицо детали при её yaw смотрит в -Z локальной оси, то есть в мир
    (-sin(yaw), -cos(yaw))."""
    bad = 0
    for (fx, fz, fyaw, fh) in faces:
        nx = -math.sin(math.radians(fyaw))
        nz = -math.cos(math.radians(fyaw))
        front = hh_at(Hh, fx + nx*probe, fz + nz*probe)
        back = hh_at(Hh, fx - nx*probe, fz - nz*probe)
        if front >= back - 0.15:
            bad += 1
            print(f"  ЛИЦОМ В ГРУНТ: ({fx:.1f},{fz:.1f}) yaw {fyaw:.0f} — перед "
                  f"лицом {front:.2f}, за спиной {back:.2f}; подпорная стенка "
                  f"обязана держать то, что ВЫШЕ её лица")
    if faces:
        print(f"  развороты лиц: {len(faces)-bad} из {len(faces)} держат склон")
    return bad

FAB_STEP = 0.25     # шаг проб по полотну, м

def check_fabric(paths):
    """ПОЛОТНО МЕРЯЕТСЯ ТРЕМЯ ЧИСЛАМИ, И ДО 24.08 ИХ НЕ МЕРИЛ НИКТО.
    check_paving спрашивает про объекты-плиты, check_axis прямо пишет, что
    покрытие камнем «обеспечено по построению», — то есть у самого полотна
    судьи не было вовсе, и двадцать три кляксы чужого камня уехали в город
    молча. Прибор дешёвый (всё уже в памяти) и меряет ровно то, что видно:

    (1) КЛАССОВАЯ ЧИСТОТА — доля проб на ПЛОСКОЙ ВЕРШИНЕ улицы или внутри
        контура площадки, чей класс отличается от класса самой улицы/площадки.
        Порог 0%. Считается ПРАВИЛОМ ДВИЖКА (последний накрывший мазок,
        радиус half + 0.75), а не намерением генератора.
    (2) СПЛОШНОСТЬ ПЛОЩАДКИ — доля проб внутри контура с износом < 1.0.
        Порог 0%. Это и есть «мощёный круг залит травой» в виде числа.
    (3) КОРОТКИЕ ОСТРОВА — штрихи короче ISLAND_MIN_M, чей класс отличается от
        класса соседнего полотна. Порог: пустой список.
    ГРАНИЦА ПРИБОРА НАЗВАНА ЧЕСТНО: износ здесь аналитический, а движок держит
    его на решётке 1 м и интерполирует. Ноль этого прибора — необходимое
    условие, а не достаточное; ненулю верить можно всегда."""
    fab = Fabric(paths)
    print("ПОЛОТНО (шаг проб %.2f м):" % FAB_STEP)
    # СТЫК ДВУХ ПОВЕРХНОСТЕЙ — НЕ КЛЯКСА, И РАЗДЕЛЯЮТСЯ ОНИ ПО ТОПОЛОГИИ, А НЕ
    # ПО ВЕЛИЧИНЕ (правило 47). Там, где мостовая города встречает загородную
    # стёжку, переходная полоса шириной с радиус класса неизбежна: класс
    # побеждает последний, и слоя приоритетов у движка нет. Но встреча бывает
    # ЗАКОННОЙ — два штриха соединены концом в конец, — и НЕЗАКОННОЙ: чужой
    # штрих лёг поперёк улицы, ни к чему не примыкая. Первое печатается
    # отдельной строкой, второе обязано быть нулём.
    n_all = n_bad = n_seam = 0
    worst = []
    for rd in PLAN["roads"]:
        cls = path_class(rd)
        half = max(0.8, rd["w"] / 2)
        flat = max(0.0, max(half, 1.0) - FADE_M)
        curve = path_polyline(rd["pts"])
        ends = (tuple(rd["pts"][0]), tuple(rd["pts"][-1]))
        bad = seam = tot = 0
        for a, b in zip(curve, curve[1:]):
            L = math.hypot(b[0]-a[0], b[1]-a[1])
            if L < 1e-9:
                continue
            tx, tz = (b[0]-a[0])/L, (b[1]-a[1])/L
            nx, nz = -tz, tx
            s = 0.0
            while s < L:
                for o in (-0.85, -0.45, 0.0, 0.45, 0.85):
                    px = a[0] + tx*s + nx*o*flat
                    pz = a[1] + tz*s + nz*o*flat
                    tot += 1
                    c, _w, who = fab.sample(px, pz)
                    if c == cls:
                        continue
                    if who is not None and any(fab.touches(who, ex, ez)
                                               for ex, ez in ends):
                        seam += 1
                    else:
                        bad += 1
                s += FAB_STEP
        n_all += tot
        n_bad += bad
        n_seam += seam
        if bad:
            worst.append((100.0*bad/max(1, tot), rd["mat"], cls))
    print(f"  (1) класс улиц: КЛЯКС {100.0*n_bad/max(1,n_all):5.2f}% "
          f"({n_bad} из {n_all}), порог 0%; стыков с соседним полотном "
          f"{100.0*n_seam/max(1,n_all):.2f}% (законны)")
    for pct, mat, cls in sorted(worst, reverse=True)[:4]:
        print(f"      тракт {mat} (кл.{cls}): {pct:.1f}% клякс")
    for name, kind, par, cls in SQUARES:
        pts = []
        if kind == "rect":
            sx, sz, sw, sd = par
            gx = sx + 1.0
            while gx <= sx + sw - 1.0:
                gz = sz + 1.0
                while gz <= sz + sd - 1.0:
                    pts.append((gx, gz))
                    gz += FAB_STEP
                gx += FAB_STEP
        else:
            # ПЛОЩАДКА БЫВАЕТ КОЛЬЦОМ, А НЕ ТОЛЬКО ДИСКОМ. У сквера
            # Гилдергрина в середине приствольный круг земли, и мерить его
            # сплошность мостовой значило бы требовать ровно того дефекта,
            # ради которого круг и вырезан. Внутренний радиус УЖЕ включает
            # метровую кайму спада (голый радиус + FADE_M), поэтому отступ в
            # метр добавляется только снаружи.
            cx, cz, rr = par[0], par[1], par[2]
            r_in = par[3] if len(par) > 3 else 0.0
            gx = cx - rr
            while gx <= cx + rr:
                gz = cz - rr
                while gz <= cz + rr:
                    dd = math.hypot(gx-cx, gz-cz)
                    if r_in <= dd <= rr - 1.0:
                        pts.append((gx, gz))
                    gz += FAB_STEP
                gx += FAB_STEP
        bad_c = bad_w = 0
        for px, pz in pts:
            c, w, _who = fab.sample(px, pz)
            if c != cls:
                bad_c += 1
            if w < 0.999:
                bad_w += 1
        n = max(1, len(pts))
        print(f"  (2) {name}: класс чужой у {100.0*bad_c/n:5.2f}%, "
              f"износ < 1.0 у {100.0*bad_w/n:5.2f}% "
              f"({len(pts)} проб внутри контура с отступом 1 м), пороги 0%")
    for name, cx, cz, rr in BARE_SPOTS:
        n = bad = 0
        who = {}
        g = -rr
        while g <= rr:
            h = -rr
            while h <= rr:
                if math.hypot(g, h) <= rr:
                    n += 1
                    _c, w, i = fab.sample(cx+g, cz+h)
                    if w > 0.0:
                        bad += 1
                        # ЧЕЙ МАЗОК — В ОТЧЁТ. Число «7.7% камня у ствола» без
                        # имени ленты не лечится: первый прогон этой меры
                        # показал утечку, и виновником оказалась не мостовая
                        # сквера (её кольцо считано верно), а УЛИЦА ВЕТРОВ,
                        # которая по замыслу упирается в дерево.
                        nm = fab.st[i][4] if i is not None else "?"
                        who[nm] = who.get(nm, 0) + 1
                h += FAB_STEP
            g += FAB_STEP
        print(f"  (2б) {name} (r={rr:.1f} м): камень у {100.0*bad/max(1,n):5.2f}% "
              f"({bad} из {n} проб), порог 0%"
              + ("" if not who else "; ленты: " + ", ".join(
                  f"«{k}» {v}" for k, v in sorted(who.items(),
                                                  key=lambda kv: -kv[1])[:3])))
    islands = []
    for i, (pts, half, soft, cls, note) in enumerate(paths):
        L = sum(math.hypot(b[0]-a[0], b[1]-a[1]) for a, b in zip(pts, pts[1:]))
        if L >= ISLAND_MIN_M:
            continue
        mid = ((pts[0][0]+pts[-1][0])/2, (pts[0][1]+pts[-1][1])/2)
        around = Fabric([p for j, p in enumerate(paths) if j != i])
        near = around.class_at(*mid)
        if near is not None and near != cls:
            islands.append((note, round(L, 2), cls, near))
    print(f"  (3) короткие острова (< {ISLAND_MIN_M:.1f} м, класс чужой "
          f"соседнему полотну): {len(islands)}, порог 0")
    for note, L, cls, near in islands[:5]:
        print(f"      «{note}» {L} м: кл.{cls} среди кл.{near}")

AXIS_GAP = 1.0      # длиннейший разрыв на процессионной оси, м (критерий)
AXIS_STEP = 0.25    # шаг проб: обязан быть заметно мельче порога разрыва

def check_axis(Hh=None, hard=()):
    """КРИТЕРИЙ ПРИЁМКИ АРХИТЕКТОРА, живущий в конвейере, а не в переписке:
    «ось ворота->рынок->замок проходится из конца в конец, не сходя с
    мощения». В числах: длиннейший разрыв <= 1.0 м при шаге проб 0.25,
    ступень на стыке <= 0.20, наложений 0. Проценты покрытия — справка:
    разрыв короче шага человека читается швом между плитами, а три метра
    голой земли — потерей нити, ради которой мощение и делается (гайд §10).
    Линия замера — сами ломаные PLAN[roads] mat=stone, то есть ровно то, что
    получает pave(): так снимается возражение «померил не ту линию».
    ...но и сама эта линия местами НЕ ПОДЛЕЖИТ МОЩЕНИЮ. Ось упирается в замок
    (гайд §11: улицы упираются в доминанты), и её последние 5.32 м лежат ВНУТРИ
    его пятна 26.6х14 — там стоит здание, а не голая земля. Прежний замер звал
    их разрывом 4.75 м и слал архитектора править габариты, которые уже
    выправлены замером 22.08. Это ровно та болезнь, что и экстраполяция плиты
    за свой край: мера, приложенная не к своему предмету. Пробы внутри тел
    исключаются из знаменателя и не считаются разрывом, а исключённая длина
    печатается — молча прятать её нельзя, иначе прибор начнёт льстить.
    ПОЛОТНО ЗЕМЛИ — ТОЖЕ ТВЁРДАЯ ПОВЕРХНОСТЬ. С fde9a7b каменный тракт это не
    лента плит, а класс полотна тропы, и покрытие им обеспечено ПО ПОСТРОЕНИЮ:
    полотно идёт по той же ломаной, по которой прибор ведёт пробы. Поэтому
    процент у каменных трактов теперь не заслуга раскладки, и врать себе, будто
    он что-то доказывает, не надо — он проверяет ровно одно: что полотно с
    каменным классом ДЕЙСТВИТЕЛЬНО выписано на этот тракт. Настоящий вопрос
    сместился на СТЫКИ: там, где ось сходит с полотна на плиту (марш террасы,
    мостовая рынка, настил моста), ступень никуда не делась и меряется.
    Прибор и три корзины пар — от wr-forge, критерий — от wr-architect."""
    if not PAVED:
        return
    print("СВЯЗНОСТЬ МОЩЕНИЯ (шаг проб %.2f м):" % AXIS_STEP)
    for i, rd in enumerate(PLAN["roads"]):
        if rd["mat"] != "stone":
            continue
        # ТРАКТ МЕРЯЕТСЯ ПРОТИВ ТОГО ПОЛОТНА, КОТОРОЕ ОН НЕСЁТ, а не против
        # мостовой вообще. С правилом «одно мощение на город» (24.08) каменный
        # тракт чертежа, ушедший ЗА кольцо стен, честно становится стёжкой —
        # и прежний фильтр `класс в (0,3)` объявил бы его сплошным разрывом.
        # Это была бы мера, приложенная не к своему предмету, третий раз за
        # волну: прибор спрашивает про связность поверхности, а не про то, из
        # чего она сделана. Класс печатается, чтобы подмена не прошла молча.
        rcls = path_class(rd)
        pts, sm = rd["pts"], []
        acc = 0.0
        for (ax, az), (bx, bz) in zip(pts, pts[1:]):
            L = math.hypot(bx-ax, bz-az)
            for j in range(max(1, int(round(L/AXIS_STEP)))):
                f = j / max(1, int(round(L/AXIS_STEP)))
                sm.append((acc + L*f, ax + (bx-ax)*f, az + (bz-az)*f))
            acc += L
        sm.append((acc, pts[-1][0], pts[-1][1]))
        # У КАЖДОЙ ПРОБЫ ЗАПОМИНАЕТСЯ И ТО, ЧЬЯ ЭТО ПОВЕРХНОСТЬ. Разность
        # соседних проб ВНУТРИ одной детали — это её уклон, а не ступень: на
        # марше 1.175/2.1 проба через 0.25 м честно даёт 0.14 м, и отчёт
        # называл бы дефектом саму лестницу. Ступень бывает только НА ПЕРЕХОДЕ
        # с детали на деталь.
        lev, who, built = [], [], []
        for _, px, pz in sm:
            fab = None
            for hp, hw, hc in hard:
                if hc != rcls:
                    continue
                for (qx, qz), (rx, rz) in zip(hp, hp[1:]):
                    vx, vz = rx-qx, rz-qz
                    L2 = vx*vx + vz*vz or 1e-9
                    tt = max(0.0, min(1.0, ((px-qx)*vx + (pz-qz)*vz) / L2))
                    if math.hypot(px-qx-vx*tt, pz-qz-vz*tt) <= hw:
                        fab = hh_at(Hh, px, pz) if Hh else 0.0
                        break
                if fab is not None:
                    break
            built.append(any(
                abs((px-bx)*math.cos(math.radians(byaw))
                    - (pz-bz)*math.sin(math.radians(byaw))) <= bw/2
                and abs((px-bx)*math.sin(math.radians(byaw))
                        + (pz-bz)*math.cos(math.radians(byaw))) <= bd/2
                for (bx, bz, bw, bd, byaw, _n) in PLACED))
            best, bi = None, None
            for pi, p in enumerate(PAVED):
                if slab_covers(p, px, pz):
                    t = slab_top(p, px, pz)
                    if best is None or t > best:
                        best, bi = t, pi
            # плита выигрывает у полотна: она и лежит поверх земли
            if best is None and fab is not None:
                best, bi = fab, -1
            lev.append(best)
            who.append(bi)
        gap = run = 0.0
        for h, b in zip(lev, built):
            run = 0.0 if (h is not None or b) else run + AXIS_STEP
            gap = max(gap, run)
        # СТУПЕНЬ НА ПЕРЕХОДЕ МЕРЯЕТСЯ НА ГРАНИЦЕ, А НЕ МЕЖДУ ПРОБАМИ. Разность
        # соседних проб по разные стороны стыка несёт ещё и УКЛОН той детали,
        # на которую проба заехала: на марше 1.375/2.0 четверть метра пробы
        # стоит 0.17 м, и стык 0.011 читался как 0.175. Обе поверхности
        # вычисляются в ОДНОЙ точке — середине между пробами, — и каждая
        # прижимается к своему пятну. Это тот же приём, которым чинилась
        # экстраполяция плиты за край; третий случай одной болезни.
        def _lvl(bi, px, pz):
            if bi is None:
                return None
            if bi < 0:
                return hh_at(Hh, px, pz) if Hh else None
            return slab_top(PAVED[bi], px, pz, clamp=True)
        worst, wat = 0.0, None
        for j in range(1, len(sm)):
            if lev[j] is None or lev[j-1] is None or who[j] == who[j-1]:
                continue
            bx2 = (sm[j][1] + sm[j-1][1]) / 2.0
            bz2 = (sm[j][2] + sm[j-1][2]) / 2.0
            ha, hb = _lvl(who[j-1], bx2, bz2), _lvl(who[j], bx2, bz2)
            if ha is None or hb is None:
                continue
            if abs(hb - ha) > worst:
                worst, wat = abs(hb - ha), sm[j]
        n_open = sum(not b for b in built)
        cov = sum(1 for h, b in zip(lev, built) if h is not None and not b)
        pct = 100.0 * cov / max(1, n_open)
        under = (len(built) - n_open) * AXIS_STEP
        line = (f"  тракт #{i} ({'мостовая' if rcls == CLS_PAVED else 'стёжка'}"
                f" кл.{rcls}): {acc:5.1f} м, покрытие {pct:5.1f}%, "
                f"разрыв {gap:5.2f} м, ступень {worst:.3f} м")
        if under > 0.4:
            line += f", под зданиями {under:4.1f} м (не мостится)"
        n_slab = sum(1 for w in who if w is not None and w >= 0)
        if n_slab:
            line += f", плитами {n_slab*AXIS_STEP:4.1f} м"
        if wat and worst > 0.02:
            line += f" у ({wat[1]:.1f},{wat[2]:.1f})"
            if worst > PAVE_STEP:
                line += " — ВЫШЕ ПОРОГА"
        print(line)

LANDMARKS = []   # (имя, cx, cz, w, d, yaw, круглое?) — ориентиры вне PLACED

def gap_rects(ax, az, aw, ad, ayaw, bx, bz, bw, bd, byaw):
    """Щель между двумя ПОВЁРНУТЫМИ пятнами. Мерить проекцией на линию
    центров нельзя: это оценка СНИЗУ, и она врёт тем сильнее, чем длиннее
    тело — на паре «колодец у таверны» разница вышла в метр (-0.22 против
    +0.78). Берём разделяющие оси обоих прямоугольников и наибольшее
    расхождение по ним: для выпуклых тел это и есть щель."""
    best = -1e9
    for (w, d, yaw) in ((aw, ad, ayaw), (bw, bd, byaw)):
        c, sn = math.cos(math.radians(yaw)), math.sin(math.radians(yaw))
        for ux, uz in ((c, -sn), (sn, c)):
            proj = abs((bx-ax)*ux + (bz-az)*uz)
            sep = proj - half_proj(aw, ad, ayaw, ux, uz) \
                       - half_proj(bw, bd, byaw, ux, uz)
            best = max(best, sep)
    return best

def check_landmarks():
    """ОРИЕНТИР — ТЕЛО, КОТОРОГО НЕТ В СПИСКЕ РАССТАНОВКИ. Колодец и
    Гилдергрин ставятся прямо из чертежа, мимо resolve_frames и мимо
    check_layout (её список — PLACED), и потому они единственные, кто может
    встать посреди улицы или внутри чужого дома, а прибор промолчит. И оба
    вставали: колодец в узле (116,152) главной улицы ([N8]), Гилдергрин в
    1.00 м от той же осевой ([N25]).
    Меряется до ОСЕВОЙ, а не до кромки полосы: по осевой идёт ходок, и
    капсуле нужен её радиус плюс ладонь. Порог 1.0 м — 0.35 капсулы и запас
    на то, что бот правит курс раз в тик, а не непрерывно."""
    if not LANDMARKS:
        return
    print("ОРИЕНТИРЫ (тела вне расстановки):")
    for name, cx, cz, w, d, yaw, rnd in LANDMARKS:
        # У КРУГЛОГО ТЕЛА ОПОРА — РАДИУС, А НЕ УГОЛ КВАДРАТА. Кольцо
        # Гилдергрина — правильный восьмигранник (радиус 2.6, вписанный 2.4);
        # квадрат 5.2х5.2 приписывает ему углы, которых нет, и врёт до метра.
        def sup(ux, uz):
            return max(w, d)/2 if rnd else half_proj(w, d, yaw, ux, uz)
        # ДО ОСЕВОЙ меряется от ГРАНИ тела, а не от его центра, и грань берётся
        # опорной функцией в направлении дороги: описанная окружность врёт на
        # полметра там, где полметра и решают.
        dax, which = 1e9, ""
        for i, rd in enumerate(PLAN["roads"]):
            for (x0, z0), (x1, z1) in zip(rd["pts"], rd["pts"][1:]):
                vx, vz = x1-x0, z1-z0
                L2 = vx*vx + vz*vz or 1e-9
                t = max(0.0, min(1.0, ((cx-x0)*vx + (cz-z0)*vz) / L2))
                qx, qz = x0+vx*t, z0+vz*t
                L = math.hypot(cx-qx, cz-qz) or 1e-9
                gap = L - sup((cx-qx)/L, (cz-qz)/L)
                if gap < dax:
                    dax, which = gap, f"#{i} ({rd['mat']})"
        dbod, bname = 1e9, ""
        for (bx, bz, bw, bd, byaw, n) in PLACED:
            if rnd:
                ux, uz = cx-bx, cz-bz
                L = math.hypot(ux, uz) or 1e-9
                gap = L - half_proj(bw, bd, byaw, ux/L, uz/L) - max(w, d)/2
            else:
                gap = gap_rects(cx, cz, w, d, yaw, bx, bz, bw, bd, byaw)
            if gap < dbod:
                dbod, bname = gap, n
        ok = (dax >= 1.0) and dbod >= 0.3
        print(f"  {name}: тело до осевой {dax:+.2f} м (ось {which}), "
              f"до тела {dbod:+.2f} м ({bname})"
              + ("" if ok else "  — ТЕСНО (ходок обязан свернуть)"))

# --- СТЕНА СКВОЗЬ ДОМА: ПРИБОР, КОТОРОГО НЕ БЫЛО ----------------------------
# ПРЕТЕНЗИЯ ВЛАДЕЛЬЦА 23.08: «несколько домов стоят в стене — стена сквозь
# дома», и отдельно «главный замок сквозь стену города проходит».
# ПОЧЕМУ ЭТОГО НЕ ВИДЕЛ НИ ОДИН СУДЬЯ, хотя судей у расстановки уже пять.
# check_layout спрашивает про ДОРОГИ, check_landmarks — про тела вне PLACED,
# resolve_frames разводит дома МЕЖДУ СОБОЙ, check_footings меряет землю, а
# check_ring_fabric — ПОЛОТНО у кладки. Кольцо стены в списке тел не состоит
# вовсе: оно кладётся напрямую через house(), мимо PLACED, — то есть для всей
# приёмки расстановки городской стены просто НЕ СУЩЕСТВУЕТ. Дом, севший в неё,
# проходил все пять проверок, и было это ровно то же, что случилось с колодцем
# ([N8]) и с самим Гилдергрином ([N25]): тело, которого нет в списке, ставится
# куда угодно, а прибор молчит.
# МЕРА. Пятно СТЕН дома (recipe_wall_rect, а не габарит со свесом кровли:
# кровля над кладкой — карниз, а стена в кладке — дефект) против ЛОМАНОЙ
# ПОСТРОЕННОЙ кладки, раздутой на полтолщины WALL_THICK/2. Пробы по оси
# кладки шагом 0.20 м; для каждой считается расстояние до повёрнутого
# прямоугольника (внутри — со знаком минус), и глубина захода кладки в дом
# это WALL_THICK/2 минус это расстояние.
# ЧИСЛА, КОТОРЫЕ ПЕЧАТАЮТСЯ: длина взаимопроникновения по оси кладки,
# наибольшая глубина и ЩЕЛЬ (у чистых домов — со знаком плюс). Порог у первых
# двух НОЛЬ, и он не смягчается: полметра кладки в спальне — не «мелкое
# наложение», а стена сквозь дом.
RING_BODY_KEEP = 1.0   # честный зазор дом<->кладка (порог владельца 23.08)
RING_PROBE = 0.20      # шаг проб по оси кладки

def _rect_dist(px, pz, cx, cz, w, d, yaw_deg):
    """Расстояние от точки до ПОВЁРНУТОГО прямоугольника; внутри — минус
    (глубина от ближайшей грани). Мерить проекцией на линию центров, как
    делала первая редакция, нельзя: у вытянутого тела это оценка снизу — та
    же болезнь, из-за которой писалась gap_rects."""
    c, sn = math.cos(math.radians(yaw_deg)), math.sin(math.radians(yaw_deg))
    lx = (px-cx)*c - (pz-cz)*sn
    lz = (px-cx)*sn + (pz-cz)*c
    dx, dz = abs(lx) - w/2, abs(lz) - d/2
    if dx > 0.0 or dz > 0.0:
        return math.hypot(max(dx, 0.0), max(dz, 0.0))
    return max(dx, dz)

def wallbase_rects():
    """(имя, cx, cz, w, d, yaw) пятен СТЕН всех построек плана — одна выборка
    на всех, кто спрашивает про пятно, а не про габарит."""
    out = []
    for rec, ox, oz, yaw, _oy, name, _base in WALLBASE:
        x0, z0, x1, z1 = recipe_wall_rect(rec)
        cx, cz = loc_to_world(ox, oz, yaw, (x0+x1)/2, (z0+z1)/2)
        out.append((name, cx, cz, x1-x0, z1-z0, yaw))
    return out

def check_ring_bodies():
    """ПРИЁМКА «СТЕНА СКВОЗЬ ДОМА». Порог: длина взаимопроникновения 0 м у
    всех построек. Печатаются ВСЕ случаи, а не худший: владелец сказал
    «несколько домов», и прибор, показывающий один, оставил бы остальные в
    городе."""
    if not RING_AXES or not WALLBASE:
        return
    half = WALL_THICK/2
    rows = []
    for name, cx, cz, w, d, yaw in wallbase_rects():
        # быстрый отсев по описанной окружности — иначе 26 домов на 28 кусков
        # по 60 проб это перебор ради нуля
        rad = math.hypot(w, d)/2 + half + RING_BODY_KEEP
        hit_len, deep, gap, where = 0.0, 0.0, 1e9, None
        for ax in RING_AXES:
            if all(math.hypot(px-cx, pz-cz) > rad + 8.0 for px, pz in ax):
                continue
            for i, (a, b) in enumerate(zip(ax, ax[1:])):
                L = math.hypot(b[0]-a[0], b[1]-a[1])
                n = max(1, int(math.ceil(L / RING_PROBE)))
                for k in range(n):
                    t = (k + 0.5) / n
                    px, pz = a[0] + (b[0]-a[0])*t, a[1] + (b[1]-a[1])*t
                    dd = _rect_dist(px, pz, cx, cz, w, d, yaw)
                    if dd - half < gap:
                        gap, where = dd - half, (px, pz)
                    if dd < half:
                        hit_len += L/n
                        deep = max(deep, half - dd)
        if gap < RING_BODY_KEEP:
            rows.append((hit_len, deep, gap, name, where))
    bad = [r for r in rows if r[0] > 0.0]
    print(f"СТЕНА СКВОЗЬ ДОМА (пятно стен против кладки, полтолщины "
          f"{half:.2f} м, шаг проб {RING_PROBE:.2f} м): {len(bad)} построек "
          f"из {len(WALLBASE)} в теле кольца, порог 0")
    for hit_len, deep, gap, name, where in sorted(rows, reverse=True):
        mark = ("  — КЛАДКА В ТЕЛЕ ДОМА" if hit_len > 0.0 else
                "  — тесно (порог %.1f м)" % RING_BODY_KEEP)
        print(f"  {name} у ({where[0]:.1f},{where[1]:.1f}): "
              f"взаимопроникновение {hit_len:.2f} м, глубина {deep:.2f} м, "
              f"щель {gap:+.2f} м{mark}")
    if not rows:
        print(f"  ни одна постройка не подходит к кладке ближе "
              f"{RING_BODY_KEEP:.1f} м")
    return len(bad)

def dump_footprints(path):
    """ПЯТНА ДОМОВ НАРУЖУ, для прибора, который меряет ПОСТРОЕННУЮ землю.
    check_floors ниже щупает ground() — ту же сетку PLAN_H, из которой пад и
    вырезан, и потому отвечает на вопрос «легло ли задуманное в задуманное»,
    а не «где земля у стены в игре». Настоящую землю (natural + pads + rivers
    + relief) знает только движок; чтобы его спросить, наружу нужен список
    пятен.

    ПЯТНО ЗДЕСЬ — ПРЯМОУГОЛЬНИК СТЕН, А НЕ ГАБАРИТ, и судится ОТМЕТКА НИЗА
    СТЕН, а не верх половой плиты: заказ владельца говорит «ни один сантиметр
    СТЕНЫ не должен быть в земле», а между низом стены и полом лежит своя
    плита (у city-house-l — цоколь 0.525), которую земле трогать тоже нельзя.
    Формат: name|cx|cz|w|d|yaw|низ_стен|низ_фундамента."""
    with open(path, "w", encoding="utf-8") as f:
        f.write("# name|cx|cz|w|d|yaw_deg|wall_base_y|footing_base_y\n")
        for rec, ox, oz, yaw, oy, name, base in WALLBASE:
            x0, z0, x1, z1 = recipe_wall_rect(rec)
            cx, cz = loc_to_world(ox, oz, yaw, (x0+x1)/2, (z0+z1)/2)
            f.write(f"{name}|{cx:.3f}|{cz:.3f}|{x1-x0:.3f}|{z1-z0:.3f}|{yaw:.3f}|"
                    f"{oy:.3f}|{'' if base is None else f'{base:.3f}'}\n")
    print(f"пятна домов записаны в {path}")

def check_footings():
    """ДВА ЧИСЛА ЗАКАЗА 23.08, И ОНИ ПРОТИВОПОЛОЖНЫ ПО ЗНАКУ.

    1. УТОПЛЕННОСТЬ: max(земля по пятну СТЕН) - отметка низа стен. Должна быть
       <= 0 у ВСЕХ — «ни один сантиметр стены не в земле».
    2. ВКОП ЛЕНТЫ: низ фундамента - min(земля по тому же пятну). Тоже <= 0 —
       «фундамент везде в земле, а не висит».
    Одно без другого ничего не значит: дом, поднятый на метр над землёй,
    выполнит первое условие блестяще и провалит второе, и это будет постройка
    на сваях. Поэтому мера парная, и печатаются оба хвоста.

    Мерится ПОЛЕ ЭТОГО ПРОХОДА (PLAN_H) — то самое, что уйдёт в relief.
    Внешняя рука по ПОСТРОЕННОЙ земле движка — tools/probe_ground.cpp; она
    поймала бы расхождение полей, если бы оно вернулось."""
    if not WALLBASE:
        return
    sink, hang, n_no = [], [], 0
    for rec, ox, oz, yaw, oy, name, base in WALLBASE:
        pts = [p for p in wall_pts(rec, ox, oz, yaw) if not in_channel(*p)]
        if not pts:
            n_no += 1
            continue
        gs = [hh_at(PLAN_H_REF[0], px, pz) for px, pz in pts]
        sink.append((max(gs) - oy, name, ox, oz))
        if base is not None:
            hang.append((base - min(gs), name, ox, oz))
    sink.sort(reverse=True)
    hang.sort(reverse=True)
    bad_s = sum(1 for v, *_ in sink if v > 0.0)
    bad_h = sum(1 for v, *_ in hang if v > 0.0)
    print(f"ФУНДАМЕНТ: утоплено {bad_s} из {len(sink)} "
          f"(земля выше низа стен), висит {bad_h} из {len(hang)} "
          f"(низ ленты выше земли)")
    print(f"  худшая утопленность {sink[0][0]:+.2f} м ({sink[0][1]}), "
          f"лучший запас {sink[-1][0]:+.2f} м")
    if hang:
        print(f"  худший вкоп {hang[0][0]:+.2f} м ({hang[0][1]}), "
              f"глубже всех {hang[-1][0]:+.2f} м")
    if n_no:
        print(f"  {n_no} пятен целиком в русле — ленты нет, там нет земли")
    if STOOPS:
        rs = sorted(s[0] for s in STOOPS)
        print(f"  крылец {len(STOOPS)}: подъём {rs[0]:.1f}..{rs[-1]:.1f} м, "
              f"подступенок 0.15..0.20, проступь 0.30, ширина {STOOP_W:.1f} м")
        for k, dx, dz, fx, fz, nm in sorted(STOOPS, reverse=True)[:3]:
            print(f"    {nm}: {k:.1f} м, дверь ({dx:.1f},{dz:.1f}), "
                  f"подножие ({fx:.1f},{fz:.1f})")
    for nm, need, best in FOOT_SHORT:
        print(f"  РЯДУ НЕ ХВАТИЛО: {nm} просит ленту {need:.2f} м, "
              f"в выпечке самая высокая {best:.2f} — перепад под пятном "
              f"больше, чем бывает у фундамента (вопрос террасы)")

def check_floors():
    """ЗЕМЛЯ ПОД ПОЛОМ, А НЕ НАД НИМ (претензия владельца 23.08). Мерится по
    ДАМПУ ИТОГОВОЙ ЗЕМЛИ (ground = сетка прошлого прохода двухпроходного
    цикла), а не по полю чертежа: поле — это то, что мы ХОТЕЛИ, дамп — то,
    что движок построил, а протыкает пол именно построенное. Пятно щупается
    сеткой 7х7 по повёрнутому прямоугольнику.
    Порог владельца: max(земля в пятне) <= пол + 0.02; мебель y >= пол - 0.01."""
    if not FLOORS:
        return
    worst, bad = [], 0
    for cx, cz, w, d, yaw, fl, name in FLOORS:
        gs = [g for g in (ground(px, pz)
                          for px, pz in rect_points(cx, cz, w, d, yaw, n=7))
              if g is not None]
        if not gs:
            continue
        over = max(gs) - fl
        worst.append((over, f"{name} ({cx:.1f},{cz:.1f})"))
        if over > 0.02:
            bad += 1
    worst.sort(reverse=True)
    print(f"ЗЕМЛЯ ПОД ПОЛОМ: {len(worst) - bad} из {len(worst)} домов в норме "
          f"(земля не выше пола + 0.02)")
    for over, name in worst[:5]:
        print(f"  {name}: земля выше пола на {over:+.2f} м"
              + ("" if over <= 0.02 else "  — ПРОТЫКАЕТ ПОЛ"))
    fbad = [(y - fl, n) for (y, fl, n) in FURN_Y if y - fl < -0.01]
    print(f"  мебель: {len(FURN_Y) - len(fbad)} из {len(FURN_Y)} не ниже пола"
          + ("" if not fbad else f"; худшая {min(fbad)[0]:+.2f} м ({min(fbad)[1]})"))

def check_layout():
    import itertools
    bad = []
    for (c1, z1, w1, d1, y1, n1), (c2, z2, w2, d2, y2, n2) in itertools.combinations(PLACED, 2):
        if math.hypot(c1-c2, z1-z2) < (max(w1,d1) + max(w2,d2)) / 2 * 0.55:
            bad.append(f"близко: {n1} и {n2}")
    for rd in PLAN["roads"]:
        for (cx, cz, w, d, y, n) in PLACED:
            if n.startswith("дорожка"):
                continue
            if rect_road_hit(cx, cz, w, d, y, rd):
                # КООРДИНАТА В ОТЧЁТ: имён «дом» в городе двенадцать, и строка
                # «на дороге: дом» не говорит, какой именно — а отодвиг от
                # кладки 23.08 добавил сюда два новых дома, и без координаты
                # их пришлось искать сверкой дампов пятен.
                bad.append(f"на дороге ({rd['mat']}): {n} ({cx:.1f},{cz:.1f})")
    if bad:
        print("ПРОВЕРКА РАССТАНОВКИ:")
        for b in sorted(set(bad)):
            print("  -", b)

def point_in_poly(x, z, pts):
    inside = False
    n = len(pts)
    j = n - 1
    for i in range(n):
        xi, zi = pts[i]
        xj, zj = pts[j]
        if (zi > z) != (zj > z) and x < (xj - xi) * (z - zi) / (zj - zi) + xi:
            inside = not inside
        j = i
    return inside

def build_plan_heights():
    """Карта высот SPANxSPAN ИЗ ПОЛИГОНОВ чертежа: последняя содержащая зона
    побеждает, поверх микропятна, затем гауссово сглаживание — перепады
    1-3 м из схемы становятся склонами 20-30%, без паразитных горок
    эллипс-аппроксимации (бот v5-3 утыкался в такую у рынка)."""
    Hh = [[25.0] * SPAN for _ in range(SPAN)]
    for zn in PLAN["zones"]:
        xs = [q[0] for q in zn["pts"]]
        zs = [q[1] for q in zn["pts"]]
        x0, x1 = max(0, int(min(xs)) - 1), min(LAST, int(max(xs)) + 2)
        z0, z1 = max(0, int(min(zs)) - 1), min(LAST, int(max(zs)) + 2)
        for gz in range(z0, z1 + 1):
            for gx in range(x0, x1 + 1):
                if point_in_poly(gx, gz, zn["pts"]):
                    Hh[gz][gx] = float(zn["h"])
    for m in PLAN["micro"]:
        xs = [q[0] for q in m["pts"]]
        zs = [q[1] for q in m["pts"]]
        for gz in range(max(0, int(min(zs))), min(LAST, int(max(zs))) + 1):
            for gx in range(max(0, int(min(xs))), min(LAST, int(max(xs))) + 1):
                if point_in_poly(gx, gz, m["pts"]):
                    Hh[gz][gx] += m["dh"]
    # сепарабельный блюр (три прохода box ~ гаусс сигма ~2.2)
    for _ in range(3):
        for row in Hh:
            acc = row[:]
            for i in range(SPAN):
                lo, hi = max(0, i - 2), min(LAST, i + 2)
                row[i] = sum(acc[lo:hi + 1]) / (hi - lo + 1)
        for i in range(SPAN):
            col = [Hh[r][i] for r in range(SPAN)]
            for r in range(SPAN):
                lo, hi = max(0, r - 2), min(LAST, r + 2)
                Hh[r][i] = sum(col[lo:hi + 1]) / (hi - lo + 1)
    return Hh

# НАТУРАЛЬНАЯ ЗЕМЛЯ — ТОЖЕ ПАРАМЕТР, и по той же причине, по какой им стало
# поле высот (WHITERUN_WRITE_HEIGHTS, 24.08): дельты relief считаются ОТ неё, и
# снимок разовой руки делает ложью весь рельеф города, а не одну посадку. Файл
# пишет прибор по СЦЕНЕ (tools/probe_ground.cpp на выпуске WHITERUN_BARE=1),
# а не генератор: натуральную землю знает движок.
# Путь — в load_city(): у каждого города свой замер.

# --- РЕКА: отметка воды снимается с ЗЕМЛИ, а не задаётся формулой -----------
# Порядок движка (Worldgen.cpp compose_passes): пады -> РЕКА -> ручной relief.
# Ручной слой говорит ПОСЛЕДНИМ, поэтому дельты чертежа зарисовывали русло
# обратно, а вода 23.6-i*0.08 оставалась на 3-4 м ниже земли — реки в кадре
# не было. Лечится двумя вещами:
#   1) вода = минимальная кромка ДВУХ берегов минус RIVER_FREEBOARD, с
#      монотонностью вниз по течению (река с горы-истока не течёт вверх);
#   2) дельты relief ГАСЯТСЯ в коридоре русла тем же smoothstep, каким движок
#      сводит дно с берегом (river_taper) — вырез движка остаётся вырезом.
# Дно = вода - RIVER_DEPTH берётся движком безусловно (apply_rivers), поэтому
# отдельные dh на дно не нужны: они бы его и засыпали.
RIVER_BANK_M = 3.0      # ширина сведения дна с берегом (1.4 м на 3 м ~ 25 гр.)
RIVER_DEPTH = 1.0       # дно ниже воды

# ХОДИБЕЛЬНАЯ ПОВЕРХНОСТЬ МОСТА — ЗАМЕР ПО РЕЦЕПТУ, а не «максимум вершин в
# окне». Прежний замер брал max(y) среди вершин у торца и ловил ПАРАПЕТ, отчего
# числа расходились вдвое и нельзя было сказать, где настил.
# У МОСТА-АРКИ (city-bridge-arc, выпечка кузни-2) полотно — это шесть
# НАКЛОННЫХ ПЛИТ (closed=1, thickness=0.30, поперёк z 0..4), сложенных в
# горбатый профиль: аппарель -8.601..0.390 (наклон 8.53 гр.), потом три
# перегиба до конька на x=4.0 и симметрично вниз до 16.601. Верх плиты лежит
# на ПОЛТОЛЩИНЫ ПО НОРМАЛИ, и на наклонной плите это ВЫСТУПАЕТ ЗА УЗЕЛ ОСИ:
# полотно кончается на локальном x=-8.623 (y=-0.4012), а не на -8.601 (ответ
# кузницы на вопрос предшественника; замер сходится до миллиметра).
# Поэтому профиль не выписан числами, а СНИМАЕТСЯ: bridge_deck() строит
# ломаную верха из тех же плит, и всё остальное (отметка торца, отметка в
# точке схода на берег) спрашивается у неё.
BRIDGE_REC = "city-bridge-arc.dfh"
BRIDGE_CHORD = 12.8   # видимый пролёт: между точками схода настила на берега
_DECK = None

def bridge_deck():
    """Верх настила: ломаная [(локальный x, y)], снятая с наклонных плит
    рецепта. Крайние точки — торцы ХОДИБЕЛЬНОЙ поверхности."""
    global _DECK
    if _DECK is not None:
        return _DECK
    V, tops = {}, []
    for line in open(os.path.join(ROOT, "assets/houses", BRIDGE_REC),
                     encoding="utf-8"):
        t = line.split()
        if not t:
            continue
        if t[0] == "vertex":
            V[t[1]] = (float(t[3]), float(t[4]), float(t[5]))
        elif t[0] == "surface" and "thickness=0.30" in line:
            vs = [v for v in t[2:] if v in V]
            if len(vs) != 4:
                continue
            pts = [V[v] for v in vs]
            if abs(max(p[2] for p in pts) - 4.0) > 1e-3 \
               or abs(min(p[2] for p in pts)) > 1e-3:
                continue          # не полотно: свод, парапет, щёки
            xs = sorted({(p[0], p[1]) for p in pts})
            if len(xs) != 2:
                continue
            (x0, y0), (x1, y1) = xs
            dx, dy = x1-x0, y1-y0
            L = math.hypot(dx, dy) or 1e-9
            nx, ny = -dy/L, dx/L
            if ny < 0:
                nx, ny = -nx, -ny
            tops.append(((x0 + nx*0.15, y0 + ny*0.15),
                         (x1 + nx*0.15, y1 + ny*0.15)))
    pts = sorted({p for seg in tops for p in seg})
    _DECK = pts
    return _DECK

def deck_top(lx):
    """Отметка верха настила на локальном x (за торцами — отметка торца)."""
    pts = bridge_deck()
    if lx <= pts[0][0]:
        return pts[0][1]
    if lx >= pts[-1][0]:
        return pts[-1][1]
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if x0 <= lx <= x1:
            return y0 + (y1-y0) * (lx-x0) / ((x1-x0) or 1e-9)
    return pts[-1][1]

RIVER_FREEBOARD = 0.40  # вода ниже кромки берега

def hh_at(Hh, x, z):
    xi = min(max(x, 0.0), EDGE)
    zi = min(max(z, 0.0), EDGE)
    x0, z0 = int(xi), int(zi)
    fx, fz = xi - x0, zi - z0
    r0, r1 = Hh[z0], Hh[z0 + 1]
    return ((r0[x0]*(1-fx) + r0[x0+1]*fx) * (1-fz)
            + (r1[x0]*(1-fx) + r1[x0+1]*fx) * fz)

def river_tangent(pts, i):
    a = pts[max(0, i-1)]
    b = pts[min(len(pts)-1, i+1)]
    vx, vz = b[0]-a[0], b[1]-a[1]
    L = math.hypot(vx, vz) or 1.0
    return vx/L, vz/L

def river_levels(Hh):
    """Отметка воды в каждой вершине осевой КАЖДОГО русла: ниже НИЖНЕГО из двух
    берегов на RIVER_FREEBOARD, монотонно НЕВОЗРАСТАЯ вниз по течению.
    Отдаётся списком по руслам: у второй реки свой исток и своя монотонность,
    и общий список отметок склеил бы их в одну."""
    out = []
    for riv in RIVERS:
        pts = riv["pts"]
        off = riv["half_w"] + RIVER_BANK_M
        lv = []
        for i, (x, z) in enumerate(pts):
            ux, uz = river_tangent(pts, i)
            nx, nz = -uz, ux
            banks = []
            for s in (-1.0, 1.0):
                # берег меряется тремя отсчётами вдоль течения — одиночная точка
                # ловила случайную кочку блюра и роняла плёс на полметра
                banks.append(min(hh_at(Hh, x + nx*off*s + ux*t, z + nz*off*s + uz*t)
                                 for t in (-2.0, 0.0, 2.0)))
            lv.append(min(banks) - RIVER_FREEBOARD)
        for i in range(1, len(lv)):
            lv[i] = min(lv[i], lv[i-1])
        out.append(lv)
    return out

def river_near(x, z):
    """[(расстояние до осевой, русло)] по всем руслам карты. Мера у каждого
    своя: полуширина рукава входит в порог, а у второго рукава она другая."""
    out = []
    for riv in RIVERS:
        pts = riv["pts"]
        best = 1e9
        for (x0, z0), (x1, z1) in zip(pts, pts[1:]):
            dx, dz = x1-x0, z1-z0
            L2 = dx*dx + dz*dz
            t = max(0.0, min(1.0, ((x-x0)*dx + (z-z0)*dz) / L2))
            best = min(best, math.hypot(x - (x0+dx*t), z - (z0+dz*t)))
        out.append((best, riv))
    return out

def river_dist(x, z):
    """До БЛИЖАЙШЕГО русла. Порогов, зависящих от полуширины, здесь нет —
    для них есть river_near; это мера «далеко ли вообще вода»."""
    return min((d for d, _r in river_near(x, z)), default=1e9)

def river_taper(x, z):
    """Доля ручной дельты, доживающая до этой точки: 0 в русле, 1 за берегом.
    Тот же smoothstep, что у apply_rivers, — берег сходится без ступеньки.
    По руслам берётся МИНИМУМ: гасит то, что гасит сильнее, иначе на слиянии
    двух рукавов дельта чертежа зарисовала бы вырез движка обратно."""
    val = 1.0
    for d, riv in river_near(x, z):
        half = riv["half_w"]
        if d <= half:
            return 0.0
        if d >= half + RIVER_BANK_M:
            continue
        t = (d - half) / RIVER_BANK_M
        val = min(val, t * t * (3.0 - 2.0 * t))
    return val

def grade_roads(Hh, skip_rect=None):
    """Полотно каменных трактов по СГЛАЖЕННОМУ продольному профилю."""
    for rd in PLAN["roads"]:
        if rd["mat"] != "stone":
            continue
        raw = [hh_at(Hh, x, z) for x, z in rd["pts"]]
        sm = [sum(raw[max(0, i-1):i+2]) / len(raw[max(0, i-1):i+2])
              for i in range(len(raw))]
        nodes = [(x, z, h) for (x, z), h in zip(rd["pts"], sm)]
        grade_corridor(Hh, nodes, max(3.2, rd["w"]/2 + 0.4), 5.0, skip_rect)

def grade_rect(Hh, x0, z0, w, d, feather, level=None):
    """Планировка ПРЯМОУГОЛЬНОЙ площадки: поле высот прижимается к отметке
    (по умолчанию — медиана самого пятна) с затуханием smoothstep на кайме
    feather. Для рынка: торговая площадь мостится жёсткой плитой, а плита не
    повторяет рельеф — под ней земля должна быть ровной, иначе плита где-то
    висит, а где-то тонет, и её кромка становится обрывом."""
    pts = [(x0 + w*i/8.0, z0 + d*j/8.0) for i in range(9) for j in range(9)]
    if level is None:
        s = sorted(hh_at(Hh, px, pz) for px, pz in pts)
        level = s[len(s)//2]
    R = feather
    for gz in range(max(0, int(z0-R)-1), min(LAST, int(z0+d+R)+1) + 1):
        for gx in range(max(0, int(x0-R)-1), min(LAST, int(x0+w+R)+1) + 1):
            ddx = max(x0 - gx, gx - (x0 + w), 0.0)
            ddz = max(z0 - gz, gz - (z0 + d), 0.0)
            dist = math.hypot(ddx, ddz)
            if dist >= R:
                continue
            u = 1.0 - dist / R
            wgt = u * u * (3.0 - 2.0 * u)
            Hh[gz][gx] = Hh[gz][gx] * (1.0 - wgt) + level * wgt
    return level

def grade_corridor(Hh, nodes, halfw, feather, skip_rect=None):
    """skip_rect — СПИСОК прямоугольников-исключений [(x, z, w, d), ...]."""
    """ПЛАНИРОВКА КОРИДОРА в поле высот чертежа: вдоль ломаной [(x,z,h)…] поле
    прижимается к заданной отметке (интерполяция по длине), с полной силой в
    полосе halfw и затуханием smoothstep до нуля на halfw+feather. Поле
    чертежа И ЕСТЬ земля (relief пишет дельту к ней), поэтому подходы,
    подъезды и срезы делаются здесь, а не отдельным слоем."""
    segs = list(zip(nodes, nodes[1:]))
    xs = [n[0] for n in nodes]
    zs = [n[1] for n in nodes]
    R = halfw + feather
    x0 = max(0, int(min(xs) - R) - 1)
    x1 = min(LAST, int(max(xs) + R) + 1)
    z0 = max(0, int(min(zs) - R) - 1)
    z1 = min(LAST, int(max(zs) + R) + 1)
    for gz in range(z0, z1 + 1):
        for gx in range(x0, x1 + 1):
            best, lvl = 1e9, None
            for (ax, az, ah), (bx, bz, bh) in segs:
                vx, vz = bx-ax, bz-az
                L2 = vx*vx + vz*vz
                t = max(0.0, min(1.0, ((gx-ax)*vx + (gz-az)*vz) / L2))
                d = math.hypot(gx - (ax+vx*t), gz - (az+vz*t))
                if d < best:
                    best, lvl = d, ah + (bh-ah)*t
            if best >= R:
                continue
            # ЧУЖАЯ ПЛОЩАДКА ГОВОРИТ ТАМ ПОСЛЕДНЕЙ. Площадок стало ДВЕ
            # (рынок и сквер Гилдергрина), поэтому исключение — СПИСОК:
            # один прямоугольник тут стоял ровно потому, что площадь была
            # одна, а не потому, что их не может быть больше.
            if skip_rect is not None and any(
                    rx <= gx <= rx + rw and rz <= gz <= rz + rd
                    for rx, rz, rw, rd in skip_rect):
                continue
            if best <= halfw:
                w = 1.0
            else:
                u = 1.0 - (best - halfw) / feather
                w = u * u * (3.0 - 2.0 * u)
            Hh[gz][gx] = Hh[gz][gx] * (1.0 - w) + lvl * w

def water_at(levels, x, z):
    """Отметка воды у ближайшей точки осевой ЛЮБОГО русла (как river_nearest
    движка). levels — список по руслам, как его отдаёт river_levels."""
    best, w = 1e9, levels[0][0]
    for ri, riv in enumerate(RIVERS):
        pts = riv["pts"]
        for i, ((x0, z0), (x1, z1)) in enumerate(zip(pts, pts[1:])):
            dx, dz = x1-x0, z1-z0
            L2 = dx*dx + dz*dz
            t = max(0.0, min(1.0, ((x-x0)*dx + (z-z0)*dz) / L2))
            d = math.hypot(x - (x0+dx*t), z - (z0+dz*t))
            if d < best:
                best, w = d, (levels[ri][i]
                              + (levels[ri][i+1] - levels[ri][i]) * t)
    return w

def bridge_frame():
    """Рама моста: (origin рецепта, точка оси при локальном x=0, вектор вдоль
    пролёта). Мост-арка занимает локально x -8.601..16.601, z 0..4, но СЕРЕДИНА
    (конёк, ось свода) по-прежнему на локальном x=4, z=2 — как у прежнего
    12.8-метрового настила, поэтому вся посадка ниже осталась той же: origin
    отступает от точки чертежа на (4,2), повёрнутые.
    ПРОЛЁТ ЦЕНТРИРУЕТСЯ НА РУСЛЕ: точка [center] чертежа лежала в 0.66 м
    западнее осевой, и торцы уходили на 7.0 и 5.3 м от неё — восточная
    аппарель оставалась внутри берегового сведения движка и висела метром
    выше земли. Сдвиг вдоль пролёта делает оба выхода симметричными."""
    b = PLAN["bridge"]
    bx, bz = b["center"]
    # РАЗВОРОТ БЕРЁТСЯ У ДОРОГИ, А НЕ У РЕКИ. Чертёж задаёт мосту deg=14, и
    # это перпендикуляр к руслу — геометрически красиво и практически неверно:
    # тракт пересекает реку под своим углом, и мост, поставленный поперёк
    # ВОДЫ, расходился с ним на 28 градусов. Торцы аппарелей уезжали от
    # осевой на 4.9 м, и бот честно проходил МИМО моста по берегу (замер: на
    # восток шёл по шельфу на y=27.7 и падал с него 2.6 м у x=162; на запад
    # переходил и утыкался в парапет с внутренней стороны). Мост существует
    # ради дороги, поэтому разворот у него дорожный; на воде он всё равно
    # остаётся центрированным — этим занимается сдвиг sh ниже.
    # ...И БЕРЁТСЯ У ХОРДЫ ТРАКТА НА ДЛИНУ ВИДИМОГО ПРОЛЁТА, А НЕ У ОТРЕЗКА В
    # ТОЧКЕ. Тракт у переправы ломается: в самой точке чертежа сходятся два
    # отрезка, (166,127)-(159.5,130) под 24.8 гр. и (159.5,130)-(152,131) под
    # 7.6, и прежний перебор «ближайший отрезок» брал ТОТ, ЧТО ПОПАЛСЯ ПЕРВЫМ
    # (расстояние у обоих нулевое). Пока настил был 12.8 м, разница уводила
    # осевую на полметра и это терпелось; у арки видимый пролёт 12.8 м, а тело
    # 25.2 — тот же угол уводит торцы вдвое дальше. Разворот берётся у ХОРДЫ:
    # от точки тракта в 6.4 м к западу до точки в 6.4 м к востоку, обе по
    # самой ломаной. Замер отхода осевой от середины настила (ход между
    # парапетами ±1.70): отрезком 1.55 м у западного схода, хордой 1.06 м.
    def road_walk(px, pz, dist):
        """Точка на ломаной каменного тракта в dist метрах от (px,pz) по ходу
        на восток (dist<0 — на запад)."""
        pts = None
        best, at = 1e9, (px, pz, 0, 0.0)
        for rd in PLAN["roads"]:
            if rd["mat"] != "stone":
                continue
            for i, ((x0, z0), (x1, z1)) in enumerate(zip(rd["pts"], rd["pts"][1:])):
                vx, vz = x1-x0, z1-z0
                L = math.hypot(vx, vz) or 1e-9
                t = max(0.0, min(1.0, ((px-x0)*vx + (pz-z0)*vz) / (L*L)))
                d = math.hypot(px - (x0+vx*t), pz - (z0+vz*t))
                if d < best:
                    best, pts, at = d, rd["pts"], (x0+vx*t, z0+vz*t, i, t*L)
        if pts is None:
            return (px, pz)
        # ломаная упорядочена с востока на запад у этого тракта — идём по её
        # длине в нужную сторону, знак берём у направления «на восток»
        qx, qz, i, off = at
        step = 0.25 if dist > 0 else -0.25
        left = abs(dist)
        while left > 1e-9:
            (x0, z0), (x1, z1) = pts[i], pts[i+1]
            vx, vz = x1-x0, z1-z0
            L = math.hypot(vx, vz) or 1e-9
            east = 1.0 if vx >= 0 else -1.0
            adv = min(0.25, left)
            off += adv * (step/abs(step)) * east
            left -= adv
            if off < 0.0:
                if i == 0:
                    off = 0.0
                    break
                i -= 1
                off += math.dist(pts[i], pts[i+1])
            elif off > L:
                if i + 2 >= len(pts):
                    off = L
                    break
                off -= L
                i += 1
        (x0, z0), (x1, z1) = pts[i], pts[i+1]
        vx, vz = x1-x0, z1-z0
        L = math.hypot(vx, vz) or 1e-9
        return (x0 + vx*off/L, z0 + vz*off/L)

    ax, az = road_walk(bx, bz, -BRIDGE_CHORD/2)
    cx, cz = road_walk(bx, bz, BRIDGE_CHORD/2)
    tux, tuz = cx-ax, cz-az
    nl = math.hypot(tux, tuz) or 1.0
    tux, tuz = (tux/nl, tuz/nl) if tux >= 0 else (-tux/nl, -tuz/nl)
    yaw = math.atan2(-tuz, tux)
    ux, uz = math.cos(yaw), -math.sin(yaw)
    zx, zz = math.sin(yaw), math.cos(yaw)
    # СМЕЩЕНИЕ ОТ ЦЕНТРА К УГЛУ ПОВОРАЧИВАЕТСЯ. Стояло `bx-4, bz-2` — верно
    # только при yaw 0. Пока мост стоял под −14 градусами, ошибка была мелкой;
    # с дорожным разворотом 24.8 настил уехал на 1.6 м от осевой, и бот шёл по
    # берегу мимо него. Ровно та же болезнь, что у прилавков рынка: точка
    # чертежа — ЦЕНТР детали, а origin лежит в её углу.
    ox = bx - (4.0*math.cos(yaw) + 2.0*math.sin(yaw))
    oz = bz + 4.0*math.sin(yaw) - 2.0*math.cos(yaw)
    mx, mz = ox + zx*2.0, oz + zz*2.0
    sh = min(((river_dist(mx + ux*(4.0+s), mz + uz*(4.0+s)), s)
              for s in (i*0.05 for i in range(-80, 81))))[1]
    return ((ox + ux*sh, oz + uz*sh), (mx + ux*sh, mz + uz*sh), (ux, uz),
            math.degrees(yaw))

# --- ОСЬ КОЛЬЦА: СГЛАЖЕННАЯ КРИВАЯ ЧЕРТЕЖА ---------------------------------
# Ломаная чертежа — 14 вершин с изломами 14-49 гр., и ПРЯМОЙ прогон, положенный
# по ней, оставляет на каждом изломе КЛИН на наружном лице: при толщине кладки
# 1.2 м клин равен 1.2*tg(излом/2) — 0.21 м на самом пологом изломе и 0.549 м
# на вершине (110,60). Числа сняты прибором по СЦЕНЕ (обе руки одной мерой),
# а не выведены: 10 стыков из 31 несли клин 0.20 м и больше.
# Гнутый прогон кузницы съедает поворот ВНУТРИ куска, но чтобы это работало,
# кольцо надо вести не по ломаной, а по КРИВОЙ. Ось — замкнутый Catmull-Rom
# ЧЕРЕЗ вершины чертежа (центростремительный, alpha=0.5: рёбра 15-28 м, и
# равномерная параметризация даёт выброс на коротком). Именно ЧЕРЕЗ, а не
# срезая углы: на вершинах стоят башни, и кривая, обрезающая угол по Шайкину,
# увела бы от них кладку на два-три метра.
RING_STEP = 0.10        # шаг выборки кривой, м

def _ring_build():
    """Кривая кольца: плотная ломаная + таблица длин по дуге."""
    P = [(float(x), float(z)) for x, z in PLAN["wall"]]
    n = len(P)
    pts = []
    for i in range(n):
        p0, p1, p2, p3 = P[(i-1) % n], P[i], P[(i+1) % n], P[(i+2) % n]
        t = [0.0]
        for a, b in ((p0, p1), (p1, p2), (p2, p3)):
            t.append(t[-1] + max(1e-6, math.dist(a, b)) ** 0.5)
        seg = max(8, int(math.dist(p1, p2) / RING_STEP))
        for k in range(seg):
            tt = t[1] + (t[2] - t[1]) * k / seg
            def mix(a, b, ta, tb):
                w = (tb - tt) / (tb - ta)
                return (a[0]*w + b[0]*(1-w), a[1]*w + b[1]*(1-w))
            A1 = mix(p0, p1, t[0], t[1])
            A2 = mix(p1, p2, t[1], t[2])
            A3 = mix(p2, p3, t[2], t[3])
            B1 = mix(A1, A2, t[0], t[2])
            B2 = mix(A2, A3, t[1], t[3])
            pts.append(mix(B1, B2, t[1], t[2]))
    cum = [0.0]
    for a, b in zip(pts, pts[1:] + [pts[0]]):
        cum.append(cum[-1] + math.dist(a, b))
    return {"pts": pts, "cum": cum, "tot": cum[-1]}

RING = None     # кривая кольца; строится в load_city(), когда прочитан чертёж

def ring_pt(s):
    """Точка кривой кольца по длине дуги (замкнуто)."""
    tot = RING["tot"]
    s = s % tot
    cum, pts = RING["cum"], RING["pts"]
    lo, hi = 0, len(cum) - 1
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if cum[mid] <= s:
            lo = mid
        else:
            hi = mid
    a = pts[lo]
    b = pts[(lo + 1) % len(pts)]
    seg = cum[lo+1] - cum[lo] or 1e-9
    f = (s - cum[lo]) / seg
    return (a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f)

def ring_tan(s, h=0.25):
    """Единичная касательная кривой в точке s (центральная разность: у стыка
    двух звеньев направление одного звена дёргается на шаге выборки)."""
    a, b = ring_pt(s - h), ring_pt(s + h)
    dx, dz = b[0]-a[0], b[1]-a[1]
    L = math.hypot(dx, dz) or 1e-9
    return (dx/L, dz/L)

RING_COARSE = 20        # каждое N-е звено — грубая сетка поиска

def ring_s(px, pz):
    """Проекция точки на кривую: (длина по дуге, расстояние). Поиск в два
    захода — грубый по каждому двадцатому звену, точный в его окрестности:
    в кривой 3200 звеньев, а раскладка спрашивает её десятки тысяч раз."""
    pts, cum = RING["pts"], RING["cum"]
    n = len(pts)
    ci, cd = 0, 1e18
    for i in range(0, n, RING_COARSE):
        d = (px-pts[i][0])**2 + (pz-pts[i][1])**2
        if d < cd:
            ci, cd = i, d
    best = (1e18, 0.0)
    for k in range(ci - RING_COARSE, ci + RING_COARSE + 1):
        i = k % n
        a, b = pts[i], pts[(i+1) % n]
        vx, vz = b[0]-a[0], b[1]-a[1]
        L2 = vx*vx + vz*vz or 1e-9
        t = max(0.0, min(1.0, ((px-a[0])*vx + (pz-a[1])*vz) / L2))
        d = math.hypot(px - (a[0]+vx*t), pz - (a[1]+vz*t))
        if d < best[0]:
            best = (d, cum[i] + t*math.sqrt(L2))
    return best[1], best[0]

# --- КОЛЬЦО СТЕНЫ: ЦЕПЬ ГНУТЫХ ПРОГОНОВ ПО КРИВОЙ ЧЕРТЕЖА -------------------
# Прежняя раскладка (2207d8e) вела кольцо ПРЯМЫМИ city-wall12 по дуге ломаной:
# дыр и дублей она не оставляла, но каждый излом чертежа отдавала клином на
# лице кладки. Здесь кольцо ведётся ЦЕПЬЮ ГНУТЫХ ПРОГОНОВ по кривой.
# ЧТО НАДО ЗНАТЬ ПРО ГНУТЫЙ КУСОК (замер arc_kit по .dfh, а не паспорт):
# ось куска — ломаная его же стенок, ОПИСАННАЯ на касательных; концы лежат на
# хорде (0,0) и (chord,0), касательная у начала смотрит на +turn/2, у конца на
# -turn/2, а бугор — в локальный +Z. Отсюда правило посадки: хорда куска = его
# касательная, ДОВЁРНУТАЯ на половину поворота, а следующий кусок начинается
# ровно там, где кончился предыдущий, и с ЕГО касательной. Стык двух кусков с
# непрерывной касательной клина не даёт вовсе — это и есть лечение.
# Поворот у куска ОДНОГО ЗНАКА (бугор налево по ходу, поворот направо), а
# кольцо чертежа обходится по часовой в чарте (знаковая площадь -7417, все 14
# изломов отрицательные) — значит порядок вершин чертежа и есть тот, при
# котором кладка смотрит бугром НАРУЖУ. Проверяется прибором, а не верой.
# ЗАКРЫТИЕ ПРОГОНА. Цепь кладётся жадно, и последний кусок почти всегда
# перелетает конец прогона. Перелёт разносится РАВНЫМ НАХЛЁСТОМ по стыкам:
# следующий кусок начинается не в конце предыдущего, а на его же дуге за delta
# до конца — касательная там та же, значит стык остаётся без клина, а длина
# цепи садится на длину прогона. delta ищется тремя итерациями Ньютона.
WALL_ARC = "city-wall-arc"   # семейство кузницы: -arc{8,12,16}-s{000..200}
GATE_REC = "city-gate.dfh"
GATE_LEN = 12.0     # замер city-gate.dfh: пилоны 0..4 и 8..12, проезд 4..8
WALL_THICK = 1.20   # замер .dfh: толщина кладки — плечо клина на изломе
WALL_SINK = 0.30    # вкоп подошвы: кладка стоит в земле, а не на траве
RING_AXES = []      # ломаные осей ПОСТРОЕННОЙ кладки (заполняет wall_ring)
RING_OPENS = []     # створы ворот на дуге, (s0, s1)
_ARC = None

def arc_kit():
    """СЕМЕЙСТВО ГНУТЫХ ПРОГОНОВ, ЗАМЕРЕННОЕ ПО .dfh: файл, хорда, поворот,
    длина дуги. Ось куска — ломаная его стенок (height=6.00): первый отрезок
    задаёт касательную у начала, последний — у конца, разница между ними и
    есть то, что кусок съедает у кривой. Ни одно из этих чисел не выписано в
    таблицу: кузница перепекает семейство волнами, и переписанная цифра —
    будущая ложь (то же правило, что у recipe_box)."""
    global _ARC
    if _ARC is not None:
        return _ARC
    out = []
    for name in sorted(os.listdir(os.path.join(ROOT, "assets/houses"))):
        if not name.startswith(WALL_ARC) or not name.endswith(".dfh"):
            continue
        V, segs = {}, []
        for line in open(os.path.join(ROOT, "assets/houses", name),
                         encoding="utf-8"):
            t = line.split()
            if not t:
                continue
            if t[0] == "vertex":
                V[t[1]] = (float(t[3]), float(t[5]))
            elif t[0] == "surface" and "height=6.00" in line:
                vs = [v for v in t[2:] if v in V]
                if len(vs) == 2:
                    segs.append((V[vs[0]], V[vs[1]]))
        if not segs:
            continue
        a, b = segs[0][0], segs[-1][1]
        chord = math.hypot(b[0]-a[0], b[1]-a[1])
        tin = math.atan2(segs[0][1][1]-segs[0][0][1], segs[0][1][0]-segs[0][0][0])
        tout = math.atan2(segs[-1][1][1]-segs[-1][0][1],
                          segs[-1][1][0]-segs[-1][0][0])
        turn = math.degrees(tin - tout)
        # ДЛИНА ДУГИ СЧИТАЕТСЯ ОТ ХОРДЫ, А НЕ ОТ ЛОМАНОЙ. Ломаная ОПИСАНА на
        # касательных и потому длиннее дуги на ~1%: у arc12-s025 12.114 против
        # 12.014. Радиус, взятый по ломаной, уводит конец куска на 0.1 м от
        # хорды — а по хорде посадка сходится точно.
        if abs(turn) < 1e-6:
            R, arc = 0.0, chord
        else:
            R = chord / (2.0 * math.sin(math.radians(turn) / 2.0))
            arc = R * math.radians(turn)
        out.append({"rec": name, "chord": chord, "turn": turn, "R": R,
                    "A": arc})
    _ARC = sorted(out, key=lambda p: (p["chord"], p["turn"]))
    return _ARC

def _rot(v, deg):
    """Поворот в чарте (x,z) против часовой на deg."""
    c, s = math.cos(math.radians(deg)), math.sin(math.radians(deg))
    return (v[0]*c - v[1]*s, v[0]*s + v[1]*c)

def arc_step(P, T, pc, t):
    """Точка и касательная НА ДУГЕ куска на расстоянии t от его начала."""
    if abs(pc["turn"]) < 1e-6:
        return (P[0] + T[0]*t, P[1] + T[1]*t), T
    phi = pc["turn"] * t / pc["A"]
    right = (T[1], -T[0])
    cx, cz = P[0] + right[0]*pc["R"], P[1] + right[1]*pc["R"]
    v = _rot((P[0]-cx, P[1]-cz), -phi)
    return (cx + v[0], cz + v[1]), _rot(T, -phi)

def arc_yaw(T, pc):
    """yaw сцены для куска, начинающегося с касательной T: хорда — это T,
    довёрнутая на половину поворота (у рецепта касательная начала смотрит на
    +turn/2 от хорды)."""
    u = _rot(T, -pc["turn"] / 2.0)
    return math.degrees(math.atan2(-u[1], u[0])) % 360.0, u

def wall_ring():
    """Кольцо стены, башни и ворота. Возвращает (прогонов, башен, ворот)."""
    kit = arc_kit()
    TOT = RING["tot"]
    wall = PLAN["wall"]

    # 1. ВОРОТА САДЯТСЯ НА КРИВУЮ. Створ — интервал кривой, чья ХОРДА ровно в
    # габарит ворот: рецепт прямой, и если брать интервал длиной 12 м ПО ДУГЕ,
    # прямые ворота окажутся короче своего проёма на кривизну. Полудлина ищется
    # бисекцией по хорде.
    opens = []
    for g in PLAN["gates"]:
        sg, dg = ring_s(*g["pos"])
        lo, hi = GATE_LEN/2 - 0.5, GATE_LEN
        for _ in range(40):
            h = (lo + hi) / 2
            if math.dist(ring_pt(sg-h), ring_pt(sg+h)) < GATE_LEN:
                lo = h
            else:
                hi = h
        h = (lo + hi) / 2
        a, b = ring_pt(sg-h), ring_pt(sg+h)
        ux, uz = (b[0]-a[0])/GATE_LEN, (b[1]-a[1])/GATE_LEN
        yaw = math.degrees(math.atan2(-uz, ux)) % 360.0
        gs = [q for q in (ground(a[0]+ux*t, a[1]+uz*t)
                          for t in (0.0, GATE_LEN/2, GATE_LEN)) if q is not None]
        gy = (min(gs) - WALL_SINK) if gs else 25.0
        house(GATE_REC, a[0], gy + 0.20, a[1], yaw, f"ворота {g['name']}")
        opens.append((sg - h, sg + h))
        print(f"  ворота {g['name']}: на кривой ({ring_pt(sg)[0]:.2f},"
              f"{ring_pt(sg)[1]:.2f}), точка чертежа в {dg:.2f} м, "
              f"створ {2*h:.2f} м по дуге при хорде {GATE_LEN:.1f}")

    # 2. ПРОГОНЫ = КРИВАЯ МИНУС СТВОРЫ.
    opens.sort()
    runs = []
    for i, (o0, o1) in enumerate(opens):
        nxt = opens[(i+1) % len(opens)][0] + (TOT if i == len(opens)-1 else 0.0)
        if nxt - o1 > 1.0:
            runs.append((o1, nxt))

    # 3. ЦЕПЬ КУСКОВ — ЛУЧЕВОЙ ПОИСК, А НЕ ЖАДНЫЙ ВЫБОР. Жадность на кривизне
    # проигрывает вот почему: у куска кривизна ПОСТОЯННАЯ, а у кривой она
    # плывёт (медиана 0.96 гр/м, на вершине (110,60) — 3.7), и кусок, лучший
    # на своём месте, оставляет наследнику отход, который тому уже нечем
    # выбрать: цепь тангенциально непрерывна, а параллельный снос ею не
    # правится. Луч шириной BEAM держит несколько начал сразу и платит
    # СУММОЙ КВАДРАТОВ отхода — замер: наибольший отход 1.35 -> 0.59 м.
    BEAM, W_PIECE = 10, 0.30

    def lay(s0, s1, delta):
        """Цепь от s0 до s1 с нахлёстом delta на стыке. Возвращает
        (список (кусок, начало, касательная, s), длину закрытой дуги)."""
        states = [(0.0, s0, ring_pt(s0), ring_tan(s0), ())]
        done = []
        for _ in range(80):
            nxt = []
            for cost, s, P, T, ch in states:
                for pc in kit:
                    dev = 0.0
                    for k in range(1, 7):
                        q, _ = arc_step(P, T, pc, pc["A"]*k/6.0)
                        dev = max(dev, ring_s(*q)[1])
                    c = cost + dev*dev + W_PIECE
                    if s + pc["A"] >= s1:
                        # ПРОГОН ОБЯЗАН ДОЙТИ ДО СТВОРА. Цепь, которой не
                        # хватило полуметра, оставляет щель ровно у пилона
                        # ворот; перелёт же уходит ПОД пилон (тело 0..4) и не
                        # виден. Поэтому конец — только «дотянул или перелетел»,
                        # а перелёт стоит денег.
                        done.append((c + abs(s + pc["A"] - s1),
                                     s + pc["A"] - s0, ch + ((pc, P, T, s),)))
                    else:
                        P2, T2 = arc_step(P, T, pc, pc["A"] - delta)
                        nxt.append((c, s + pc["A"] - delta, P2, T2,
                                    ch + ((pc, P, T, s),)))
            nxt.sort(key=lambda x: x[0])
            states = nxt[:BEAM]
            if not states:
                break
        done.sort(key=lambda x: x[0])
        return list(done[0][2]), done[0][1]

    # 4. ЗАКРЫТИЕ ПРОГОНА: СНАЧАЛА СВЕС В ПИЛОН, ПОТОМ НАХЛЁСТ. Перелёт цепи
    # сперва отдаётся СВЕСУ — цепь целиком сдвигается на shift назад, и её
    # концы одинаково заходят под пилоны обоих ворот (тело пилона 4 м, проезд
    # 4..8 — свес до 2 м арку не задевает). Что не влезло в свес, разносится
    # РАВНЫМ НАХЛЁСТОМ: следующий кусок начинается на дуге предыдущего за
    # delta до его конца, касательная там та же — стык остаётся без клина.
    # Порядок обязателен: нахлёст ставит две коробки кладки в одну плоскость,
    # свес не ставит ничего.
    WALL_SHIFT_MAX = 2.0

    placed, n_wall, closure = [], 0, 0.0
    for (s0, s1) in runs:
        need = s1 - s0
        chain, got = lay(s0, s1, 0.0)
        over = got - need
        shift = max(0.0, min(WALL_SHIFT_MAX, over/2))
        delta = max(0.0, (over - 2*shift) / max(1, len(chain) - 1))
        best = None
        for _ in range(4):
            chain, got = lay(s0 - shift, s1 + shift, delta)
            n = len(chain)
            resid = got - (need + 2*shift)
            if best is None or abs(resid) < abs(best[0]):
                best = (resid, chain, shift, delta)
            if abs(resid) < 0.05:
                break
            ns = max(0.0, min(WALL_SHIFT_MAX, shift + resid/2))
            delta = max(0.0, delta + 0.8*(resid - 2*(ns - shift)) / max(1, n-1))
            shift = ns
        resid, chain, shift, delta = best
        closure = max(closure, abs(resid))
        print(f"  прогон {s0:.1f}..{s1:.1f} ({need:.1f} м): {len(chain)} кусков, "
              f"свес {shift:.2f} м, нахлёст {delta:.2f} м, невязка {resid:+.2f} м")
        for pc, P, T, _s in chain:
            yaw, u = arc_yaw(T, pc)
            gs = [q for q in (ground(*arc_step(P, T, pc, pc["A"]*k/2.0)[0])
                              for k in (0, 1, 2)) if q is not None]
            gy = (min(gs) - WALL_SINK) if gs else 25.0
            house(pc["rec"], P[0], gy, P[1], yaw, "стена кольца")
            placed.append({"pc": pc, "P": P, "T": T, "yaw": yaw,
                           "run": len(runs) and (s0, s1)})
            n_wall += 1

    # 3. БАШНИ — по вершинам чертежа, выдвинуты наружу по нормали от центра.
    ccx = sum(p[0] for p in wall) / len(wall)
    ccz = sum(p[1] for p in wall) / len(wall)
    n_tower = 0
    for tx, tz in PLAN["towers"]:
        ang = math.degrees(math.atan2(tz-ccz, tx-ccx))
        nx, nz = tx-ccx, tz-ccz
        nl = math.hypot(nx, nz)
        px, pz = tx + nx/nl*1.5, tz + nz/nl*1.5
        g = ground(px, pz)
        house("city-tower.dfh", px - 1.8, (25.0 if g is None else g - 0.2),
              pz - 1.8, (ang + 90) % 360, "башня кольца (наружу)")
        n_tower += 1

    # 4. ПРИЁМКА КОЛЬЦА, четыре меры и все по построенному, а не по замыслу:
    #   * НЕПОКРЫТАЯ ДУГА: проба каждые 0.25 м спрашивает, лежит ли она в теле
    #     кладки (WALL_THICK/2 от оси куска) или в створе ворот;
    #   * ИЗЛОМ НА СТЫКЕ и клин на лице — та же мера, какой мерена прямая
    #     раскладка по сцене (клин = толщина*tg(излом/2));
    #   * ОТХОД ОСИ от кривой чертежа — цена цепи: куски садятся друг от друга,
    #     и ошибка подгонки копится внутри прогона;
    #   * ЛИЦОМ НАРУЖУ: бугор куска обязан смотреть от центра кольца.
    axes = []
    for it in placed:
        pc, P, T = it["pc"], it["P"], it["T"]
        n = max(2, int(pc["A"] / 0.20))
        axes.append([arc_step(P, T, pc, pc["A"]*k/n)[0] for k in range(n+1)])
    # ОСИ ПОСТРОЕННОЙ КЛАДКИ ОТДАЮТСЯ ПРИЁМКЕ ТЕЛ (check_ring_bodies). Мерить
    # дома до КРИВОЙ чертежа нельзя: цепь кусков отходит от неё до 0.6 м, и
    # дом, чистый по кривой, режется настоящей кладкой.
    RING_AXES[:] = axes
    RING_OPENS[:] = list(opens)
    # ДЫРА МЕРИТСЯ ЛУЧОМ ИЗ ЦЕНТРА, А НЕ ПРОБОЙ НА КРИВОЙ ЧЕРТЕЖА (правка
    # 23.08, и это исправление МЕРЫ, а не смягчение порога).
    # Прежняя проба шла по кривой чертежа и спрашивала, лежит ли точка кривой
    # в теле кладки. Пока цепь держалась чертежа, ответ совпадал с искомым; но
    # цепь кусков ходит от кривой в обе стороны — на этом чертеже до 0.68 м
    # при полтолщине 0.60, — и стоило северной грани лечь на кромку замкового
    # плато, как прибор объявил «непокрытая дуга 4.75 м» ТАМ, ГДЕ КЛАДКА
    # СПЛОШНАЯ: он мерил не дыру, а отход. Отход у нас уже меряется отдельным
    # числом (dev), и мерить его дважды — значит потерять единственное число
    # про дыру. Настоящий вопрос: «есть ли направление, в котором из города
    # выходят, не пересекая ни кладки, ни створа ворот». Это луч из центра
    # кольца: каждый кусок закрывает УГЛОВОЙ интервал, ворота — свой, дыра —
    # непокрытый остаток окружности, переведённый в метры по среднему радиусу.
    # Мера не зависит от того, где именно легла цепь, — только от того,
    # сплошная ли она; ровно этот вопрос и задавался с самого начала.
    ccx0 = sum(p[0] for p in wall) / len(wall)
    ccz0 = sum(p[1] for p in wall) / len(wall)

    def _span(pts):
        """Угловой интервал набора точек из центра кольца, развёрнутый так,
        что он не рвётся на стыке ±pi."""
        a0 = math.atan2(pts[0][1]-ccz0, pts[0][0]-ccx0)
        lo = hi = 0.0
        for px, pz in pts[1:]:
            da = math.atan2(pz-ccz0, px-ccx0) - a0
            da = (da + math.pi) % (2*math.pi) - math.pi
            lo, hi = min(lo, da), max(hi, da)
        return a0 + lo, a0 + hi

    # КОНТРОЛЬНАЯ РУКА ИЗ ТОГО ЖЕ БИНАРНИКА (правило 30): прибор, который
    # только проходит, ничего не доказывает. WHITERUN_WALL_HOLE=<номер>
    # ВЫНИМАЕТ один кусок из МЕРЫ (не из сцены) — метрика обязана назвать
    # дыру в его длину. Замер 23.08: без двери 0.00 м, с WALL_HOLE=5 — 9.94 м.
    hole = env("WALL_HOLE")
    covered = []
    for i, ax in enumerate(axes):
        if hole is not None and i == int(hole):
            continue
        covered.append(_span(ax))
    for (o0, o1) in opens:
        covered.append(_span([ring_pt(o0 + (o1-o0)*k/8.0) for k in range(9)]))
    # ДЫРА, КОТОРУЮ НЕ ВИДНО В ГРАДУСАХ, НЕ ДЫРА: перекрытие в полградуса на
    # среднем радиусе 52 м — это полметра, и цепь смыкается плотнее.
    R_MEAN = TOT / (2*math.pi)
    TAU = 2*math.pi
    events = []
    for a, b in covered:
        L = b - a
        a %= TAU
        if a + L > TAU:                  # интервал через ноль — режем надвое
            events.append((a, TAU))
            events.append((0.0, a + L - TAU))
        else:
            events.append((a, a + L))
    events.sort()
    def _at(ang):
        return (ccx0 + math.cos(ang)*R_MEAN, ccz0 + math.sin(ang)*R_MEAN)
    worst, cur_end = (0.0, 0.0, 0.0), 0.0
    for a, b in events:
        if a > cur_end and (a - cur_end) * R_MEAN > worst[0]:
            worst = ((a - cur_end) * R_MEAN,) + _at((cur_end + a) / 2)
        cur_end = max(cur_end, b)
    if (TAU - cur_end) * R_MEAN > worst[0]:
        worst = ((TAU - cur_end) * R_MEAN,) + _at((cur_end + TAU) / 2)
    dev = max(max(ring_s(*w)[1] for w in ax) for ax in axes)
    kinks = []
    for i, it in enumerate(placed):
        nx = placed[(i+1) % len(placed)]
        if nx["run"] != it["run"]:
            continue                     # разрыв под ворота — не стык
        end, Tend = arc_step(it["P"], it["T"], it["pc"], it["pc"]["A"])
        dth = abs((math.degrees(math.atan2(nx["T"][1], nx["T"][0])
                                - math.atan2(Tend[1], Tend[0])) + 180)
                  % 360 - 180)
        kinks.append(dth)
    out_ok = 0
    for it in placed:
        _, u = arc_yaw(it["T"], it["pc"])
        bulge = (-u[1], u[0])
        mid, _ = arc_step(it["P"], it["T"], it["pc"], it["pc"]["A"]/2)
        if bulge[0]*(mid[0]-ccx) + bulge[1]*(mid[1]-ccz) > 0:
            out_ok += 1
    worst_kink = max(kinks) if kinks else 0.0
    used = {}
    for it in placed:
        used[it["pc"]["rec"]] = used.get(it["pc"]["rec"], 0) + 1
    print(f"кольцо стены: {n_wall} гнутых прогонов, {n_tower} башен, "
          f"{len(opens)} проёмов по {GATE_LEN:.1f} м; кривая {TOT:.1f} м, "
          f"наибольшая непокрытая дуга {worst[0]:.2f} м"
          + (f" у ({worst[1]:.1f},{worst[2]:.1f})" if worst[0] > 0.005 else "")
          + f", отход оси от кривой {dev:.2f} м, невязка закрытия {closure:.2f} м")
    print(f"  стыки: изломов {len(kinks)}, наибольший {worst_kink:.3f} гр. "
          f"(клин на лице {WALL_THICK*math.tan(math.radians(worst_kink)/2):.3f} м); "
          f"бугром наружу {out_ok} из {n_wall}")
    print("  раскладка: " + ", ".join(f"{k.replace('city-wall-arc','arc').replace('.dfh','')}x{v}"
                                      for k, v in sorted(used.items())))
    return n_wall, n_tower, len(opens)

# --- ПОЛОТНО НЕ ЛЕЗЕТ В КЛАДКУ (претензия владельца 23.08: «некоторые тропы
# проходят сквозь стену — глупо») ------------------------------------------
# Полотно путевого атласа рисуется САМОЙ ЗЕМЛЁЙ полосой half+soft от осевой, и
# земля под кладкой ничем не отличается от земли перед ней: дорожка, чей конец
# лёг у стены, продолжается тёсаным камнем ПОД стеной и вылезает снаружи.
# Проходить кольцо полотну положено только в створе ворот — там для того и
# проём. Замер (пробы вдоль всего кольца шагом 0.5 м, 641 проба): полотно вне
# створа находилось у 6 проб, все — одна дорожка от двери у северной стены.
RING_CLEAR = 1.0   # ближе этого к осевой стены полотна нет (порог владельца)
GATE_SPAN = 9.0    # створ ворот: половина габарита плюс щёки

def ring_dist(px, pz):
    """Расстояние до осевой кольца стены. Меряется до КРИВОЙ, по которой
    кладка и ведётся, а не до ломаной чертежа: между ними до 1.4 м, и на
    вершинах ломаная лежит ВНУТРИ кладки соседних кусков."""
    return ring_s(px, pz)[1]

def in_gate(px, pz):
    return any(math.hypot(px-g["pos"][0], pz-g["pos"][1]) < GATE_SPAN
               for g in PLAN["gates"])

def clip_walk(x0, z0, x1, z1, band):
    """Дорожка укорачивается ДО ПЕРВОЙ ПРОБЫ, у которой её полоса дотягивается
    до кладки — с ОБОИХ концов.
    БЛИЖНИЙ КОНЕЦ ТОЖЕ РЕЖЕТСЯ, и это правка 24.08. Здесь стояло «ближний
    конец — крыльцо, его не трогаем: дом стоит там, где стоит», и это было
    верно ровно до тех пор, пока ни один дом не стоял ВПЛОТНУЮ к кольцу. С
    новым свесом соломенной кровли (0.35 -> 0.55) габариты жилья выросли,
    расстановка сдвинулась, и один дом сел у самой стены: его дорожка выходила
    из-под кладки, то есть ровно тот дефект [B], ради которого весь этот клип и
    написан (приёмка check_ring_fabric честно поймала: 0 проб -> 1 из 641).
    Довод «дом стоит там, где стоит» отвечает на другой вопрос: он про то,
    можно ли двигать ДОМ, а не про то, обязана ли МОСТОВАЯ доходить до его
    порога. Не обязана — у дома в стене вход с улицы, а не с обхода стены."""
    L = math.hypot(x1-x0, z1-z0)
    if L < 1e-6:
        return None
    n = max(2, int(L / 0.25))
    lo, hi = 0.0, 1.0
    reach = (band + RING_CLEAR) / L
    for i in range(n + 1):
        t = i / n
        px, pz = x0 + (x1-x0)*t, z0 + (z1-z0)*t
        if ring_dist(px, pz) <= band + RING_CLEAR and not in_gate(px, pz):
            hi = max(0.0, t - reach)
            break
    for i in range(n, -1, -1):
        t = i / n
        px, pz = x0 + (x1-x0)*t, z0 + (z1-z0)*t
        if ring_dist(px, pz) <= band + RING_CLEAR and not in_gate(px, pz):
            lo = min(1.0, t + reach)
            break
    if lo <= 0.001 and hi >= 0.999:
        return (x0, z0, x1, z1)
    if (hi - lo) * L < 0.8:
        return None        # от дорожки остался огрызок — её просто нет
    return (x0 + (x1-x0)*lo, z0 + (z1-z0)*lo,
            x0 + (x1-x0)*hi, z0 + (z1-z0)*hi)

# =============================================================================
# ЗЕМЛЯ ГОРОДА ПИШЕТСЯ КЛАССАМИ (заказ архитектора З1, 24.08)
# =============================================================================
# ПРЕТЕНЗИЯ: газон #4c6e27..#647e29, насыщенность 0.59-0.67 — цвет бильярдного
# сукна; разброс яркости по крупным участкам 6.7-9.6 из 255; и главное — земля
# ВНУТРИ стен ровно та же, что снаружи. Город, в который двести лет ходят
# люди, не может иметь внутри такую же землю, как чистое поле.
#
# ПОЧЕМУ ЭТО ЛЕЧИТСЯ ЗДЕСЬ, А НЕ ТИНТОМ. dfn_ground.sh нормирует тинт по люме
# к единице — «оттенок гуляет свободно, ЯРКОСТЬ не двигается вовсе», и это
# принятое решение, а не баг (прежняя пятнистость рисовала 60-метровые бурые
# разводы). Значит разброса яркости из тинта НЕ БУДЕТ НИ ПРИ КАКОЙ ДОЗЕ, и
# взяться ему неоткуда, кроме КЛАССА ПОВЕРХНОСТИ. А класс пишет город.
#
# ИНСТРУМЕНТ БЫЛ И НЕ ИСПОЛЬЗОВАЛСЯ: формат .relief понимает строку
# «mat <x> <z> <класс>» на решётке 1 м (ReliefLayer.cpp), классы grass / blend
# / rock / sand / waterbed дают РАЗНЫЕ клетки атласа, а не подкраску одной.
# Генератор Вайтрана не писал НИ ОДНОЙ такой строки.
#
# ТРИ СЛОЯ, И ВСЕ ТОЛЬКО ВНУТРИ КОЛЬЦА. Разница «город/поле» и есть половина
# смысла: распиши классами всё — и она пропадёт.
#   1. ВЫТОПТАННЫЙ ГРУНТ — размытый ОРЕОЛ вокруг занятых мест (пороги, ворота,
#      колодец, лотки, подножие Гилдергрина, полоса вдоль кладки), а не вторая
#      тропа: у порога чистый грунт, через 2 м смесь, через 5 м уже трава.
#   2. КАМЕНЬ НА ПОВЕРХНОСТИ и 3. СУХИЕ ПОДПАЛИНЫ — ОТКАЗАНО ПО КАДРУ, и это
#      надо записать, потому что заказаны они были оба. Оба слоя были написаны,
#      прогнаны и СНЯТЫ ПОСЛЕ ПРИЁМКИ С УРОВНЯ ГЛАЗ: сверху они дают ровно то,
#      что заказано (разброс яркости по участку внутри стен 4.85 -> 13.66 при
#      контрольной руке — нетронутой земле за кольцом), а вблизи класс на
#      решётке 1 м рисуется ПЛОСКИМ ПЯТНОМ С ЖЁСТКИМ КОНТУРОМ: перед камерой
#      лежала серая амёба в шесть метров с обводкой. Это не настройка порога —
#      мельче пятно, чем клетка, не бывает, а обводку рисует шейдер земли.
#      Разброс с воздуха не стоит того, чтобы у ног игрока лежала клякса;
#      кадр отдан архитектору вместе с числом.
#      ОСТАВЛЕН ТОЛЬКО ОРЕОЛ, и по причине, а не из осторожности: он привязан
#      к ПРЕДМЕТАМ (порог, ворота, колодец, кладка), и пятно у порога читается
#      вытоптанной землёй — тем, чем и является, — а не кляксой посреди луга.
# ГРАНИЦЫ РАЗМЫВАЮТСЯ, А НЕ РЕЖУТСЯ ОКРУЖНОСТЬЮ: у края пятна заполнение
# вероятностное, и вероятность — ДЕТЕРМИНИРОВАННЫЙ ХЭШ от (x, z), никакого
# random(): файл обязан собираться побайтово одинаково два раза подряд.
GROUND_MAT = []      # (gx, gz, имя класса)

def _gh(x, z, salt):
    """Хэш клетки в [0,1). Тот же приём, что у дрожи огня: две сборки одной
    руки дают побайтово одну сцену."""
    v = math.sin(x * 127.1 + z * 311.7 + salt * 74.7) * 43758.5453
    return v - math.floor(v)

def _gnoise(x, z, cell, salt):
    """Гладкий шум значением по решётке cell метров (билинейно, smoothstep)."""
    fx, fz = x / cell, z / cell
    ix, iz = math.floor(fx), math.floor(fz)
    tx, tz = fx - ix, fz - iz
    tx = tx * tx * (3.0 - 2.0 * tx)
    tz = tz * tz * (3.0 - 2.0 * tz)
    a = _gh(ix, iz, salt)
    b = _gh(ix + 1, iz, salt)
    c = _gh(ix, iz + 1, salt)
    d = _gh(ix + 1, iz + 1, salt)
    return (a * (1 - tx) + b * tx) * (1 - tz) + (c * (1 - tx) + d * tx) * tz

def paint_ground(Hh):
    """Три слоя классов по решётке 1 м, только внутри кольца стен."""
    # ТОЧКИ ПРИТЯЖЕНИЯ — из чертежа и из расстановки, а не выдуманные: ворота,
    # ядра МЕСТ (каждое объявляет свой ореол само) и подножия крылец.
    spots = [(g["pos"][0], g["pos"][1], GROUND_GATE_R) for g in PLAN["gates"]]
    spots += [h for h in (place_halo(pl) for pl in PLACES) if h is not None]
    for (_k, _dx, _dz, fx, fz, _n) in STOOPS:
        spots.append((fx, fz, GROUND_STOOP_R))
    for (fx, fz) in STOOP_FOOT:
        spots.append((fx, fz, GROUND_STOOP_R))
    n_dirt = n_blend = n_rock = n_in = 0
    for gz in range(SPAN):
        for gx in range(SPAN):
            if not point_in_poly(gx, gz, PLAN["wall"]):
                continue
            n_in += 1
            # (1) ОРЕОЛ ВЫТОПТАННОГО. Ближайшая точка притяжения решает; её
            # собственный радиус — ядро чистого грунта, дальше кайма смеси.
            near = min((math.hypot(gx-sx, gz-sz) - sr for sx, sz, sr in spots),
                       default=1e9)
            # ...плюс полоса вдоль кладки: у стены ходят вдоль, а не поперёк.
            near = min(near, abs(ring_dist(gx, gz) - GROUND_WALL_BAND[0])
                       - GROUND_WALL_BAND[1])
            cls = None
            if near <= 0.0:
                cls = GROUND_CORE_CLS                 # чистый грунт у порога
            elif near <= GROUND_FADE_M:
                # размытый край: чем дальше, тем реже
                if _gh(gx, gz, 3.0) > near / GROUND_FADE_M * GROUND_EDGE_P:
                    cls = GROUND_EDGE_CLS
            if cls is None:
                continue
            GROUND_MAT.append((gx, gz, cls))
            n_dirt += 1 if cls == GROUND_CORE_CLS else 0
            n_blend += 1 if cls == GROUND_EDGE_CLS else 0
            n_rock += 1 if cls == "rock" else 0
    tot = max(1, n_in)
    print(f"ЗЕМЛЯ ГОРОДА КЛАССАМИ: {n_in} клеток внутри кольца; "
          f"грунт {n_dirt} ({100.0*n_dirt/tot:.0f}%), "
          f"смесь {n_blend} ({100.0*n_blend/tot:.0f}%), "
          f"камень {n_rock} ({100.0*n_rock/tot:.0f}%); "
          f"снаружи не тронуто ни одной")
    return len(GROUND_MAT)

def check_ring_fabric(bands):
    """Приёмка владельца: пробы вдоль кольца — нет полотна в 1 м от осевой
    стены вне створа ворот. bands: [(ломаная, полуширина, мягкость)].
    ПРОБЫ ИДУТ ПО КРИВОЙ, А НЕ ПО ЛОМАНОЙ ЧЕРТЕЖА (правка 24.08). Кладка с
    18.08 ведётся гнутыми прогонами по центростремительной кривой, и та
    отходит от ломаной до 1.86 м; clip_walk с того же дня режет дорожки по
    КРИВОЙ (ring_dist). Пока прибор щупал ломаную, он спрашивал про место, где
    кладки местами нет: одна и та же дорожка объявлялась и обрезанной, и
    сквозной — двумя мерами одного предмета. Одна линия на обе стороны."""
    tot, bad, where = 0, 0, None
    step = 0.5
    for k in range(int(RING["tot"] / step) + 1):
        px, pz = ring_pt(k * step)
        tot += 1
        if in_gate(px, pz):
            continue
        for pts, half, soft in bands:
            if len(pts) < 2:
                continue
            d = 1e9
            for (u0, v0), (u1, v1) in zip(pts, pts[1:]):
                vx, vz = u1-u0, v1-v0
                L2 = vx*vx + vz*vz or 1e-9
                tt = max(0.0, min(1.0, ((px-u0)*vx + (pz-v0)*vz) / L2))
                d = min(d, math.hypot(px - (u0+vx*tt), pz - (v0+vz*tt)))
            if d <= half + soft:
                bad += 1
                where = (px, pz)
                break
    print(f"ПОЛОТНО У СТЕНЫ: {tot} проб по кольцу, вне створа ворот полотно "
          f"нашлось у {bad}"
          + (f" (напр. {where[0]:.1f},{where[1]:.1f}) — СКВОЗЬ КЛАДКУ" if bad else ""))
    return bad

# =============================================================================
# ЗАПИСЬ ВЫПУСКА
# =============================================================================
# ТРИ ФАЙЛА — ТРИ ФУНКЦИИ, И ЭТО НЕ КОСМЕТИКА. Запись сцены стояла хвостом
# main() одним open().write(), то есть выпуск был ОДИН ПО УСТРОЙСТВУ. Зона И15
# («интерьеры-локации как в Skyrim») просит писать пачку: экстерьер плюс по
# сцене на каждый вход; функция, которую можно позвать N+1 раз, — это ровно то
# место, куда она встанет, и стоит она сегодня ничего.

def city_header():
    """Шапка ГОРОДСКОЙ сцены: карта, размер мира, рельеф, спавн, воздух."""
    return list(CITY.SCENE_HEADER) + [
        f"map = {CITY.MAP_ZONE}/{OUT}",
        f"world_span_m = {SPAN}",
        f"relief = {OUT}.relief",
        f"spawn = {CITY.SPAWN[0]} {CITY.SPAWN[1]} {CITY.SPAWN[2]}",
        f"spawn_yaw = {CITY.SPAWN_YAW}", "",
        "[air]"] + [f"{k} = {v}" for k, v in CITY.AIR] + [""]

def write_scene(rel_path, header, terrain, places, houses, lights):
    """Сцена: готовая ШАПКА, terrain-блоки, [place], [house], [light].

    ШАПКА — ПАРАМЕТР, А НЕ СОБСТВЕННОСТЬ ЭТОЙ ФУНКЦИИ, и просьба epoch-i15
    (зона И15, интерьеры-локации) назвала причину точно: у интерьерной сцены
    шапка ДРУГАЯ по составу, а не по значениям — нет relief, нет размера мира
    города, свой [air] и несколько [spawn]. Функция, которая печатает шапку
    сама, годна ровно для одного вида сцен; ниже неё всё тело — общее, и
    делить его копией было бы хуже, чем передать десять строк параметром.
    Город зовёт city_header(), интерьер построит свою."""
    out = list(header)
    out.append("\n".join(terrain))
    for obj, x, y, z, yaw, note, sc in places:
        out += ["[place]", f"object = {obj}",
                f"pos = {x:.3f} {y:.3f} {z:.3f}", f"yaw = {yaw:.6f}",
                f"scale = {sc:g}"]
        if note:
            out += [f"note = {note}"]
        out += [""]
    for file, x, y, z, yaw, note in houses:
        out += ["[house]", f"file = {file}",
                f"pos = {x:.3f} {y:.3f} {z:.3f}", f"yaw = {yaw:.6f}",
                f"note = {note}", ""]
    # СВЕТ ОЧАГОВ. Рендер зажигает восемь ближайших ([light] — не объект),
    # тени просит только тот, кому они по сюжету (слотов два).
    for x, y, z, col, rad, shadow, note, inter, room, soft, flick in lights:
        out += ["[light]", f"pos = {x:.3f} {y:.3f} {z:.3f}",
                f"color = {col[0]:.3f} {col[1]:.3f} {col[2]:.3f}",
                f"radius_m = {rad:.2f}",
                f"casts_shadow = {1 if shadow else 0}"]
        if inter:
            out += ["interior = 1"]
        if room:
            out += [f"room = {room[0]:.3f} {room[1]:.3f} "
                    f"{room[2]:.3f} {room[3]:.3f}"]
        if soft > 0.0:
            out += [f"softness = {soft:g}"]
        if flick > 0.0:
            out += [f"flicker = {flick:.2f}"]
        out += [f"note = {note}", ""]
    open(os.path.join(ROOT, rel_path), "w",
         encoding="utf-8").write("\n".join(out))
    return len(out)

def write_relief(rel_path, Hh, relief_paths):
    """Рельеф: дельты от НАТУРАЛЬНОЙ земли, классы земли, тропы."""
    rel = [CITY.RELIEF_HEADER, "step 1"]
    if env("BARE") != "1" and os.path.exists(NATURAL_PATH):
        nat = [[float(v) for v in line.split()]
               for line in open(NATURAL_PATH, encoding="utf-8")
               if not line.startswith("#")]
        for gz in range(SPAN):
            for gx in range(SPAN):
                dh = (Hh[gz][gx] - nat[gz][gx]) * river_taper(gx, gz)
                if abs(dh) > 0.05:
                    rel.append(f"dh {gx} {gz} {dh:.2f}")
    for gx, gz, cls in GROUND_MAT:
        rel.append(f"mat {gx} {gz} {cls}")
    rel += relief_paths
    open(os.path.join(ROOT, rel_path), "w",
         encoding="utf-8").write("\n".join(rel) + "\n")

def write_map(rel_path):
    """Манифест карты. Все строки — из паспорта; built_commit ставит сборка."""
    open(os.path.join(ROOT, rel_path), "w", encoding="utf-8").write(
        f"name = {CITY.MAP_TITLE}\n"
        f"zone = {CITY.MAP_ZONE}\nsize_chunks = {SIZE_CHUNKS}\n"
        f"{CITY.MAP_NOTE}\n"
        f"source = {CITY.MAP_SOURCE}\n"
        f"scene = assets/scenes/{OUT}.scene\n"
        f"objects = {CITY.MAP_OBJECTS}\n"
        f"description = {CITY.MAP_DESC}\n"
        "built_commit =\n")

# =============================================================================
# СТАДИИ КОНВЕЙЕРА
# =============================================================================
# main() ниже — ОРКЕСТРАТОР, и это не косметика. Он был на семьсот строк, и в
# них лежало вперемешку три разных предмета: очерёдность (что после чего),
# устройство отдельных стадий (как именно садится мост) и данные города (какие
# именно узлы улицы держат огонь). Разделить их пришлось ради второго города,
# но окупилось раньше: очерёдность — ЕДИНСТВЕННОЕ, что в этом файле нельзя
# прочитать по месту, потому что она нигде не записана, кроме порядка строк.

def bridge_setup(WLEV):
    """Рама моста и отметка его origin.
    ИМЕНА РАМЫ МОСТА — СВОИ. Прежде рама распаковывалась в mx, mz, ux, uz, а
    ниже по main() те же mx, mz получали прямоугольник РЫНКА. Приёмка посадки,
    написанная в конце, честно мерила землю у рынка и объявляла аппарели
    утопленными на три метра. Одно имя на два предмета — та же болезнь, что
    половина дефектов этого города: мера, приложенная не к своему."""
    (box, boz), (bmx, bmz), (bux, buz), yaw = bridge_frame()
    # МОСТ СТОИТ НА ВОДЕ, А НЕ НА БЕРЕГУ. Отметка бралась с земли в 7 м к
    # востоку — на дамбе берега, и настил уезжал от русла. Настил рецепта
    # лежит на +0.20..+0.35 от origin, аппарели спускаются к -0.50, быки
    # уходят на -2.20: origin на 1.05 над водой даёт проезжую часть в 1.25-1.40
    # м над плёсом, торцы аппарелей — на планированную кромку (вода+0.50),
    # быки — на 0.15 в дно.
    oy = water_at(WLEV, bmx + bux*4.0, bmz + buz*4.0) + 1.05
    return {"o": (box, boz), "mid": (bmx, bmz), "u": (bux, buz),
            "yaw": yaw, "oy": oy}

# ТОЧКИ СХОДА НАСТИЛА НА БЕРЕГ, локальные x рецепта. У арки полупролёт 12.62 м,
# а от наружной грани кольца до западной кромки воды всего 4.7 м: западная
# аппарель физически НЕ МОЖЕТ приземлиться за стеной — её торец лежит в теле
# городского шельфа, у самых Восточных ворот. Землю к торцу тут не доведёшь:
# пришлось бы срезать шельф на 1.9 м ровно под кладкой и воротами. Поэтому
# подход доводится не к торцу, а к ТОЧКЕ СХОДА — тому месту настила, где он
# выходит из берега; всё, что западнее, остаётся В НАСЫПИ, как у всякого
# каменного моста, упирающегося в склон.
BRIDGE_LAND = (-2.4, 10.4)
BRIDGE_TIP = (-8.623, 16.623)   # торцы ходибельной поверхности (замер рецепта)
BRIDGE_RUN = 10.6               # длина спланированного подхода за точкой схода

def grade_bridge(Hh, br):
    """ЗЕМЛЯ ПОДХОДОВ ДОВОДИТСЯ К ТОЧКАМ СХОДА. Рецепт наклона не умеет —
    настил кладётся горизонтально, а сходятся с ним берега. Отметка у схода =
    ровно верх настила, а не «вода + полметра»: прежняя формула ставила землю
    на 0.15 ниже НАМЕРЕННО, и это было бы терпимо, если бы держалось.
    Полоса 4 м (ширина тракта).
    РУСЛО МЕЖДУ АППАРЕЛЯМИ НЕ ПЛАНИРУЕТСЯ. Прежний коридор шёл ОДНОЙ ломаной
    от берега до берега с обоими торцами на отметке аппарели — и заодно
    засыпал реку землёй на уровне настила. Бот честно переходил реку ПО ЭТОЙ
    НАСЫПИ, рядом с мостом, а не по нему (замер: шёл на y=25.30 при верхе
    настила 26.00), и утыкался в парапет с внутренней стороны.
    РУСЛО ЗАЩИЩАЕТСЯ КОРОТКОЙ КАЙМОЙ, А НЕ ПРЯМОУГОЛЬНИКОМ. Осевая коробка
    вокруг воды при развороте моста на 25 градусов задевала западный торец
    (кромка уезжала на 0.6-0.9 м), а сделать её меньше нельзя — она обязана
    накрыть всю ширину воды. Вместо неё коротка кайма самих коридоров: 2.5
    вместо 6.0. Коридор перестаёт дотягиваться до середины пролёта, а то, что
    всё же попадает в русло, гасит river_taper — тем же smoothstep, каким
    движок сводит дно с берегом."""
    (bmx, bmz), (bux, buz), oy = br["mid"], br["u"], br["oy"]
    for t0, t1 in ((BRIDGE_LAND[0] - BRIDGE_RUN, BRIDGE_LAND[0]),
                   (BRIDGE_LAND[1], BRIDGE_LAND[1] + BRIDGE_RUN)):
        nodes = []
        for t, h in ((t0, None if t0 < 0 else oy + deck_top(t0)),
                     (t1, oy + deck_top(t1) if t1 < 0 else None)):
            px, pz = bmx + bux*t, bmz + buz*t
            nodes.append((px, pz, hh_at(Hh, px, pz) if h is None else h))
        grade_corridor(Hh, nodes, 4.0, 2.5)

def put_bridge(Hh, br):
    """Настил на воду плюс приёмка посадки обоих концов."""
    house(BRIDGE_REC, br["o"][0], br["oy"], br["o"][1], br["yaw"],
          "мост-арка через реку")
    (bmx, bmz), (bux, buz), oy = br["mid"], br["u"], br["oy"]
    for t, nm in zip(BRIDGE_LAND, ("западная", "восточная")):
        px, pz = bmx + bux*t, bmz + buz*t
        d = (oy + deck_top(t)) - hh_at(Hh, px, pz)
        print(f"  мост, {nm} точка схода (t={t:+.1f}, настил "
              f"{oy + deck_top(t):.2f}): кромка {d:+.3f} м над полотном"
              + ("" if abs(d) <= 0.05 else "  — ВЫШЕ ДОПУСКА 0.05"))
    for t, nm in zip(BRIDGE_TIP, ("западный", "восточный")):
        px, pz = bmx + bux*t, bmz + buz*t
        d = hh_at(Hh, px, pz) - (oy + deck_top(t))
        print(f"  мост, {nm} торец аппарели: земля на {d:+.2f} м над полотном"
              f" (в насыпи)" if d > 0 else
              f"  мост, {nm} торец аппарели: ОТКРЫТ, земля на {d:+.2f} м")

BIG_HOUSE_M = 10.0   # крупнее этого — площадку режем, на ровное пятно не сядет

def grade_big_pads(Hh, FR):
    """ПЛОЩАДКИ ПОД КРУПНЫЕ ЗДАНИЯ. Посадка по минимуму пятна честна только
    там, где пятно помещается на ровное: у замка 26.6х14, Йоррваскра 16х8,
    храма 12х10 и амбаров 12х9 пятно перелезает кромку террасы, и минимум
    утягивал здание на нижнюю ступень. Дом такого размера в жизни встаёт на
    СПЛАНИРОВАННУЮ площадку — её и режем в поле высот по медиане пятна."""
    for f in FR:
        ccx, ccz, w, d, yaw = f["x"], f["z"], f["w"], f["d"], f["yaw"]
        if max(w, d) < BIG_HOUSE_M:
            continue
        pts = rect_points(ccx, ccz, w, d, yaw, n=7)
        hs_lvl = sorted(hh_at(Hh, px, pz) for px, pz in pts)[len(pts)//2]
        c = math.cos(math.radians(yaw))
        sn = math.sin(math.radians(yaw))
        # коридор по длинной оси пятна, halfw = половина короткой стороны
        ax, az = (c, -sn) if w >= d else (sn, c)
        half_long = max(w, d)/2
        halfw = min(w, d)/2
        grade_corridor(Hh, [(ccx - ax*half_long, ccz - az*half_long, hs_lvl),
                            (ccx + ax*half_long, ccz + az*half_long, hs_lvl)],
                       halfw + 0.8, 3.0)

def seat_houses(Hh, FR, squares):
    """ОТМЕТКА КАЖДОГО ДОМА — ПОСЛЕДНЕЙ ИЗ ПЛАНИРОВОК, и это обязательно:
    посчитанная раньше, она перестаёт соответствовать земле, которую потом
    перестелет полотно тракта и кайма площади.
    ПОСАДКА ПО МАКСИМУМУ ЗЕМЛИ ПОД ПЯТНОМ СТЕН, БЕЗ ПАДА (заказ владельца
    23.08: «дома почти все на треть первого этажа под землёй — это крит»).
    Минимум был честен ровно в одном («ни один угол не висит»), но выбирал
    нижнюю точку склона, и всё, что выше неё, лезло на кладку. Максимум
    переворачивает вопрос: висеть теперь может ВСЁ, и держит это не земля, а
    фундамент.
    КОНТРОЛЬНАЯ РУКА ИЗ ТОГО ЖЕ ГЕНЕРАТОРА: DFN_CITY_PAD=1 возвращает прежний
    пад-корыто (срез пятна до «пол - HOUSE_PAD_DROP» с каймой) — иначе «стало
    лучше» нечем доказать, кроме памяти. Обе руки из одного бинарника,
    отличается ровно эта развилка."""
    old_pad = env("PAD") == "1"
    for f in FR:
        ccx, ccz, w, d, yaw = f["x"], f["z"], f["w"], f["d"], f["yaw"]
        if old_pad:
            pts = rect_points(ccx, ccz, w, d, yaw, n=7)
            lvl = sorted(hh_at(Hh, px, pz) for px, pz in pts)[len(pts)//2]
            f["y"] = lvl - 0.05
            c = math.cos(math.radians(yaw))
            sn = math.sin(math.radians(yaw))
            ax, az = (c, -sn) if w >= d else (sn, c)
            half_long, halfw = max(w, d)/2, min(w, d)/2
            pad = house_floor(f["rec"], f["y"]) - HOUSE_PAD_DROP
            grade_corridor(Hh, [(ccx - ax*half_long, ccz - az*half_long, pad),
                                (ccx + ax*half_long, ccz + az*half_long, pad)],
                           halfw + 0.3, HOUSE_PAD_FEATHER, skip_rect=squares)
            continue
        ox, oz = house_origin(f["rec"], ccx, ccz, yaw)
        # РУСЛО ИЗ ПРОБ ИСКЛЮЧАЕТСЯ, И ЭТО НЕ ПОБЛАЖКА. Вырез дна делает
        # движок (apply_rivers), а дельты чертежа в коридоре гасит river_taper
        # — то есть поле высот там показывает берег, которого под мельницей
        # нет: её пятно 10.8x7.0 стоит НАД мельничным лотком. Лента,
        # доведённая до дна, перегородила бы русло каменной стеной в четыре с
        # половиной метра, а колесу нужна вода. Число печатается вслух в
        # check_footings.
        pts = [p for p in wall_pts(f["rec"], ox, oz, yaw) if not in_channel(*p)]
        if not pts:
            pts = wall_pts(f["rec"], ox, oz, yaw)
        gs = [hh_at(Hh, px, pz) for px, pz in pts]
        # НИЗ СТЕН — НАД САМОЙ ВЫСОКОЙ ЗЕМЛЁЙ ПЯТНА, а не над самой низкой.
        # Всё, что ниже, держит лента фундамента; она же уходит под грунт до
        # min - FOOT_BURY, поэтому висеть не может ни один её метр.
        f["y"] = max(gs) + FOOT_CLEAR
        f["foot_lo"] = min(gs)

# --- УЛИЧНЫЕ ОГНИ ([N14]: ночной город без единого огня) --------------------
# Гайд §10: огонь ставится У ВХОДОВ И В УЗЛАХ РЕШЕНИЙ — там, где игрок
# выбирает, куда идти, а не равномерной гирляндой вдоль улицы. Ни interior, ни
# room: жаровня горит НА улице, ей нечего ограничивать. И НИ ОДНОЙ ТЕНИ:
# кубовых слотов всего два (MAX_SHADOW_POINT_LIGHTS), и они по сюжету
# принадлежат очагам залов.

def road_normal(px, pz):
    """Единичная нормаль к ближайшей дороге. Считается от КАСАТЕЛЬНОЙ в
    ближайшей точке, а не от вектора «точка минус ближайшая»: у точки, лежащей
    НА осевой, второй вектор вырождается в ноль, а именно такие точки и
    отодвигаются."""
    best, tan = 1e9, (1.0, 0.0)
    for rd in PLAN["roads"]:
        for (x0, z0), (x1, z1) in zip(rd["pts"], rd["pts"][1:]):
            vx, vz = x1-x0, z1-z0
            L2 = vx*vx + vz*vz or 1e-9
            t = max(0.0, min(1.0, ((px-x0)*vx + (pz-z0)*vz) / L2))
            d = math.hypot(px - (x0+vx*t), pz - (z0+vz*t))
            if d < best:
                nl = math.hypot(vx, vz) or 1.0
                best, tan = d, (vx/nl, vz/nl)
    return (-tan[1], tan[0])

def flat_enough(qx, qz):
    """Жаровня стоит на РОВНОМ, а не на срезе террасы. Проба по своему же
    пятну (те же пять точек, что у sit): у жаровни восточных ворот земля
    падала на 0.45 м в пределах 0.4 м (48 гр.), и подошва, посаженная по
    минимуму, уходила в грунт на полметра."""
    gs = [q for q in (ground(qx+dx, qz+dz)
                      for dx, dz in ((0, 0), (0.4, 0.4), (0.4, -0.4),
                                     (-0.4, 0.4), (-0.4, -0.4)))
          if q is not None]
    return bool(gs) and (max(gs) - min(gs)) <= BRAZIER_FLAT

def brazier(px, pz, note):
    """ОТОДВИГ ДО ЧИСТОГО МЕСТА. dist_to_roads меряет до КРОМКИ полосы (минус
    полуширина), поэтому отрицательное значение — это «стоит на проезжей
    части». Столб там — ровно тот дефект, за который убирался колодец с
    главной улицы, так что не ставим вовсе, пока не отойдём.
    Жаровня жмётся к стене, как в жизни: радиус чистого места — это САМО ТЕЛО
    с ладонью зазора, а не пустая площадка (0.36 + ладонь = 0.70; прежняя 1.0
    была размером СТОЛБА, и на ней две жаровни из одиннадцати не находили
    места). Ищем поперёк улицы в обе стороны и с небольшим сдвигом вдоль неё:
    фасадные ряды стоят вплотную, и точный узел бывает занят крыльцом."""
    nx, nz = road_normal(px, pz)
    tx2, tz2 = -nz, nx
    found = None
    for along in (0.0, 2.5, -2.5, 5.0, -5.0):
        for step in (3.6, 4.4, 5.2, 6.0, 7.0):
            for sgn in (1.0, -1.0):
                qx = px + tx2*along + nx*sgn*step
                qz = pz + tz2*along + nz*sgn*step
                if dist_to_roads(qx, qz) >= 0.9 \
                        and flat_enough(qx, qz) \
                        and river_dist(qx, qz) >= BRAZIER_BANK \
                        and all(math.hypot(qx-ax, qz-az) >= BRAZIER_APART
                                for ax, az in BRAZIER_AT) \
                        and spot_free(qx, qz, BRAZIER_CLEAR):
                    found = (qx, qz)
                    break
            if found:
                break
        if found:
            break
    if not found:
        print(f"  жаровня {note}: чистого места рядом нет — не ставлю")
        return 0
    px, pz = found
    BRAZIER_AT.append((px, pz))
    # ПРОБА ЗЕМЛИ ПО СВОЕМУ ПЯТНУ. sit щупает центр и четыре угла на half и
    # берёт МИНИМУМ — при half=1.0 (полстолба) жаровня у моста хваталась за
    # срез берега и садилась на 23.58 при земле 25.52, то есть стояла в воде
    # по венчик чаши. Пятно у неё 0.72, значит half=0.4; а от самого среза
    # жаровня теперь держится подальше (BRAZIER_BANK).
    gy = sit(px, pz, 27.0, half=0.4)
    # ТЕЛОМ ЖАРОВНИ СТОЯЛА НЕСУЩАЯ КОЛОННА. furn-column — это столб, который в
    # доме держит балку: у него нет ни чаши, ни огня, и «жаровня» была колонной
    # с летящей над ней точкой света. Кузня-2 испекла настоящую:
    # furn-brazier-fire, ножка + восьмилепестковая чаша (замер: венчик
    # 2.05..2.28, дно чаши 2.10, угли 2.15, дрова 2.17, пламя 2.30..2.92).
    _bcx, _bcz, _bw, _bd, _ba, _bo = recipe_box("furn-brazier-fire.dfh")
    byaw = (int(px*7) % 40) - 20
    _bc = math.cos(math.radians(byaw))
    _bs = math.sin(math.radians(byaw))
    house("furn-brazier-fire.dfh",
          px - (_bcx*_bc + _bcz*_bs), gy, pz - (-_bcx*_bs + _bcz*_bc),
          byaw, "жаровня: " + note)
    lamp("brazier", px, gy + BRAZIER_LIGHT, pz, "жаровня: " + note)
    return 1

def street_fire():
    """Огонь у ворот, в изломах процессионной оси и в точках паспорта."""
    n = 0
    for gt in PLAN["gates"]:
        gx, gz = gt["pos"]
        # пара по флангам створа: нормаль к ближайшей дороге
        qx, qz = nearest_on_roads(gx, gz)
        vx, vz = gx - qx, gz - qz
        if math.hypot(vx, vz) < 0.2:
            vx, vz = 1.0, 0.0
        nl = math.hypot(vx, vz)
        # нормаль к дороге = поперёк её касательной; берём перпендикуляр к (v)
        tx, tz = -vz/nl, vx/nl
        for sgn in (1.0, -1.0):
            n += brazier(gx + tx*sgn*CITY.FIRE_GATE_OFF,
                         gz + tz*sgn*CITY.FIRE_GATE_OFF, gt["name"])
    # узлы главной улицы: изломы осевой — там, где вид меняется
    axis = PLAN["roads"][AXIS_ROAD]["pts"]
    for k in AXIS_FIRE_NODES:
        ax0, az0 = axis[k]
        bx0, bz0 = axis[k-1]
        ux0, uz0 = ax0-bx0, az0-bz0
        nl = math.hypot(ux0, uz0) or 1.0
        n += brazier(ax0 - uz0/nl*CITY.FIRE_AXIS_OFF,
                     az0 + ux0/nl*CITY.FIRE_AXIS_OFF, "главная улица")
    for sp in CITY.FIRE_SPOTS:
        ref = plan_ref(sp["ref"])
        ax0 = ref[sp["ix"]][0] if "ix" in sp else ref[0]
        az0 = ref[sp["iz"]][1] if "iz" in sp else ref[1]
        n += brazier(ax0 + sp["d"][0], az0 + sp["d"][1], sp["note"])
    return n

def plan_flora(Hh):
    """Поляна с дубом, огороды и одиночные деревья чертежа."""
    og = PLAN["oak_glade"]
    oak_rec, oak_yaw = CITY.GLADE_OAK
    oy = sit(og["oak"][0], og["oak"][1], 26.0, half=3)
    place(oak_rec, og["oak"][0], oy, og["oak"][1], oak_yaw, "дуб поляны")
    opts = TREE[CITY.GLADE_TREES]
    for i, (tx, tz) in enumerate(og["trees"]):
        ty = sit(tx, tz, 26.0, half=1.5)
        place(opts[i % len(opts)], tx, ty, tz, (i * 61) % 360)
    for i, (gx, gz) in enumerate(PLAN["gardens"]):
        gy = sit(gx, gz, 33.0, half=1.5)
        for k in (0, 1):
            house(CITY.GARDEN_REC, gx - 0.5 + k * 1.6, gy, gz - 1.2,
                  (i*23) % 20 - 10, "огород")
    for i, t in enumerate(PLAN["trees"]):
        opts = TREE.get(t["kind"], TREE["bush"])
        ty = sit(t["x"], t["z"], 25.0, half=1.0)
        place(opts[i % len(opts)], t["x"], ty, t["z"], (i * 47) % 360)

def lay_roads():
    """ДОРОГИ — ТРОПАМИ РЕЛЬЕФА, НЕСУЩИМИ МАТЕРИАЛ. Приказ владельца 22.08:
    «тропинки опять плитами кладутся, а не тропинкой каменной». Движок
    (fde9a7b) принимает третьим числом строки path класс полотна путевого
    атласа, и шейдер рисует его САМОЙ ЗЕМЛЁЙ — без настила, без швов и без
    «губы» над грунтом. Каменный тракт больше не набирается штучными плитами:
    он становится свойством земли, как и был задуман."""
    for rd in PLAN["roads"]:
        lay(rd["pts"], max(0.8, rd["w"] / 2), path_class(rd),
            f"тракт {rd['mat']}")

def lay_walkways():
    """ДОРОЖКИ ОТ ДВЕРЕЙ — ТЕМ ЖЕ ПОЛОТНОМ, ЧТО УЛИЦА, а не своим камнем.
    Прежде здесь стояла константа cls = 3 (тёсаная плита), и она была ГЛАВНОЙ
    ПРИЧИНОЙ ЛОСКУТОВ: класс побеждает последний (движок), радиус класса на
    0.75 м шире полуширины, дорожки кладутся ПОСЛЕДНИМИ — значит каждая из 23
    штамповала пятно чужого камня радиусом 2.35 м поверх улицы, к которой
    подходила. Самая короткая (1.10 м) не могла прочитаться мощением в
    принципе: у штриха короче 2*FADE_M нет ни метра полной полки.
    ДОРОЖКА К ДВЕРИ — ЭТО НЕ ОТДЕЛЬНОЕ ПОКРЫТИЕ, ЭТО ПОСЛЕДНИЕ ДВА МЕТРА ТОЙ
    ЖЕ УЛИЦЫ. Класс берётся у полотна В ТОЧКЕ ВЫХОДА НА УЛИЦУ, тем же
    правилом, каким его прочтёт движок."""
    fab_streets = Fabric(PATHS)
    n_clip, n_island = 0, 0
    for (dx0, dz0, dx1, dz1) in WALKWAYS:
        cut = clip_walk(dx0, dz0, dx1, dz1, WALK_HALF + FADE_M)
        if cut is None:
            n_clip += 1
            continue
        if abs(cut[2]-dx1) > 1e-6 or abs(cut[3]-dz1) > 1e-6:
            n_clip += 1
        dx0, dz0, dx1, dz1 = cut
        street = fab_streets.class_at(dx1, dz1)
        if street is None:
            street = (CLS_PAVED if point_in_poly(dx1, dz1, PLAN["wall"])
                      else CLS_TRACK)
        # СТРАХОВКА, А НЕ ОСНОВНОЙ МЕХАНИЗМ: пока класс наследуется, островом
        # дорожка стать не может. Порог остаётся включённым, чтобы следующая
        # правка, вернувшая сюда константу, упёрлась в него, а не в кадр.
        if math.hypot(dx1-dx0, dz1-dz0) < ISLAND_MIN_M:
            n_island += 1
        lay([(round(dx0, 2), round(dz0, 2)), (round(dx1, 2), round(dz1, 2))],
            WALK_HALF, street, "дорожка от двери")
    if n_clip:
        print(f"полотно у стены: {n_clip} дорожек укорочено/снято (кладка)")
    if n_island:
        print(f"дорожки короче {ISLAND_MIN_M:.1f} м: {n_island} — класс взят "
              f"у улицы (островом такая длина не читается)")

def fabric_out():
    """PATHS -> строки .relief плюс две выборки для приёмок."""
    relief_paths, FABRIC, HARD = [], [], []
    flat_m, n_flat = 0.0, 0
    for pts, half, soft, cls, _nm in PATHS:
        body = "\n".join(f"pp {x:g} {z:g}" for x, z in pts)
        relief_paths.append(f"path {half:g} {soft:.4f} {cls}\n{body}")
        HARD.append((pts, half, cls))
        FABRIC.append((pts, half, soft))
        flat = half * (1.0 - soft)
        flat_m += flat
        n_flat += 1 if flat > 0.01 else 0
    print(f"полотно: {len(PATHS)} лент, плоская вершина у {n_flat} из "
          f"{len(PATHS)} (средняя полуполка {flat_m/max(1,len(PATHS)):.2f} м; "
          f"до правки была 0.00 у ВСЕХ — soft писался метрами, читался долей)")
    return relief_paths, FABRIC, HARD

def river_terrain(WLEV):
    """Секции [river] сцены. ЗАМЕР НАТУРАЛЬНОЙ ЗЕМЛИ ИДЁТ БЕЗ РЕКИ
    (DFN_CITY_BARE=1): иначе в nat уже сидит вырез старого русла, и дельта у
    берега считается от дна, а не от земли. Дельты в коридоре гасятся
    river_taper, поэтому вырез там делает только движок — от отметки воды,
    снятой с берегов."""
    terrain = []
    if env("BARE") == "1":
        return terrain
    for ri, riv in enumerate(RIVERS):
        rpts = "\n".join(f"point = {x} {z} {WLEV[ri][i]:.2f}"
                         for i, (x, z) in enumerate(riv["pts"]))
        terrain.append(f"[river]\nwidth_m = {riv['half_w']*2:.1f}\n"
                       f"depth_m = {RIVER_DEPTH:.1f}\nbank_m = {RIVER_BANK_M:.1f}\n"
                       f"note = река плана: вода по земле, дно на {RIVER_DEPTH:.1f} м ниже\n"
                       f"{rpts}\n")
    return terrain

def acceptance(PLAN_H, FABRIC, HARD):
    """Все приёмки конвейера одной строкой вызова: они спрашивают про РАЗНЫЕ
    предметы (полотно у кладки, тела в кладке, ориентиры, фундамент, пол,
    расстановка, мощение, связность оси, полотно), и порядок между ними
    свободный — но собранные вместе они читаются как один отчёт."""
    if COLUMN_SHORT:
        need = {}
        for rec, ln, best, nm in COLUMN_SHORT:
            need.setdefault(round(ln, 3), [0, rec, best])
            need[round(ln, 3)][0] += 1
        print("СТОЛБЫ, КОТОРЫМ НЕЧЕМ ДОСТАТЬ ДО БАЛКИ (не поставлены):")
        for ln, (n, rec, best) in sorted(need.items()):
            print(f"  {rec}: нужна длина {ln:.3f} м, в выпечке ближайшая "
                  f"{best:.3f} — {n} шт.")
    check_ring_fabric(FABRIC)
    check_ring_bodies()
    check_landmarks()
    check_footings()
    fp = env("DUMP_FOOTPRINTS")
    if fp:
        dump_footprints(fp)
    check_floors()
    check_layout()
    check_paving()
    check_axis(PLAN_H, HARD)
    check_fabric(PATHS)

def main(city="whiterun"):
    """ОРКЕСТРАТОР. Порядок строк ниже — контракт: он один раз выведен из
    двух десятков дефектов, каждый из которых был не «неверной геометрией», а
    НЕВЕРНОЙ ОЧЕРЁДНОСТЬЮ (площадь, спланированная раньше улицы; пад,
    затёртый полотном; убранство сквера, поставленное раньше дворов)."""
    load_city(city)
    PLAN_H = build_plan_heights()
    PLAN_H_REF[0] = PLAN_H
    WLEV = river_levels(PLAN_H)
    bridge = bridge_setup(WLEV)

    # 1. ПОЛОТНО КАМЕННЫХ ТРАКТОВ. Мостовая — жёсткая плита, и поперечный
    # уклон вместе с кочками под пятном не даёт положить её нигде, кроме
    # случайно ровных мест (первая раскладка: 35% покрытия, разрыв 33 м).
    # Полоса улицы планируется по СГЛАЖЕННОМУ продольному профилю: поперечный
    # уклон уходит в ноль, продольный остаётся честным уклоном горы.
    grade_roads(PLAN_H)
    # 2. СТЕНА СТАВИТСЯ ДО РАССТАНОВКИ, А НЕ ПОСЛЕ — И ЭТО ЕДИНСТВЕННЫЙ СПОСОБ
    # ОТОДВИНУТЬ ДОМ ОТ НАСТОЯЩЕЙ КЛАДКИ, А НЕ ОТ ЛИНИИ ЧЕРТЕЖА. Кольцо
    # кладётся цепью гнутых кусков, и цепь отходит от кривой чертежа до 0.68 м
    # ТУДА И ОБРАТНО; отодвиг, считавший запас от кривой, обязан был
    # закладывать весь этот отход в порог — а в юго-восточном коридоре, где
    # между полосой главной улицы и стеной на тело кузницы остаётся полтора
    # метра свободы, такого порога просто нет. wall_ring не зависит ни от чего
    # в main: землю она берёт у дампа прошлого прохода.
    wall_ring()
    # 3. ТЕЛА ГОРОДА, РАЗВЕДЁННЫЕ МЕЖДУ СОБОЙ И ОТОДВИНУТЫЕ ОТ ПОЛОС.
    FR = resolve_frames()
    grade_big_pads(PLAN_H, FR)
    # 4. ПЛОЩАДКИ МЕСТ. ПЛОЩАДЬ ГОВОРИТ ПОСЛЕДНЕЙ: главная улица проходит
    # ЧЕРЕЗ рынок, и полотно тракта, спланированное после площади, поднимало её
    # кромку на 1.35 м — плита с прилавками зависала над землёй, бот вставал на
    # неё и застревал (char-трасса: (119.97, 29.11, 147.57), 5 с без смещения).
    SQUARES_RECT = [r for r in (place_grade(pl, PLAN_H) for pl in PLACES)
                    if r is not None]
    # ...и полотно трактов кладётся ПОВЕРХ их каймы, минуя сами прямоугольники:
    # кайма площади ложилась на улицу и снова делала её волнистой (покрытие
    # подхода к рынку падало с 46 до 28%). Внутри места — место, снаружи —
    # улица; обе плоские, стык на кромке.
    grade_roads(PLAN_H, skip_rect=SQUARES_RECT)
    # 5. ПОДХОДЫ МОСТА — ПОСЛЕ ДОРОГ, А НЕ ДО НИХ. Здесь была причина всего
    # перекоса: подходы планировались первым же делом, а потом grade_roads
    # заново стелила ту же землю по профилю тракта и затирала их. Западный
    # торец оказывался на 0.99 м НИЖЕ земли, восточный на 0.18 ВЫШЕ, бот на
    # обратном пути сходил с настила и вставал на тридцать секунд. Мост стоит
    # на реке, а не на профиле улицы, поэтому у русла последнее слово за ним.
    grade_bridge(PLAN_H, bridge)
    # 6. ОТМЕТКИ ДОМОВ — ПОСЛЕДНИМИ ИЗ ПЛАНИРОВОК, и постройка следом.
    seat_houses(PLAN_H, FR, SQUARES_RECT)
    n_foot = n_stoop = 0
    for f in FR:
        a, b = put_house(f)
        n_foot += a
        n_stoop += b
    # 7. МЕСТА: ПОЛ, ЯДРО, ЖИЗНЬ.
    for pl in PLACES:
        place_floor(pl, PLAN_H)
        place_life(pl, PLAN_H, place_core(pl, PLAN_H))
    # 8. УЛИЧНЫЙ ОГОНЬ И МОСТ.
    n_fire = street_fire()
    put_bridge(PLAN_H, bridge)
    # 9. ЯДРА-ДЕРЕВЬЯ МЕСТ И ЗЕЛЕНЬ ЧЕРТЕЖА.
    for pl in PLACES:
        place_tree(pl, PLAN_H)
    plan_flora(PLAN_H)
    # 10. ДВОРЫ — вторым проходом, когда все тела уже известны.
    n_forge = smithy_yard()
    n_yard = yards()
    # 11. УБРАНСТВО МЕСТ — ПОСЛЕ дворов: у сквера и парадного двора места мало
    # (замер: до дома 0.38 м), а поленница соседа, поставленная ПОЗЖЕ, не была
    # бы видна проверке. Кто раньше, тот и занимает; убранству точки притяжения
    # место нужнее, чем ещё одной бочке.
    for pl in PLACES:
        place_decor(pl, PLAN_H, FR)
    # 12. РИТМ УЛИЧНОГО ОГНЯ, ОЗЕЛЕНЕНИЕ, ОГОНЬ У ДВЕРЕЙ.
    street_lamps(PLAN_H)
    greenery(PLAN_H)
    door_lights(PLAN_H, FR)
    # 13. ПОСТРОЕННЫЕ ПЕРЕПАДЫ МЕСТ (марш и подпорная кромка).
    n_step, n_kerb = 0, 0
    for pl in PLACES:
        a, b = place_terrace(pl, PLAN_H)
        n_step += a
        n_kerb += b
    # 14. ПОЛОТНО: реки в сцену, тракты и дорожки в рельеф.
    terrain = river_terrain(WLEV)
    lay_roads()
    lay_walkways()
    relief_paths, FABRIC, HARD = fabric_out()
    n_kerb = kerbs_along(PATHS)

    # 15. ВЫПУСК.
    write_scene(f"assets/scenes/{OUT}.scene", city_header(), terrain,
                P, H, LIGHTS)
    # ЗЕМЛЯ ГОРОДА КЛАССАМИ — перед записью рельефа, когда крыльца и
    # притяжения уже расставлены: ореол вытоптанного считается от НИХ.
    paint_ground(PLAN_H)
    write_relief(f"assets/scenes/{OUT}.relief", PLAN_H, relief_paths)
    write_map(f"assets/maps/houses/{OUT}.map")
    # --- ВТОРОЙ ПРОХОД ЗАМЫКАЕТСЯ ЗДЕСЬ, А НЕ ВНЕШНИМ ПРИБОРОМ --------------
    # Схема «gen -> dump_heights -> gen» описана в шапке с 21.08, но ПРИБОРА,
    # который пишет дамп высот, в дереве НЕ БЫЛО НИ ОДНОГО: дамп в /tmp остался
    # от разовой руки давней сессии и с тех пор был СНИМКОМ. Любой сдвиг дома в
    # чертеже делал его ложью, а check_floors, который меряет ИМЕННО дамп,
    # начинал ругаться на дома, стоящие верно. Поле этого прохода И ЕСТЬ та
    # земля, которая уйдёт в relief, поэтому второй проход замыкается одной
    # дверью: DFN_CITY_WRITE_HEIGHTS=<файл>.
    wh = env("WRITE_HEIGHTS")
    if wh:
        with open(wh, "w", encoding="utf-8") as f:
            f.write(f"# {OUT} ground heights, row per z 0..{LAST}, "
                    f"col per x 0..{LAST}, step 1m\n")
            for gz in range(SPAN):
                f.write(" ".join(f"{PLAN_H[gz][gx]:.2f}" for gx in range(SPAN))
                        + "\n")
        print(f"поле высот этого прохода записано в {wh}")
    acceptance(PLAN_H, FABRIC, HARD)
    print(f"{OUT}: {len(H)} построек, {len(P)} расстановок, "
          f"{len(LIGHTS)} огней ({n_fire} уличных), {n_yard} дворовых "
          f"(+{n_forge} кузнечных), "
          f"{len(terrain)} terrain-блоков, {len(relief_paths)} троп, "
          f"терраса: {n_step} марш + {n_kerb} отрезков кромки, "
          f"фундамент: {n_foot} отрезков ленты + {n_stoop} крылец")


def cli(argv):
    """`python3 tools/gen_city.py <город>`. Без имени — список паспортов:
    молча собрать «какой-нибудь» город хуже, чем не собрать никакой."""
    here = os.path.join(os.path.dirname(os.path.abspath(__file__)), "cities")
    have = sorted(f[:-3] for f in os.listdir(here)
                  if f.endswith(".py") and not f.startswith("_"))
    if len(argv) != 2 or argv[1] not in have:
        if len(argv) > 1:
            print(f"паспорта «{argv[1]}» нет в tools/cities")
        print("python3 tools/gen_city.py <город>; паспорта: "
              + ", ".join(have))
        return 2
    main(argv[1])
    return 0

if __name__ == "__main__":
    sys.exit(cli(sys.argv))
